INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u5-C1','kor',6,2,'u5',1,'음성 언어와 문자 언어 — 음성 언어는 음성으로 나타내는 말로 듣는 사람 앞에서 바로 전해지고, 문자 언어는 글자로 나타내는 말로 적어 두면 다시 볼 수 있으며, 두 언어는 등수를 매기는 사이가 아니라 알맞은 곳이 서로 다를 뿐이다',ARRAY['[6국04-01]']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u5-C2','kor',6,2,'u5',1,'특성은 규칙이 아니라 기본 성질 — 말은 보통 그 자리에서 사라지고 글은 보통 오래 남지만 매체에 따라 달라져(녹음한 말은 남고, 빠르게 지나가는 대화 글·잠깐 뜨는 알림·넘기면 없어지는 자막은 흘러감) 「언제나」로 외우지 않고 이 매체에서는 어떻게 되는지를 그때그때 살핀다',ARRAY['[6국04-01]']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u5-C3','kor',6,2,'u5',1,'매체 자료의 세 갈래 — 인쇄 매체는 문자 언어를 바탕으로 표·그림·사진을, 음성 매체는 음성 언어를 바탕으로 소리·음악을, 영상 매체는 음성 언어·문자 언어·그림·소리·움직임을 어울러 쓰며, 더 나은 매체는 없고 전하려는 내용과 받는 사람에 따라 알맞은 매체가 달라진다',ARRAY['[6국04-01]']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u5-C4','kor',6,2,'u5',2,'문자 언어의 표현 특성 — 적은 내용이 그대로 남아 필요할 때 다시 볼 수 있고, 여러 사람이 똑같은 내용을 정확하게 나누어 가지며, 글자의 크기·굵기·문장 부호·줄 나눔으로 중요한 곳을 눈에 보이게 하고, 천천히 생각하며 읽고 쓴 뒤에 고칠 수 있다',ARRAY['[6국04-01]']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u5-C5','kor',6,2,'u5',2,'음성 언어의 표현 특성 — 그 자리에서 바로 전해지고 말이 끝나면 소리가 사라지며, 목소리의 크기·억양·속도·잠깐 쉬기로 감정과 의도를 함께 전하고, 듣는 사람의 반응을 보며 말을 바꾸거나 다시 설명하고, 모르는 곳을 그 자리에서 되물을 수 있다',ARRAY['[6국04-01]']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u5-C6','kor',6,2,'u5',2,'그 자리에 알맞은 방법 고르기 — 어느 쪽이 더 나은지가 아니라 전하려는 내용과 받는 사람의 처지를 함께 보아, 차례가 여럿이거나 다시 봐야 하면 글, 마음을 생생하게 전하거나 바로 주고받아야 하면 말, 어렵거나 헷갈리면 둘을 함께 쓰며, 고른 까닭을 언어의 특성과 이어 말하는 데까지가 답이다',ARRAY['[6국04-01]']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u5-C7','kor',6,2,'u5',2,'두 언어를 함께 써 서로 보완하기 — 말로 설명하면 생생하지만 놓치면 되돌릴 수 없고 같은 내용을 글로도 보여 주면 놓친 곳을 다시 확인할 수 있어, 어렵거나 헷갈리는 내용일수록 말과 글을 함께 쓴다',ARRAY['[6국04-01]']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u5-C8','kor',6,2,'u5',4,'영상 매체를 이루는 요소 — 해설하는 말(흐름을 이어 줌)·자막(꼭 남겨야 할 내용을 다시 보여 줌)·장면과 움직임(어떤 일이 벌어지는지 한눈에)·소리와 음악(어디를 눈여겨볼지 알림)이 함께 내용을 전하며, 올린 날짜·만든 사람 이름·본 사람 수·화면 크기는 뜻을 나르는 요소가 아니다',ARRAY['[6국04-01]']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u5-C9','kor',6,2,'u5',4,'말과 자막의 보완 · 강조 방법 — 해설하는 말은 흐름을 이어 주지만 놓치면 되돌릴 수 없어, 어렵거나 헷갈리는 내용은 자막으로 정리해 눈으로 다시 확인하게 하고, 자막은 색·크기·모양으로, 말은 음악과 효과음으로 중요한 곳을 강조한다',ARRAY['[6국04-01]']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u5-C10','kor',6,2,'u5',4,'표현 효과는 무엇을 돕는가로 본다 — 자막을 화면 가득 채우거나 음악을 계속 크게 깔거나 장면을 쉴 새 없이 바꾸면 무엇이 중요한지 흐려지고, 꼭 남길 곳에만 자막을 두고 중요한 곳에서 소리를 바꾸면 또렷해지므로, 표현 효과는 요소의 개수가 아니라 그 요소가 무엇을 돕는가로 본다',ARRAY['[6국04-01]']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u5-C11','kor',6,2,'u5',5,'장면마다 방법이 다른 까닭 — 같은 영상 안에서도 그 장면에서 해야 할 일이 달라 쓰는 방법이 다르다: 무엇을 다룰지 알릴 때 자막으로 제목, 처음 듣는 낱말을 정확히 남길 때 말과 자막을 함께, 느낌을 바꿀 때 음악의 빠르기를 바꾼다',ARRAY['[6국04-01]']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u5-C12','kor',6,2,'u5',5,'영상 감상의 세 걸음 — 찾기(이 장면에 말·글·그림·소리 가운데 무엇이 쓰였는가)·잇기(그것이 이해를 무엇으로 돕는가)·말하기(나는 어떻게 느꼈고 까닭은 무엇인가)이며, 어느 장면이 인상 깊었는가 같은 느낌은 사람마다 다를 수 있지만 무엇이 쓰였고 무엇을 돕는가는 영상 안에서 함께 확인할 수 있으므로, 감상은 좋았다·별로였다에서 멈추지 않고 어떤 표현 때문인지 까닭을 함께 말한다',ARRAY['[6국04-01]']::text[],12) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u5-C14','kor',6,2,'u5',7,'독자를 고려한다는 것 — 글을 읽는 사람(독자)의 처지에서 헤아려 보는 것으로, 독자의 흥미·배경지식·수준(알아들을 수 있는 낱말과 표현)·글을 읽는 매체를 살피고, 독자가 겪는 어려움과 독자가 할 수 있는 일까지 보이게 쓴다 — 같은 내용이라도 누가 읽느냐에 따라 낱말도 차례도 달라진다',ARRAY['[6국03-04]']::text[],14) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u5-C15','kor',6,2,'u5',7,'독자 고려는 비위 맞추기가 아니다 — 독자가 좋아할 내용만 고르거나 어려운 이야기를 빼 버리거나 낱말만 쉽게 바꾸면 끝나는 것이 아니라, 전하려는 것은 그대로 두고 독자가 알아들을 수 있게 짜는 것이며, 말하고 싶은 것을 줄이는 일이 아니라 그것이 독자에게 닿게 하는 일이다',ARRAY['[6국03-04]']::text[],15) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u5-C16','kor',6,2,'u5',7,'글 쓰는 세 단계와 고쳐 쓰기 — 계획 세우기(누가 읽을지·무엇을 왜 쓸지)·내용 생성하고 조직하기(쓸 거리를 모아 차례 짜기)·글 쓰고 고쳐 쓰기를 거치며 단계마다 독자를 다시 떠올리고, 고쳐 쓸 때에는 독자의 수준에 맞는가·주제가 드러나는가·낱말과 문장에 잘못이 없는가·오해할 만한 표현이 없는가를 본다 — 고쳐 쓰기는 틀린 곳을 벌하는 일이 아니라 독자에게 더 잘 닿게 하는 일',ARRAY['[6국03-04]']::text[],16) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u5-C17','kor',6,2,'u5',7,'글에 자료를 넣는 까닭 — 글만으로 잘 전해지지 않을 때 수를 견줄 때는 표나 그래프, 모습이나 차례는 사진이나 그림, 할 일은 기호와 줄 나눔을 함께 놓으며, 자료는 개수를 채우려고가 아니라 독자의 이해를 도우려고 넣고 글에서 말한 내용과 이어지는 것만 고른다',ARRAY['[6국03-04]']::text[],17) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u5-C18','kor',6,2,'u5',9,'기사문의 특성 — 어떤 사실이나 사건을 여러 사람에게 알리는 글로, 직접 보고 듣고 조사한 내용을, 느낌이 아니라 사실로, 빠르고 정확하게, 객관적이고 간결한 표현으로 쓰며, 읽는 사람이 사실이라고 믿고 읽기 때문에 지어낼 수 없다',ARRAY['[6국03-04]']::text[],18) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u5-C19','kor',6,2,'u5',9,'기사문의 짜임과 육하원칙 — 제목(표제는 내용을 간결하게 드러내고 부제는 필요할 때 표제를 보충)·전문(주요 내용을 누가·언제·어디에서·무엇을·어떻게·왜의 육하원칙으로 앞에서 요약)·본문(주된 내용을 자세히)으로 이루어진다',ARRAY['[6국03-04]']::text[],19) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u5-C20','kor',6,2,'u5',9,'확인한 사실과 생각 가르기 — 직접 세어 본 수·직접 들은 말·눈으로 확인한 일·본인에게 물어 확인한 계획은 쓰고, 확인하지 못한 소문·그럴 것 같아 지어낸 숫자는 쓰지 않으며, 「모두 기뻐했다」처럼 쓴 사람의 생각을 사실처럼 쓰지 않고 생각을 쓰려면 누구의 생각인지 밝힌다',ARRAY['[6국03-04]']::text[],20) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u5-C21','kor',6,2,'u5',9,'기사문 계획 · 자료 출처 · 제목 — 독자의 특성·기삿거리(독자가 관심 있고 내가 가서 확인할 수 있는 일)·필요한 자료·자료 수집 방법을 정한 뒤 개요를 짜고, 사진·표 같은 자료는 출처(내가 조사했으면 언제·누구에게·어떻게)를 밝히며, 제목은 내용을 담고 읽고 싶어지게 쓰되 본문에 없는 말로 부풀리지 않는다',ARRAY['[6국03-04]']::text[],21) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u5-C22','kor',6,2,'u5',12,'편지의 짜임과 독자 — 받는 사람·첫인사(안부)·하고 싶은 말(쓴 목적)·끝인사·쓴 날짜와 보내는 사람의 다섯 부분으로 이루어지며, 독자가 받는 사람 한 사람이라 알맞은 높임말을 쓰고 목적이 뚜렷이 드러나게 하고 받는 사람이 모를 만한 일은 앞뒤를 설명해 준다',ARRAY['[6국03-04]']::text[],22) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u5-C23','kor',6,2,'u5',12,'전하려는 마음에 맞는 내용 — 고마울 때는 무엇이 고마웠는지 그 일을 콕 집어, 미안할 때는 변명보다 무엇이 잘못이었는지를 먼저, 축하할 때는 그 사람이 애쓴 과정을 함께, 힘을 내라고 할 때는 섣부른 충고보다 곁에 있다는 말을 쓴다',ARRAY['[6국03-04]']::text[],23) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u5-C24','kor',6,2,'u5',12,'편지의 매체 고르기와 건네기 — 손 편지(글씨와 종이가 남아 오래 간직)·영상 편지(목소리와 표정이 생생)·누리집이나 게시판 글(여러 사람이 함께 봄) 가운데 전하려는 마음과 받는 사람의 처지에 맞는 것을 고르며(매체에 등수 없음), 정말 전하고 싶은 사람에게 쓰고 실제로 건네 반응을 보아야 편지가 완성된다',ARRAY['[6국03-04]']::text[],24) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u5-C25','kor',6,2,'u5',12,'겹받침이 있는 낱말의 발음 — 받침에 자음자가 두 개 있는 겹받침은 받침에서 한 번에 한 소리만 낼 수 있어 뒤에 자음자가 오거나 낱말이 끝나면 하나만 소리 나고(붉다[북따]·얇다[얄따]·짧다[짤따]), 뒤에 모음이 오면 두 소리가 다 나며 뒤엣것이 뒷글자로 넘어간다(붉어요[불거요]·얇아요[얄바요]) (기초 다지기)',ARRAY['기초 다지기 — 겹받침 발음(단원 성취기준 표기 없음)']::text[],25) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u5-C26','kor',6,2,'u5',1,'글을 쓴 경험과 기사문을 읽은 경험 떠올리기(준비) — 편지·초대장을 쓸 때 친근한 표현·쉬운 표현으로 독자에게 잘 전달하려 한 경험 · 신문·과학 잡지·온라인 매체에서 기사문을 읽은 경험 · 이 단원에서 배울 두 부분(언어의 표현 효과 이해하기 / 독자를 고려하며 글 쓰기)',ARRAY['[6국03-04]']::text[],26) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u5-C27','kor',6,2,'u5',2,'「‘작가와의 만남’ 행사 안내」로 문자 언어의 특성 알기 — 글자로 전해 눈으로 읽고 나중에 다시 볼 수 있음 · 제목은 큰 글자, 중요한 내용은 글자 크기·굵기·따옴표로 강조해 어떤 정보가 중요한지 금방 파악 · 직접 만나지 않아도 의사소통 · 천천히 생각하며 이해 · 기록한 내용은 오랫동안 보존',ARRAY['[6국04-01]']::text[],27) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u5-C28','kor',6,2,'u5',2,'「선생님의 안내 말씀」으로 음성 언어의 특성 알기 — 중요한 내용(재능 발표회 시작 시각·장소)에서 목소리를 크고 또박또박하게 · 목소리의 크기나 억양으로 감정과 의도를 전달 · 실감 나게 전달 · 말이 끝나면서 소리가 사라져 집중해서 듣고 메모해야 함',ARRAY['[6국04-01]']::text[],28) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u5-C29','kor',6,2,'u5',4,'「아동 안전 ― 운전자가 보호자 ―」의 표현 방법과 효과 — 주제(아동의 안전을 위해 운전하는 사람이 차량 안전을 생각해야 함) · 만든 까닭(공공의 이익) · 동영상·대사·자막·음악 · 음성 언어 「도로에서는 운전자가 보호자입니다.」와 문자 언어 「운전면허는 보행자 보호 면허」 · 어린이 보호 구역 표지판과 자막 · 아이의 말과 장면',ARRAY['[6국04-01]']::text[],29) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u5-C30','kor',6,2,'u5',5,'「수월봉 화산 쇄설층」 내용 알기 — 지하에서 올라온 마그마가 지표의 물과 만나 폭발한 뒤 화산재와 화산 쇄설물들이 쌓여 만들어짐 · 화산탄이 일정한 각도인 것을 보고 분화구의 중심을 바다 한가운데라고 추측함 · 장면 1~5의 표현(파도 소리와 음악·해설자의 말을 문자로·긴장감 있는 음악·글과 그림·음성 없는 자막)',ARRAY['[6국04-01]']::text[],30) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u5-C31','kor',6,2,'u5',5,'「수월봉 화산 쇄설층」 낱말 알기 — 지표(지구의 표면) · 분화구(화산 꼭대기에 생긴 용암과 화산 가스 따위의 분출구) · 화산재(화산에서 나온 용암의 부스러기 가운데 크기가 작은 알갱이) · 지층(알갱이의 크기, 색, 성분 따위가 서로 달라서 위아래의 퇴적암과 구분되는 퇴적암체) · 쇄설층(암석 부스러기가 쌓여 형성된 지층)',ARRAY['[6국04-01]']::text[],31) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u5-C32','kor',6,2,'u5',7,'「운동장 놀이의 좋은 점」과 「그림자 술래잡기」 견주기 — 같은 운동장 놀이 소재 · 앞 글은 글쓴이가 조사한 내용에만 집중해 독자의 관심사(놀이 방법)와 어긋나고 어려운 낱말(심폐 지구력)이 있어 독자가 어려워함 · 다시 쓴 글은 쉬운 표현으로 독자가 찾던 놀이 방법을 써서 반응이 달라짐(쓰는 사람이 독자를 고려함)',ARRAY['[6국03-04]']::text[],32) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u5-C33','kor',6,2,'u5',7,'「계단을 안전하게 이용합시다」에서 독자를 고려한 점 — 독자(○○초등학교 학생들)의 특성(그림이나 그래프가 있을 때 더 쉽게 이해) 조사 · 학생 50명 조사 그래프(있다 40명·거의 없다 6명·없다 4명)로 한눈에 · 별표 기호로 안전 수칙(뛰지 말고 천천히·난간 잡기·앞을 잘 보기)을 나누어 기억하기 쉽게 · 학생들이 관심 많은 안전한 학교생활',ARRAY['[6국03-04]']::text[],33) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u5-C34','kor',6,2,'u5',9,'「희망초등학교, ‘전문가와 함께 하는 예술 진로 캠프’ 개최」 내용 알기 — 표제·부제(다양한 예술 직업의 세계를 탐구하고 꿈을 키워요)·전문(1~6학년, 11월 8일부터 9일까지 이틀간, 예술 직업 이해·소질과 적성)·본문(1~2학년 미술실 그림 작가 · 3~4학년 시청각실 성우 · 5~6학년 실과 실습실 특수 분장 · 학생 소감) · 누가 언제 어디에서 무슨 일',ARRAY['[6국03-04]']::text[],34) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u5-C35','kor',6,2,'u5',12,'목적에 따른 편지의 종류와 영상 편지 — 소식은 안부 편지 · 초대는 초대 편지 · 미안한 마음은 사과 편지 · 기쁜 일은 축하 편지 · 힘든 일은 위로 편지 · 감사한 마음은 감사 편지 · 정보 전달은 알림 편지 · 영상 편지 만들기(편지지에 쓰기 → 촬영 도구 준비 → 촬영 → 확인하고 편집 → 전달)',ARRAY['[6국03-04]']::text[],35) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u5-X01','kor',6,'u5',ARRAY['K6-2-u5-C1']::text[],'음성 언어와 문자 언어의 뜻을 서로 바꾸어 알거나, 글로 옮겨 적은 말을 음성 언어로 여긴다','음성으로? 글자로?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u5-X02','kor',6,'u5',ARRAY['K6-2-u5-C2','K6-2-u5-C4','K6-2-u5-C5']::text[],'「말은 언제나 사라진다 · 글은 언제나 남는다」처럼 특성을 어떤 경우에도 맞는 규칙으로 외워, 녹음한 말이나 흘러가는 글을 설명하지 못한다','보통은 그렇지만 매체에 따라 달라져요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u5-X03','kor',6,'u5',ARRAY['K6-2-u5-C1','K6-2-u5-C3','K6-2-u5-C24']::text[],'글이 말보다, 영상이 글보다 낫다처럼 언어나 매체에 등수를 매긴다','더 나은 쪽이 아니라 그 자리에 알맞은 쪽') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u5-X04','kor',6,'u5',ARRAY['K6-2-u5-C3']::text[],'인쇄 · 음성 · 영상 매체가 주로 쓰는 방법을 헷갈린다','무엇을 바탕으로 무엇을 더하나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u5-X05','kor',6,'u5',ARRAY['K6-2-u5-C3','K6-2-u5-C8']::text[],'올린 날짜 · 만든 사람 이름 · 본 사람 수 · 화면 크기처럼 뜻을 나르지 않는 것을 매체 자료의 표현 방법으로 고른다','화면이나 지면에서 뜻을 나르는 것만') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u5-X06','kor',6,'u5',ARRAY['K6-2-u5-C4','K6-2-u5-C5']::text[],'글의 강조 방법(굵은 글씨 · 밑줄 · 문장 부호)과 말의 강조 방법(목소리 크기 · 억양 · 속도)을 뒤섞는다','글은 눈에, 말은 귀에 띄게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u5-X07','kor',6,'u5',ARRAY['K6-2-u5-C4']::text[],'문자 언어의 장점(다시 보기 · 똑같이 나누어 갖기 · 천천히 읽고 고치기)을 모르거나 글은 쓰고 나면 고칠 수 없다고 여긴다','적어 두면 무엇이 좋을까?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u5-X08','kor',6,'u5',ARRAY['K6-2-u5-C5']::text[],'음성 언어의 장점(목소리로 감정 전하기 · 반응 보고 바꾸기 · 그 자리에서 되묻기)을 모른다','마주 보고 말하면 무엇을 할 수 있을까?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u5-X09','kor',6,'u5',ARRAY['K6-2-u5-C6']::text[],'알맞은 방법을 고르기만 하고 까닭을 말하지 않거나, 까닭을 언어의 특성과 잇지 못한다','고른 것 + 그 특성 때문에') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u5-X10','kor',6,'u5',ARRAY['K6-2-u5-C6','K6-2-u5-C24']::text[],'전하려는 내용과 받는 사람의 처지를 보지 않고 늘 한 가지 방법만 쓰거나 빠르고 편한 방법만 고른다','무엇을 · 누구에게?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u5-X11','kor',6,'u5',ARRAY['K6-2-u5-C7','K6-2-u5-C9']::text[],'말한 내용을 글(자막)로도 보여 주면 겹쳐서 쓸모없다고 여겨, 두 언어가 서로 보완하는 것을 모른다','놓친 곳을 다시 확인하게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u5-X12','kor',6,'u5',ARRAY['K6-2-u5-C8','K6-2-u5-C9','K6-2-u5-C11']::text[],'해설하는 말 · 자막 · 장면 · 소리와 음악이 각각 하는 일을 헷갈린다','흐름 · 붙들기 · 한눈에 · 눈여겨볼 곳') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u5-X13','kor',6,'u5',ARRAY['K6-2-u5-C10','K6-2-u5-C17']::text[],'자막 · 음악 · 장면 · 자료를 많이 넣을수록 잘 전달되고 좋은 자료라고 여긴다','개수가 아니라 무엇을 돕는가') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u5-X14','kor',6,'u5',ARRAY['K6-2-u5-C11']::text[],'장면마다 방법을 아무렇게나 골랐다고 여겨, 그 장면에서 해야 할 일과 방법을 잇지 못한다','이 장면에서 시청자가 알아야 할 것은?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u5-X15','kor',6,'u5',ARRAY['K6-2-u5-C12']::text[],'감상을 「좋았다 · 재미있었다 · 별로였다」에서 멈추고 어떤 표현 때문인지 까닭을 말하지 않는다','찾기 · 잇기 · 말하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u5-X16','kor',6,'u5',ARRAY['K6-2-u5-C12']::text[],'느낌이 나와 다르면 잘못 본 것이라 여기거나, 사람마다 다를 수 있는 느낌과 영상 안에서 확인할 수 있는 것을 가르지 못한다','갈릴 수 있는 것 · 함께 확인할 수 있는 것') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u5-X19','kor',6,'u5',ARRAY['K6-2-u5-C14']::text[],'독자 고려를 낱말만 쉽게 바꾸는 일로 좁히거나, 독자의 흥미 · 배경지식 · 수준 · 매체 가운데 일부만 살핀다','흥미 · 배경지식 · 수준 · 매체') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u5-X20','kor',6,'u5',ARRAY['K6-2-u5-C15']::text[],'독자 고려를 독자가 좋아할 내용만 고르거나 어려운 이야기를 빼 버리는 비위 맞추기로 여긴다','전하려는 것은 그대로, 닿는 방법을 바꾸기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u5-X21','kor',6,'u5',ARRAY['K6-2-u5-C16']::text[],'글 쓰는 세 단계와 그 단계에서 하는 일을 헷갈리거나, 독자는 처음 계획할 때만 떠올리면 된다고 여긴다','쓰기 전 · 쓰는 중 · 쓴 뒤, 단계마다 독자') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u5-X22','kor',6,'u5',ARRAY['K6-2-u5-C16']::text[],'고쳐 쓸 곳을 글씨 · 길이 · 꾸밈 같은 겉모습에서 찾거나, 고쳐 쓰기를 틀린 곳을 벌하는 일로 여긴다','독자에게 더 잘 닿게 하려고 고쳐요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u5-X23','kor',6,'u5',ARRAY['K6-2-u5-C17']::text[],'자료를 개수를 채우려고 넣거나, 글과 이어지지 않는 자료를 넣거나, 자료를 넣으면 글을 덜 써도 된다고 여긴다','글만으로 어려운 곳을 돕는 자료') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u5-X24','kor',6,'u5',ARRAY['K6-2-u5-C14','K6-2-u5-C16']::text[],'어렵고 딱딱한 낱말을 많이 쓰면 글이 훌륭해 보인다고 여겨, 독자가 알아듣지 못하는 문제를 보지 않는다','독자가 아는 말인가?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u5-X25','kor',6,'u5',ARRAY['K6-2-u5-C14','K6-2-u5-C15']::text[],'글에서 독자가 무엇을 하면 되는지, 왜 그래야 하는지가 빠져도 괜찮다고 여긴다','까닭과 할 일이 함께 보이게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u5-X26','kor',6,'u5',ARRAY['K6-2-u5-C18','K6-2-u5-C20']::text[],'기사문에 쓴 사람의 느낌이나 생각을 사실처럼 쓴다(「모두 기뻐했다」 · 「가장 큰 변화」)','누구든 다시 확인할 수 있는가?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u5-X27','kor',6,'u5',ARRAY['K6-2-u5-C18','K6-2-u5-C20']::text[],'확인하지 못한 소문이나 그럴 것 같아 지어낸 숫자를 기사문에 쓴다','세어 보거나 물어본 것만') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u5-X28','kor',6,'u5',ARRAY['K6-2-u5-C19']::text[],'기사문의 짜임(표제 · 부제 · 전문 · 본문)과 하는 일을 헷갈리거나, 전문을 느낌이나 못다 한 말을 쓰는 곳으로 여긴다','전문 = 주요 내용 요약') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u5-X29','kor',6,'u5',ARRAY['K6-2-u5-C19']::text[],'육하원칙(누가 · 언제 · 어디에서 · 무엇을 · 어떻게 · 왜)의 항목을 서로 헷갈리거나 빠뜨린다','여섯 가지 물음에 하나씩 답하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u5-X30','kor',6,'u5',ARRAY['K6-2-u5-C21']::text[],'기삿거리를 독자의 관심이나 직접 확인할 수 있는지를 보지 않고 고른다','독자가 관심 있고, 내가 가서 확인할 수 있는 일') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u5-X31','kor',6,'u5',ARRAY['K6-2-u5-C21']::text[],'기사문 제목을 본문에 없는 말로 부풀리거나, 반대로 아무 내용도 담지 않은 제목을 쓴다','내용을 담되 부풀리지 않기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u5-X32','kor',6,'u5',ARRAY['K6-2-u5-C21','K6-2-u5-C17']::text[],'사진 · 표 같은 자료를 넣으면서 어디에서 얻었는지, 언제 누구에게 어떻게 조사했는지 출처를 밝히지 않는다','출처를 밝혀요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u5-X33','kor',6,'u5',ARRAY['K6-2-u5-C22']::text[],'편지의 다섯 부분(받는 사람 · 첫인사 · 하고 싶은 말 · 끝인사 · 쓴 날짜와 보내는 사람)을 빠뜨리거나 하는 일을 헷갈린다','누구에게 · 인사 · 목적 · 인사 · 언제 누가') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u5-X34','kor',6,'u5',ARRAY['K6-2-u5-C22']::text[],'편지를 받는 사람에게 알맞은 높임말을 쓰지 않거나, 받는 사람이 모를 만한 일을 앞뒤 설명 없이 쓴다','받는 사람 한 사람을 떠올려요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u5-X35','kor',6,'u5',ARRAY['K6-2-u5-C23']::text[],'전하려는 마음과 맞지 않는 내용을 쓴다(축하에 충고, 사과에 변명 먼저, 위로에 섣부른 충고)','이 마음에 맞는 말은?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u5-X36','kor',6,'u5',ARRAY['K6-2-u5-C23']::text[],'「고마워」 · 「잘했네」처럼 무엇이 그런지 없이 막연하게 써서 마음이 잘 닿지 않는다','그 일을 콕 집어') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u5-X37','kor',6,'u5',ARRAY['K6-2-u5-C24']::text[],'편지를 숙제로 아무에게나 쓰거나 꾸미기에 시간을 다 쓰고, 건네고 반응을 보는 것을 하지 않는다','건네고 나서 완성돼요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u5-X38','kor',6,'u5',ARRAY['K6-2-u5-C25']::text[],'겹받침 뒤에 자음자가 오거나 낱말이 끝날 때에도 두 소리를 다 내거나, 뒤에 모음이 와도 하나만 소리 낸다','뒤에 오는 것이 자음자? 모음?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u5-X39','kor',6,'u5',ARRAY['K6-2-u5-C25']::text[],'겹받침 낱말에서 어느 자음자가 소리 나는지, 뒤엣것이 어느 글자로 넘어가는지를 헷갈린다','소리 내어 천천히 읽어 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u5-X41','kor',6,'u5',ARRAY['K6-2-u5-C30']::text[],'「수월봉 화산 쇄설층」이 만들어진 과정이나 분화구의 중심을 바다 한가운데라고 추측한 까닭을 영상 내용과 다르게 안다(용암이 흘러 그대로 굳었다 · 파도가 깎아 만들었다 등)','마그마가 물을 만나 폭발 → 화산재와 쇄설물이 쌓임') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u5-X42','kor',6,'u5',ARRAY['K6-2-u5-C31']::text[],'영상에 나온 낱말(지표·분화구·화산재·지층)의 뜻을 서로 엇갈리게 안다','뜻풀이를 문장에 넣어 읽어 봐요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u5-X43','kor',6,'u5',ARRAY['K6-2-u5-C14','K6-2-u5-C32']::text[],'글쓴이가 조사한 내용이나 자기 관심만 쓰면 독자도 관심을 갖고 이해할 것이라 여겨, 독자의 관심사와 아는 정도를 살피지 않는다','이 글을 읽을 사람은 무엇이 궁금할까?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u5-X44','kor',6,'u5',ARRAY['K6-2-u5-C35','K6-2-u5-C23']::text[],'편지를 쓰는 목적과 편지의 종류를 잇지 못한다(미안한 마음을 전하는데 초대 편지 · 행사에 부르는데 위로 편지)','전하려는 마음이 무엇인가?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u5-X45','kor',6,'u5',ARRAY['K6-2-u5-C14']::text[],'누리 소통망에 올리는 짧은 글은 읽는 사람을 생각하지 않고 써도 된다고 여겨, 오해를 부르는 표현을 그대로 쓴다','짧은 글에도 읽는 사람이 있어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u5-X46','kor',6,'u5',ARRAY['K6-2-u5-C21','K6-2-u5-C19']::text[],'기사문의 제목은 반드시 본문보다 먼저 정해야 한다고 여겨, 본문을 쓴 뒤 내용을 보고 제목을 정하거나 고치는 방법을 모른다','본문을 다 쓰고 제목을 정해도 돼요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u5-X47','kor',6,'u5',ARRAY['K6-2-u5-C27','K6-2-u5-C28']::text[],'문자 언어나 음성 언어의 특성을 물으면 자료의 내용(날짜·장소)만 되풀이하고, 글자 크기·굵기나 목소리 크기·억양 같은 표현 방식이 전달을 어떻게 돕는지는 말하지 못한다','무엇을 전했나보다 어떻게 전했나') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L01_basic#1','kor',6,2,'u5','L01','tb_g6_2_kor_u5_L01_basic','lesson_basic','K6-2-u5-C3',1,'mc','auto','생각 열기에서 「오디오 북에서 전문가가 설명하는 자료를 들을 수 있어.」라고 말한 친구는 어떤 방법으로 자료를 얻나요?',ARRAY['K6-2-u5-X01','K6-2-u5-X04']::text[],false,'{"seq":1,"concept":"K6-2-u5-C3","difficulty":1,"kind":"mc","stem":"생각 열기에서 「오디오 북에서 전문가가 설명하는 자료를 들을 수 있어.」라고 말한 친구는 어떤 방법으로 자료를 얻나요?","options":[{"t":"음성 언어로 된 자료를 귀로 듣는다","correct":true},{"t":"글자로 된 자료를 눈으로 읽는다","mis":"K6-2-u5-X01"},{"t":"학급 알림판의 글을 읽는다","mis":"K6-2-u5-X04"},{"t":"책을 빌려 읽는다","mis":"K6-2-u5-X04"}],"explanation":["오디오 북은 소리로 들려주는 책이에요.","전문가의 설명을 음성 언어로 들어요.","알림판의 글과 책은 글자로 된 자료예요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"텔레비전, 인터넷에서 동영상을 보면서 자료를 정리할 수 있어."},{"who":"친구 2","text":"오디오 북에서 전문가가 설명하는 자료를 들을 수 있어."},{"who":"친구 3","text":"학급 알림판에는 우리가 읽을 수 있는 여러 글이 있어."},{"who":"친구 4","text":"책을 읽으면 자료를 얻을 수 있어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L01_basic#2','kor',6,2,'u5','L01','tb_g6_2_kor_u5_L01_basic','lesson_basic','K6-2-u5-C26',1,'sa','auto','『국어』 221쪽 2번 예시 답안이에요. 「전학 간 친구에게 소식을 전하는 (    )을/를 썼습니다.」 빈칸에 알맞은 두 글자 낱말을 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"K6-2-u5-C26","difficulty":1,"kind":"sa","stem":"『국어』 221쪽 2번 예시 답안이에요. 「전학 간 친구에게 소식을 전하는 (    )을/를 썼습니다.」 빈칸에 알맞은 두 글자 낱말을 쓰세요.","answer":["편지"],"explanation":["일상생활에서 글을 쓴 경험을 떠올리는 활동이에요.","전학 간 친구에게 소식을 전하는 편지를 썼어요.","동생에게 초대장을 쓴 경험도 예시로 나와요."],"mis":"K6-2-u5-X33"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L01_basic#3','kor',6,2,'u5','L01','tb_g6_2_kor_u5_L01_basic','lesson_basic','K6-2-u5-C1',1,'ox','auto','『국어』 220쪽 그림의 동영상은 문자 언어, 음성 언어, 그림 등으로 내용을 전달하고 있어요.',ARRAY['K6-2-u5-X04']::text[],false,'{"seq":3,"concept":"K6-2-u5-C1","difficulty":1,"kind":"ox","stem":"『국어』 220쪽 그림의 동영상은 문자 언어, 음성 언어, 그림 등으로 내용을 전달하고 있어요.","answer":"O","reason_options":[{"t":"화면의 자막(글자), 설명하는 목소리, 그림이 함께 나오기 때문에","correct":true},{"t":"동영상은 소리로만 내용을 전달하기 때문에","mis":"K6-2-u5-X04"}],"mis":"K6-2-u5-X04","explanation":["동영상에는 「심폐 소생술」이라는 자막이 나와요.","설명하는 목소리도 함께 들려요.","여러 방법이 어우러져 내용을 전해요."],"asset":{"type":"speech","turns":[{"who":"[화면 자막]","text":"심폐 소생술 — 정지된 심장 대신 심장과 뇌에 산소가 포함된 혈액을 공급하는 응급 처치술."},{"who":"친구 1","text":"동영상을 볼 때 자막을 같이 보면 어때?"},{"who":"친구 2","text":"자막을 읽으면서 동시에 음성으로 들으니까 내용을 잘 알겠어."},{"who":"친구 3","text":"말하는 이의 말을 정리해서 보여 주니까 장면을 이해하기 쉬워."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L01_basic#4','kor',6,2,'u5','L01','tb_g6_2_kor_u5_L01_basic','lesson_basic','K6-2-u5-C26',1,'mc','auto','『국어』 221쪽 3번에서 친구들이 기사문을 읽었다고 말한 곳이 아닌 것은 무엇인가요?',ARRAY['K6-2-u5-X04']::text[],false,'{"seq":4,"concept":"K6-2-u5-C26","difficulty":1,"kind":"mc","stem":"『국어』 221쪽 3번에서 친구들이 기사문을 읽었다고 말한 곳이 아닌 것은 무엇인가요?","options":[{"t":"오디오 북","correct":true},{"t":"신문","mis":"K6-2-u5-X04"},{"t":"과학 잡지","mis":"K6-2-u5-X04"},{"t":"온라인 매체","mis":"K6-2-u5-X04"}],"explanation":["친구들은 신문, 과학 잡지에서 기사문을 읽었다고 했어요.","온라인 매체에서 기사문을 읽은 경험도 나와요.","오디오 북은 소리로 듣는 음성 매체예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L01_basic#5','kor',6,2,'u5','L01','tb_g6_2_kor_u5_L01_basic','lesson_basic','K6-2-u5-C1',2,'mc','auto','『국어』 220쪽 그림에서 「자막을 읽으면서 동시에 음성으로 들으니까 내용을 잘 알겠어.」라고 한 친구가 말한 좋은 점과 가장 가까운 것은 무엇인가요?',ARRAY['K6-2-u5-X11','K6-2-u5-X03']::text[],false,'{"seq":5,"concept":"K6-2-u5-C1","difficulty":2,"kind":"mc","stem":"『국어』 220쪽 그림에서 「자막을 읽으면서 동시에 음성으로 들으니까 내용을 잘 알겠어.」라고 한 친구가 말한 좋은 점과 가장 가까운 것은 무엇인가요?","options":[{"t":"글자로 보고 소리로 들으니 내용을 더 잘 이해할 수 있다","correct":true},{"t":"자막이 있으면 소리를 꺼도 똑같다","mis":"K6-2-u5-X11"},{"t":"음성만 들어야 집중이 잘된다","mis":"K6-2-u5-X03"},{"t":"자막은 화면을 가려서 방해가 된다","mis":"K6-2-u5-X11"}],"explanation":["자막은 문자 언어, 설명하는 목소리는 음성 언어예요.","두 언어를 함께 쓰면 내용을 더 잘 알 수 있어요.","한쪽만 있으면 된다는 생각은 알맞지 않아요."],"asset":{"type":"speech","turns":[{"who":"[화면 자막]","text":"심폐 소생술 — 정지된 심장 대신 심장과 뇌에 산소가 포함된 혈액을 공급하는 응급 처치술."},{"who":"친구 1","text":"동영상을 볼 때 자막을 같이 보면 어때?"},{"who":"친구 2","text":"자막을 읽으면서 동시에 음성으로 들으니까 내용을 잘 알겠어."},{"who":"친구 3","text":"말하는 이의 말을 정리해서 보여 주니까 장면을 이해하기 쉬워."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L01_basic#6','kor',6,2,'u5','L01','tb_g6_2_kor_u5_L01_basic','lesson_basic','K6-2-u5-C26',2,'mc','auto','『국어』 221쪽 2번에서 글을 쓸 때 내용을 독자에게 잘 전달하려고 사용한 방법의 예시 답안은 무엇인가요?',ARRAY['K6-2-u5-X24','K6-2-u5-X43','K6-2-u5-X22']::text[],false,'{"seq":6,"concept":"K6-2-u5-C26","difficulty":2,"kind":"mc","stem":"『국어』 221쪽 2번에서 글을 쓸 때 내용을 독자에게 잘 전달하려고 사용한 방법의 예시 답안은 무엇인가요?","options":[{"t":"친근한 표현이나 쉬운 표현을 사용했다","correct":true},{"t":"어려운 낱말을 많이 넣었다","mis":"K6-2-u5-X24"},{"t":"읽을 사람은 생각하지 않고 내가 아는 것만 썼다","mis":"K6-2-u5-X43"},{"t":"글씨만 크게 썼다","mis":"K6-2-u5-X22"}],"explanation":["편지나 초대장을 받는 사람을 떠올렸어요.","친근한 표현, 쉬운 표현을 썼어요.","이것이 이 단원에서 배울 「독자를 고려하며 글 쓰기」로 이어져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L01_basic#7','kor',6,2,'u5','L01','tb_g6_2_kor_u5_L01_basic','lesson_basic','K6-2-u5-C3',2,'match','auto','생각 열기에 나온 자료와 그 자료가 정보를 전하는 방법을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K6-2-u5-C3","difficulty":2,"kind":"match","stem":"생각 열기에 나온 자료와 그 자료가 정보를 전하는 방법을 알맞게 이으세요.","pairs":[{"l":"텔레비전·인터넷 동영상","r":"글자, 소리, 그림이 어우러져 전한다"},{"l":"오디오 북","r":"목소리로 들려준다"},{"l":"학급 알림판의 글","r":"글자로 읽게 한다"}],"mis":"K6-2-u5-X04","explanation":["우리가 접하는 자료는 각각 다른 방법으로 생각을 전해요.","오디오 북은 소리, 알림판의 글은 글자로 전해요.","동영상은 여러 방법이 어우러져 있어요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"텔레비전, 인터넷에서 동영상을 보면서 자료를 정리할 수 있어."},{"who":"친구 2","text":"오디오 북에서 전문가가 설명하는 자료를 들을 수 있어."},{"who":"친구 3","text":"학급 알림판에는 우리가 읽을 수 있는 여러 글이 있어."},{"who":"친구 4","text":"책을 읽으면 자료를 얻을 수 있어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L01_basic#8','kor',6,2,'u5','L01','tb_g6_2_kor_u5_L01_basic','lesson_basic','K6-2-u5-C2',2,'ox','auto','문자 언어와 음성 언어는 매체 환경과 상관없이 언제나 전통적인 모습 그대로 나타나요.',ARRAY['K6-2-u5-X02']::text[],false,'{"seq":8,"concept":"K6-2-u5-C2","difficulty":2,"kind":"ox","stem":"문자 언어와 음성 언어는 매체 환경과 상관없이 언제나 전통적인 모습 그대로 나타나요.","answer":"X","reason_options":[{"t":"매체 환경에 따라 언어가 바뀌어 표현되기도 하기 때문에(자막, 음성 메모 등)","correct":true},{"t":"글은 언제나 종이에만 쓰고 말은 언제나 마주 보고만 하기 때문에","mis":"K6-2-u5-X02"}],"mis":"K6-2-u5-X02","explanation":["매체를 활용하면 언어의 모습이 달라지기도 해요.","말을 자막으로 보여 주거나 목소리를 녹음해 남길 수 있어요.","그래서 매체에 따라 언어가 어떻게 표현되는지 살펴보아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L01_basic#9','kor',6,2,'u5','L01','tb_g6_2_kor_u5_L01_basic','lesson_basic','K6-2-u5-C1',2,'blank','auto','「자신이 즐겨 찾는 매체는 언어를 어떻게 표현하나요?」라는 물음에 「동영상은 (    )을/를 사용합니다.」라고 답했어요. 빈칸에 알맞은 것은 무엇인가요?',ARRAY['K6-2-u5-X04','K6-2-u5-X05']::text[],false,'{"seq":9,"concept":"K6-2-u5-C1","difficulty":2,"kind":"blank","stem":"「자신이 즐겨 찾는 매체는 언어를 어떻게 표현하나요?」라는 물음에 「동영상은 (    )을/를 사용합니다.」라고 답했어요. 빈칸에 알맞은 것은 무엇인가요?","options":[{"t":"문자 언어와 음성 언어","correct":true},{"t":"문자 언어 한 가지","mis":"K6-2-u5-X04"},{"t":"음성 언어 한 가지","mis":"K6-2-u5-X04"},{"t":"그림과 음악","mis":"K6-2-u5-X05"}],"explanation":["동영상에는 자막과 설명하는 목소리가 함께 나와요.","자막은 문자 언어, 목소리는 음성 언어예요.","그래서 동영상은 두 언어를 모두 사용해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L01_basic#10','kor',6,2,'u5','L01','tb_g6_2_kor_u5_L01_basic','lesson_basic','K6-2-u5-C1',3,'mc','auto','『국어』 219쪽 「어떻게 하면 효과적으로 정보를 얻고 생각을 표현할 수 있을까요?」에 대한 예상 반응으로 알맞은 것은 무엇인가요?',ARRAY['K6-2-u5-X10','K6-2-u5-X03','K6-2-u5-X06']::text[],false,'{"seq":10,"concept":"K6-2-u5-C1","difficulty":3,"kind":"mc","stem":"『국어』 219쪽 「어떻게 하면 효과적으로 정보를 얻고 생각을 표현할 수 있을까요?」에 대한 예상 반응으로 알맞은 것은 무엇인가요?","options":[{"t":"언어의 특성을 생각하여 표현한다","correct":true},{"t":"언제나 글로만 표현한다","mis":"K6-2-u5-X10"},{"t":"더 좋은 언어 하나를 정해 그것만 쓴다","mis":"K6-2-u5-X03"},{"t":"목소리만 크게 하면 된다","mis":"K6-2-u5-X06"}],"explanation":["자료마다 생각을 전하는 방법이 달라요.","문자 언어와 음성 언어의 특성을 알면 알맞게 고를 수 있어요.","이 단원에서 그 특성과 표현 효과를 배워요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"텔레비전, 인터넷에서 동영상을 보면서 자료를 정리할 수 있어."},{"who":"친구 2","text":"오디오 북에서 전문가가 설명하는 자료를 들을 수 있어."},{"who":"친구 3","text":"학급 알림판에는 우리가 읽을 수 있는 여러 글이 있어."},{"who":"친구 4","text":"책을 읽으면 자료를 얻을 수 있어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L01_challenge#1','kor',6,2,'u5','L01','tb_g6_2_kor_u5_L01_challenge','lesson_challenge','K6-2-u5-C3',2,'mc','auto','생각 열기에 나온 자료 가운데 문자 언어를 바탕으로 정보를 전하는 것끼리 묶은 것은 무엇인가요?',ARRAY['K6-2-u5-X04']::text[],false,'{"seq":1,"concept":"K6-2-u5-C3","difficulty":2,"kind":"mc","stem":"생각 열기에 나온 자료 가운데 문자 언어를 바탕으로 정보를 전하는 것끼리 묶은 것은 무엇인가요?","options":[{"t":"학급 알림판의 글, 책","correct":true},{"t":"오디오 북, 책","mis":"K6-2-u5-X04"},{"t":"텔레비전 동영상, 오디오 북","mis":"K6-2-u5-X04"},{"t":"텔레비전 동영상만","mis":"K6-2-u5-X04"}],"explanation":["학급 알림판의 글과 책은 글자로 읽어요.","오디오 북은 소리로 들어요.","동영상은 글자와 소리가 어우러져 있어요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"텔레비전, 인터넷에서 동영상을 보면서 자료를 정리할 수 있어."},{"who":"친구 2","text":"오디오 북에서 전문가가 설명하는 자료를 들을 수 있어."},{"who":"친구 3","text":"학급 알림판에는 우리가 읽을 수 있는 여러 글이 있어."},{"who":"친구 4","text":"책을 읽으면 자료를 얻을 수 있어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L01_challenge#2','kor',6,2,'u5','L01','tb_g6_2_kor_u5_L01_challenge','lesson_challenge','K6-2-u5-C1',2,'sa','auto','『국어』 220쪽 (2)의 예시 답안이에요. 「(    ) 언어, 음성 언어, 그림 등으로 전달하고 있습니다.」 빈칸에 알맞은 두 글자 낱말을 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"K6-2-u5-C1","difficulty":2,"kind":"sa","stem":"『국어』 220쪽 (2)의 예시 답안이에요. 「(    ) 언어, 음성 언어, 그림 등으로 전달하고 있습니다.」 빈칸에 알맞은 두 글자 낱말을 쓰세요.","answer":["문자"],"explanation":["동영상 화면에 자막이 나와요.","자막은 글자로 나타낸 문자 언어예요.","목소리는 음성 언어, 장면은 그림이에요."],"asset":{"type":"speech","turns":[{"who":"[화면 자막]","text":"심폐 소생술 — 정지된 심장 대신 심장과 뇌에 산소가 포함된 혈액을 공급하는 응급 처치술."},{"who":"친구 1","text":"동영상을 볼 때 자막을 같이 보면 어때?"},{"who":"친구 2","text":"자막을 읽으면서 동시에 음성으로 들으니까 내용을 잘 알겠어."},{"who":"친구 3","text":"말하는 이의 말을 정리해서 보여 주니까 장면을 이해하기 쉬워."}]},"mis":"K6-2-u5-X01"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L01_challenge#3','kor',6,2,'u5','L01','tb_g6_2_kor_u5_L01_challenge','lesson_challenge','K6-2-u5-C1',3,'mc','auto','『국어』 220쪽 그림의 동영상에서 「심폐 소생술」이라는 글자와 그 뜻을 화면에 보여 주는 까닭으로 가장 알맞은 것은 무엇인가요?',ARRAY['K6-2-u5-X05','K6-2-u5-X11','K6-2-u5-X13']::text[],false,'{"seq":3,"concept":"K6-2-u5-C1","difficulty":3,"kind":"mc","stem":"『국어』 220쪽 그림의 동영상에서 「심폐 소생술」이라는 글자와 그 뜻을 화면에 보여 주는 까닭으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"말하는 이의 말을 정리해서 보여 주어 장면을 이해하기 쉽게 하려고","correct":true},{"t":"글자를 넣어 화면을 예쁘고 화려하게 꾸미려고","mis":"K6-2-u5-X05"},{"t":"설명하는 목소리를 들려주지 않고 글자로만 전하려고","mis":"K6-2-u5-X11"},{"t":"화면에 글자가 많을수록 좋은 영상이 되기 때문에","mis":"K6-2-u5-X13"}],"explanation":["친구 3은 「말하는 이의 말을 정리해서 보여 주니까 장면을 이해하기 쉬워.」라고 했어요.","자막은 말한 내용을 글자로 정리해 보여 줘요.","꾸밈이나 글자 수가 목적이 아니에요."],"asset":{"type":"speech","turns":[{"who":"[화면 자막]","text":"심폐 소생술 — 정지된 심장 대신 심장과 뇌에 산소가 포함된 혈액을 공급하는 응급 처치술."},{"who":"친구 1","text":"동영상을 볼 때 자막을 같이 보면 어때?"},{"who":"친구 2","text":"자막을 읽으면서 동시에 음성으로 들으니까 내용을 잘 알겠어."},{"who":"친구 3","text":"말하는 이의 말을 정리해서 보여 주니까 장면을 이해하기 쉬워."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L01_challenge#4','kor',6,2,'u5','L01','tb_g6_2_kor_u5_L01_challenge','lesson_challenge','K6-2-u5-C26',3,'error','auto','『국어』 221쪽 2번을 떠올리며 친구들이 말했어요. 독자에게 잘 전달하려는 방법으로 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-2-u5-X24','K6-2-u5-X19']::text[],false,'{"seq":4,"concept":"K6-2-u5-C26","difficulty":3,"kind":"error","stem":"『국어』 221쪽 2번을 떠올리며 친구들이 말했어요. 독자에게 잘 전달하려는 방법으로 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"친구 3 — 「동생에게 초대장을 쓸 때 어른도 잘 모르는 어려운 낱말을 골라 썼어.」","correct":true,"mis_target":"K6-2-u5-X24"},{"t":"친구 1 — 「전학 간 친구에게 편지를 쓸 때 친근한 표현을 사용했어.」","mis":"K6-2-u5-X19"},{"t":"친구 2 — 「동생에게 초대장을 쓸 때 쉬운 표현을 사용했어.」","mis":"K6-2-u5-X19"}],"explanation":["글을 읽을 사람에게 잘 전달되어야 해요.","친근한 표현, 쉬운 표현은 독자를 생각한 방법이에요.","동생에게 어려운 낱말을 쓰면 뜻이 잘 전해지지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L01_challenge#5','kor',6,2,'u5','L01','tb_g6_2_kor_u5_L01_challenge','lesson_challenge','K6-2-u5-C2',3,'ox','auto','스마트폰의 음성 메모처럼 음성 언어도 기록으로 남길 수 있어요.',ARRAY['K6-2-u5-X02']::text[],false,'{"seq":5,"concept":"K6-2-u5-C2","difficulty":3,"kind":"ox","stem":"스마트폰의 음성 메모처럼 음성 언어도 기록으로 남길 수 있어요.","answer":"O","reason_options":[{"t":"음성 언어는 보통 말하면 사라지지만, 매체를 쓰면 녹음해 남길 수도 있기 때문에","correct":true},{"t":"음성 언어는 어떤 경우에도 반드시 사라지기 때문에","mis":"K6-2-u5-X02"}],"mis":"K6-2-u5-X02","explanation":["음성 언어는 기본적으로 사용하는 즉시 사라져요.","하지만 스마트폰이나 태블릿 피시로 녹음하면 남길 수 있어요.","특성은 기본 성질이고 매체에 따라 달라질 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L01_challenge#6','kor',6,2,'u5','L01','tb_g6_2_kor_u5_L01_challenge','lesson_challenge','K6-2-u5-C3',3,'mc','auto','『국어』 220쪽 「이 단원에서는」에 나온 「매체 자료에서 언어의 표현 효과 이해하기」를 공부할 때 살펴볼 것으로 알맞은 것은 무엇인가요?',ARRAY['K6-2-u5-X05','K6-2-u5-X03','K6-2-u5-X13']::text[],false,'{"seq":6,"concept":"K6-2-u5-C3","difficulty":3,"kind":"mc","stem":"『국어』 220쪽 「이 단원에서는」에 나온 「매체 자료에서 언어의 표현 효과 이해하기」를 공부할 때 살펴볼 것으로 알맞은 것은 무엇인가요?","options":[{"t":"영상 같은 매체 자료에서 문자 언어와 음성 언어가 어떻게 쓰여 내용을 전하는지","correct":true},{"t":"영상을 올린 날짜와 본 사람 수, 좋아요 수","mis":"K6-2-u5-X05"},{"t":"여러 매체 가운데 어느 매체가 가장 좋은지 순위 정하기","mis":"K6-2-u5-X03"},{"t":"영상에 자막과 음악이 모두 몇 번 나오는지 세어 보기","mis":"K6-2-u5-X13"}],"explanation":["표현 효과는 언어가 내용을 어떻게 전하는지를 보는 거예요.","올린 날짜나 본 사람 수는 뜻을 나르지 않아요.","매체에 순위를 매기거나 개수를 세는 공부가 아니에요."],"asset":{"type":"passage","lines":["1. 언어의 표현 효과 이해하기","• 문자 언어와 음성 언어의 특성 이해하기","• 매체 자료에서 언어의 표현 효과 이해하기","• 언어의 표현 효과를 생각하며 영상 감상하기","2. 독자를 고려하며 글 쓰기","• 독자를 고려해 글 쓰는 방법 알기","• 독자를 고려해 기사문 쓰기"],"numbered":false,"title":"이 단원에서는(『국어』 220쪽)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L01_challenge#7','kor',6,2,'u5','L01','tb_g6_2_kor_u5_L01_challenge','lesson_challenge','K6-2-u5-C1',3,'match','auto','생각 열기와 『국어』 220쪽 그림에 나온 자료를 주로 쓰는 언어와 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K6-2-u5-C1","difficulty":3,"kind":"match","stem":"생각 열기와 『국어』 220쪽 그림에 나온 자료를 주로 쓰는 언어와 알맞게 이으세요.","pairs":[{"l":"학급 알림판의 글","r":"문자 언어"},{"l":"오디오 북의 설명","r":"음성 언어"},{"l":"동영상의 자막과 해설","r":"문자 언어와 음성 언어"}],"mis":"K6-2-u5-X01","explanation":["글자로 나타내는 말은 문자 언어예요.","음성으로 나타내는 말은 음성 언어예요.","동영상은 자막과 해설로 두 언어를 함께 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L01_challenge#8','kor',6,2,'u5','L01','tb_g6_2_kor_u5_L01_challenge','lesson_challenge','K6-2-u5-C26',4,'essay','teacher','『국어』 221쪽 2번처럼 일상생활에서 글을 쓴 경험을 하나 떠올려 쓰고, 그때 내용을 독자에게 잘 전달하려고 사용한 방법을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K6-2-u5-C26","difficulty":4,"kind":"essay","stem":"『국어』 221쪽 2번처럼 일상생활에서 글을 쓴 경험을 하나 떠올려 쓰고, 그때 내용을 독자에게 잘 전달하려고 사용한 방법을 쓰세요.","answer_guide":{"answer":"예: 전학 간 친구에게 소식을 전하는 편지를 썼다. 친구가 편하게 읽을 수 있도록 친근한 표현을 쓰고, 친구가 모르는 우리 반 소식은 쉬운 표현으로 풀어 썼다.","scoring_points":["어떤 글을 누구에게 썼는지 밝혔는가","독자에게 잘 전달하려고 쓴 방법(친근한 표현·쉬운 표현 등)을 썼는가","방법이 그 독자와 이어지게 썼는가"]},"explanation":["누구에게 어떤 글을 썼는지 먼저 떠올려요.","그 사람에게 잘 전하려고 쓴 표현을 적어요.","이 경험이 독자를 고려하며 글 쓰기의 시작이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L01_challenge#9','kor',6,2,'u5','L01','tb_g6_2_kor_u5_L01_challenge','lesson_challenge','K6-2-u5-C1',4,'essay','teacher','『국어』 220쪽 그림에서 친구들이 나눈 말을 바탕으로, 동영상을 볼 때 자막(문자 언어)과 설명하는 목소리(음성 언어)를 함께 보고 들으면 좋은 점을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-2-u5-C1","difficulty":4,"kind":"essay","stem":"『국어』 220쪽 그림에서 친구들이 나눈 말을 바탕으로, 동영상을 볼 때 자막(문자 언어)과 설명하는 목소리(음성 언어)를 함께 보고 들으면 좋은 점을 쓰세요.","answer_guide":{"answer":"예: 설명하는 목소리를 들으면서 자막을 함께 읽으면 내용을 더 잘 알 수 있다. 말하는 이의 말을 자막으로 정리해 보여 주니 장면을 이해하기 쉽고, 놓친 말도 글자로 다시 확인할 수 있다.","scoring_points":["문자 언어와 음성 언어를 함께 쓴다는 점을 밝혔는가","내용을 더 잘 이해하게 된다는 좋은 점을 썼는가","친구들의 말과 이어지게 썼는가"]},"explanation":["자막은 문자 언어, 목소리는 음성 언어예요.","말을 글로 정리해 보여 주면 이해하기 쉬워요.","두 언어가 서로 도와요."],"asset":{"type":"speech","turns":[{"who":"[화면 자막]","text":"심폐 소생술 — 정지된 심장 대신 심장과 뇌에 산소가 포함된 혈액을 공급하는 응급 처치술."},{"who":"친구 1","text":"동영상을 볼 때 자막을 같이 보면 어때?"},{"who":"친구 2","text":"자막을 읽으면서 동시에 음성으로 들으니까 내용을 잘 알겠어."},{"who":"친구 3","text":"말하는 이의 말을 정리해서 보여 주니까 장면을 이해하기 쉬워."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L01_challenge#10','kor',6,2,'u5','L01','tb_g6_2_kor_u5_L01_challenge','lesson_challenge','K6-2-u5-C3',4,'essay','teacher','생각 열기의 친구들처럼 내가 자주 이용하는 매체 하나를 골라, 그 매체가 언어를 어떻게 표현하는지 쓰고 그 매체로 정보를 얻으면 좋은 점을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-2-u5-C3","difficulty":4,"kind":"essay","stem":"생각 열기의 친구들처럼 내가 자주 이용하는 매체 하나를 골라, 그 매체가 언어를 어떻게 표현하는지 쓰고 그 매체로 정보를 얻으면 좋은 점을 쓰세요.","answer_guide":{"answer":"예: 나는 인터넷 동영상을 자주 본다. 동영상은 설명하는 목소리(음성 언어)와 자막(문자 언어), 그림이 함께 나온다. 그래서 어려운 내용도 귀로 듣고 눈으로 보며 쉽게 이해할 수 있다.","scoring_points":["매체 하나를 골랐는가","그 매체가 쓰는 언어(문자·음성)를 바르게 썼는가","좋은 점을 언어의 표현과 이어 썼는가"]},"explanation":["매체마다 언어를 표현하는 방법이 달라요.","책·알림판은 글자, 오디오 북은 소리, 동영상은 둘 다예요.","그 표현 덕분에 무엇이 좋은지 써요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"텔레비전, 인터넷에서 동영상을 보면서 자료를 정리할 수 있어."},{"who":"친구 2","text":"오디오 북에서 전문가가 설명하는 자료를 들을 수 있어."},{"who":"친구 3","text":"학급 알림판에는 우리가 읽을 수 있는 여러 글이 있어."},{"who":"친구 4","text":"책을 읽으면 자료를 얻을 수 있어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L02_basic#1','kor',6,2,'u5','L02','tb_g6_2_kor_u5_L02_basic','lesson_basic','K6-2-u5-C27',1,'mc','auto','「‘작가와의 만남’ 행사 안내」를 읽은 학생이 몇 분 전까지 자리에 앉아야 하는지 잊어버렸어요. 어떻게 하면 다시 확인할 수 있나요?',ARRAY['K6-2-u5-X07','K6-2-u5-X10']::text[],false,'{"seq":1,"concept":"K6-2-u5-C27","difficulty":1,"kind":"mc","stem":"「‘작가와의 만남’ 행사 안내」를 읽은 학생이 몇 분 전까지 자리에 앉아야 하는지 잊어버렸어요. 어떻게 하면 다시 확인할 수 있나요?","options":[{"t":"안내하는 글을 다시 읽어 본다","correct":true},{"t":"말이 끝나서 다시 알 수 없다","mis":"K6-2-u5-X07"},{"t":"글은 한 번 읽으면 다시 볼 수 없다","mis":"K6-2-u5-X07"},{"t":"친구에게 들은 짐작을 그대로 믿는다","mis":"K6-2-u5-X10"}],"explanation":["안내하는 글은 문자 언어로 쓰여 있어요.","글자로 쓰인 내용은 나중에 다시 볼 수 있어요.","「3교시 시작 5분 전까지」를 글에서 다시 확인해요."],"asset":{"type":"passage","lines":["일시 11월 ○○일 수요일 3교시","장소 1층 시청각실","주제 꿈으로 책 쓰기(작가 김○○)","[자리 안내] 6학년 하늘반은 시청각실 첫째 줄부터 셋째 줄까지 앉는다.","[자리 안내] 이동 시간이 겹치지 않도록 3교시 시작 5분 전까지 앉는다.","[준비할 일] 학교 도서관 ‘이달의 추천 도서’인 작가님의 책을 읽고 질문을 생각해 온다.","[준비할 일] 작가님께 질문하고 대답을 듣는 시간이 있다."],"numbered":false,"title":"「‘작가와의 만남’ 행사 안내」(『국어』 224쪽, 간추림)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L02_basic#2','kor',6,2,'u5','L02','tb_g6_2_kor_u5_L02_basic','lesson_basic','K6-2-u5-C4',1,'blank','auto','『국어』 225쪽 (3)에서 정리한 문자 언어의 특성이에요. 「문자 언어로 기록한 내용은 오랫동안 (    )될 수 있다.」 빈칸에 알맞은 낱말은 무엇인가요?',ARRAY['K6-2-u5-X07','K6-2-u5-X06']::text[],false,'{"seq":2,"concept":"K6-2-u5-C4","difficulty":1,"kind":"blank","stem":"『국어』 225쪽 (3)에서 정리한 문자 언어의 특성이에요. 「문자 언어로 기록한 내용은 오랫동안 (    )될 수 있다.」 빈칸에 알맞은 낱말은 무엇인가요?","options":[{"t":"보존","correct":true},{"t":"삭제","mis":"K6-2-u5-X07"},{"t":"억양","mis":"K6-2-u5-X06"}],"explanation":["보기 낱말은 「보존」과 「크기나 굵기」예요.","글로 기록한 내용은 오랫동안 남아요.","그래서 「보존될 수 있다」라고 정리해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L02_basic#3','kor',6,2,'u5','L02','tb_g6_2_kor_u5_L02_basic','lesson_basic','K6-2-u5-C5',1,'sa','auto','『국어』 227쪽 (3)에서 정리한 음성 언어의 특성이에요. 「말이 끝나면서 소리가 (    ).」 빈칸에 알맞은 낱말을 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"K6-2-u5-C5","difficulty":1,"kind":"sa","stem":"『국어』 227쪽 (3)에서 정리한 음성 언어의 특성이에요. 「말이 끝나면서 소리가 (    ).」 빈칸에 알맞은 낱말을 쓰세요.","answer":["사라진다"],"explanation":["보기 낱말은 「사라진다」와 「크기나 억양」이에요.","음성 언어는 말이 끝나면 소리가 사라져요.","그래서 집중해서 들어야 해요."],"mis":"K6-2-u5-X02"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L02_basic#4','kor',6,2,'u5','L02','tb_g6_2_kor_u5_L02_basic','lesson_basic','K6-2-u5-C4',1,'ox','auto','『국어』 222쪽 상황 ㉮에서 친구는 메모한 글을 보면서 길을 찾고 있어요.',ARRAY['K6-2-u5-X01']::text[],false,'{"seq":4,"concept":"K6-2-u5-C4","difficulty":1,"kind":"ox","stem":"『국어』 222쪽 상황 ㉮에서 친구는 메모한 글을 보면서 길을 찾고 있어요.","answer":"O","reason_options":[{"t":"메모(문자 언어)를 보며 「약국이 나오면 길을 건너라고 되어 있네.」 하고 확인했기 때문에","correct":true},{"t":"전화로 다시 물어보며 길을 찾았기 때문에","mis":"K6-2-u5-X01"}],"mis":"K6-2-u5-X01","explanation":["상황 ㉮는 메모를 확인하며 길을 찾는 상황이에요.","문자 언어로 정보를 전달받고 있어요.","전화로 묻는 것은 상황 ㉯예요."],"asset":{"type":"speech","turns":[{"who":"㉮ 메모를 보는 친구","text":"첫 번째 골목에서 오른쪽으로 돌아서 올라가다가 약국이 나오면 길을 건너는구나."},{"who":"㉮ 메모를 보는 친구","text":"약국이 나오면 길을 건너라고 되어 있네."},{"who":"㉯ 전화하는 친구","text":"어떻게 찾아가야 할까요?"},{"who":"㉯ 전화 속 어른","text":"첫 번째 골목에서 오른쪽으로 돌아서 올라가다가 약국이 나오면……."},{"who":"㉯ 전화하는 친구","text":"골목에서 오른쪽으로 돌아서 올라왔어요. 그다음에 어떻게 갈지 다시 한번 말씀해 주세요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L02_basic#5','kor',6,2,'u5','L02','tb_g6_2_kor_u5_L02_basic','lesson_basic','K6-2-u5-C5',2,'mc','auto','『국어』 222쪽 상황 ㉯에서 친구가 정보를 다시 확인한 방법은 무엇인가요?',ARRAY['K6-2-u5-X01','K6-2-u5-X02']::text[],false,'{"seq":5,"concept":"K6-2-u5-C5","difficulty":2,"kind":"mc","stem":"『국어』 222쪽 상황 ㉯에서 친구가 정보를 다시 확인한 방법은 무엇인가요?","options":[{"t":"말로 다시 물어보았다","correct":true},{"t":"메모한 글을 다시 읽었다","mis":"K6-2-u5-X01"},{"t":"녹음한 말을 다시 들었다","mis":"K6-2-u5-X02"},{"t":"약국 간판의 글자를 읽었다","mis":"K6-2-u5-X01"}],"explanation":["상황 ㉯는 전화하면서 길을 찾아요.","「다시 한번 말씀해 주세요.」 하고 말로 다시 물었어요.","음성 언어는 그 자리에서 되물을 수 있어요."],"asset":{"type":"speech","turns":[{"who":"㉮ 메모를 보는 친구","text":"첫 번째 골목에서 오른쪽으로 돌아서 올라가다가 약국이 나오면 길을 건너는구나."},{"who":"㉮ 메모를 보는 친구","text":"약국이 나오면 길을 건너라고 되어 있네."},{"who":"㉯ 전화하는 친구","text":"어떻게 찾아가야 할까요?"},{"who":"㉯ 전화 속 어른","text":"첫 번째 골목에서 오른쪽으로 돌아서 올라가다가 약국이 나오면……."},{"who":"㉯ 전화하는 친구","text":"골목에서 오른쪽으로 돌아서 올라왔어요. 그다음에 어떻게 갈지 다시 한번 말씀해 주세요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L02_basic#6','kor',6,2,'u5','L02','tb_g6_2_kor_u5_L02_basic','lesson_basic','K6-2-u5-C28',2,'mc','auto','「선생님의 안내 말씀」에서 선생님이 목소리를 크고 또박또박하게 하신 부분은 어디인가요?',ARRAY['K6-2-u5-X05','K6-2-u5-X47']::text[],false,'{"seq":6,"concept":"K6-2-u5-C28","difficulty":2,"kind":"mc","stem":"「선생님의 안내 말씀」에서 선생님이 목소리를 크고 또박또박하게 하신 부분은 어디인가요?","options":[{"t":"재능 발표회가 오전 9시 30분에 학교 강당에서 시작된다는 부분","correct":true},{"t":"말씀을 시작하기 전에 교실이 웅성거리는 부분","mis":"K6-2-u5-X05"},{"t":"「그럼 내일 즐거운 마음으로 만나요.」 하는 부분","mis":"K6-2-u5-X47"},{"t":"강당에 가면 나무반 선생님이 계신다는 부분","mis":"K6-2-u5-X47"}],"explanation":["선생님은 꼭 기억해야 할 내용을 말할 때 목소리를 바꾸셨어요.","시작 시각과 장소를 크고 또박또박하게 말씀하셨어요.","목소리의 크기로 중요한 내용을 강조한 거예요."],"asset":{"type":"passage","lines":["(간추림) 내일 재능 발표회는 오전 9시 30분에 학교 강당에서 시작된다.","[이 부분은 목소리를 크고 또박또박하게 말씀하신다.]","(간추림) 발표하는 친구는 등교하자마자 강당에 가서 나무반 선생님께 말씀드린다.","(간추림) 관람하는 친구는 교실에 모였다가 9시에 선생님과 함께 강당으로 간다.","(간추림) 6학년 자리는 무대를 바라보고 강당 오른편이다.","(간추림) 당부 셋 — 큰 박수로 응원 · 자리를 지키며 집중 · 뛰지 말고 안전하게"],"numbered":false,"title":"「선생님의 안내 말씀」(『국어』 226쪽 듣기 자료, 간추림)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L02_basic#7','kor',6,2,'u5','L02','tb_g6_2_kor_u5_L02_basic','lesson_basic','K6-2-u5-C6',2,'match','auto','말이나 글을 고른 까닭을 언어의 특성과 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K6-2-u5-C6","difficulty":2,"kind":"match","stem":"말이나 글을 고른 까닭을 언어의 특성과 알맞게 이으세요.","pairs":[{"l":"종이접기 순서를 설명할 때 문자 언어를 고른 까닭","r":"나중에 잊어버려도 다시 볼 수 있어서"},{"l":"미안한 마음을 전할 때 음성 언어를 고른 까닭","r":"얼굴을 보고 목소리에 진심을 담을 수 있어서"},{"l":"발표회 시작 시각을 말할 때 목소리를 크게 한 까닭","r":"중요한 내용을 강조하려고"}],"mis":"K6-2-u5-X09","explanation":["문자 언어는 기록으로 남아 다시 볼 수 있어요.","음성 언어는 목소리에 감정을 담을 수 있어요.","목소리의 크기로 중요한 곳을 강조해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L02_basic#8','kor',6,2,'u5','L02','tb_g6_2_kor_u5_L02_basic','lesson_basic','K6-2-u5-C5',2,'blank','auto','『국어』 227쪽 (3)에서 「목소리의 (    )(으)로 감정과 의도를 전달할 수 있다.」라고 정리했어요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['K6-2-u5-X06','K6-2-u5-X07']::text[],false,'{"seq":8,"concept":"K6-2-u5-C5","difficulty":2,"kind":"blank","stem":"『국어』 227쪽 (3)에서 「목소리의 (    )(으)로 감정과 의도를 전달할 수 있다.」라고 정리했어요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"크기나 억양","correct":true},{"t":"크기나 굵기","mis":"K6-2-u5-X06"},{"t":"보존","mis":"K6-2-u5-X07"},{"t":"문장 부호","mis":"K6-2-u5-X06"}],"explanation":["「크기나 굵기」는 글자를 강조하는 문자 언어의 방법이에요.","음성 언어는 목소리의 크기나 억양으로 강조해요.","글은 눈에, 말은 귀에 띄게 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L02_basic#9','kor',6,2,'u5','L02','tb_g6_2_kor_u5_L02_basic','lesson_basic','K6-2-u5-C5',2,'ox','auto','안내 내용을 말로만 차례차례 전하는 놀이를 하면 마지막 사람이 들은 내용이 처음 내용과 달라질 수 있어요.',ARRAY['K6-2-u5-X03']::text[],false,'{"seq":9,"concept":"K6-2-u5-C5","difficulty":2,"kind":"ox","stem":"안내 내용을 말로만 차례차례 전하는 놀이를 하면 마지막 사람이 들은 내용이 처음 내용과 달라질 수 있어요.","answer":"O","reason_options":[{"t":"음성 언어는 반복이나 확인 없이 전하면 내용이 바뀔 수 있고, 글로 전하면 내용을 그대로 지킬 수 있기 때문에","correct":true},{"t":"말로 전하면 언제나 글보다 정확하기 때문에","mis":"K6-2-u5-X03"}],"mis":"K6-2-u5-X03","explanation":["내용 전달하기 놀이에서 말과 글로 각각 전해 보아요.","말은 사라지고 다시 확인하기 어려워 달라지기 쉬워요.","글은 내용을 그대로 지킬 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L02_basic#10','kor',6,2,'u5','L02','tb_g6_2_kor_u5_L02_basic','lesson_basic','K6-2-u5-C27',3,'mc','auto','『국어』 225쪽 (2)에서 친구가 「그래서 글을 보면 어떤 정보가 중요한지 금방 파악할 수 있어.」라고 했어요. 그 까닭으로 알맞은 것은 무엇인가요?',ARRAY['K6-2-u5-X47','K6-2-u5-X06']::text[],false,'{"seq":10,"concept":"K6-2-u5-C27","difficulty":3,"kind":"mc","stem":"『국어』 225쪽 (2)에서 친구가 「그래서 글을 보면 어떤 정보가 중요한지 금방 파악할 수 있어.」라고 했어요. 그 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"제목은 큰 글자로, 중요한 내용은 크기·굵기·따옴표로 강조했기 때문","correct":true},{"t":"행사 날짜와 요일, 교시가 맨 앞에 차례대로 나와 있기 때문","mis":"K6-2-u5-X47"},{"t":"작가님의 이름과 책 쓰기 주제가 함께 나와 있기 때문","mis":"K6-2-u5-X47"},{"t":"선생님이 중요한 부분을 목소리를 크게 해서 읽어 주셨기 때문","mis":"K6-2-u5-X06"}],"explanation":["문자 언어는 글자의 크기나 굵기, 문장 부호로 강조해요.","그래서 중요한 정보가 눈에 띄어요.","날짜나 이름은 내용이지 강조 방법이 아니에요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"안내하는 글은 글자로 내용을 전달하고 있어서 눈으로 읽고 내용을 이해할 수 있었어. 글자로 쓰인 내용은 나중에 다시 볼 수 있어."},{"who":"친구 2","text":"이 글에서 제목은 큰 글자로 표시되어 있고, 중요한 내용은 글자 크기나 굵기를 다르게 하거나 따옴표를 붙여서 강조했어."},{"who":"친구 2","text":"그래서 글을 보면 어떤 정보가 중요한지 금방 파악할 수 있어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L02_challenge#1','kor',6,2,'u5','L02','tb_g6_2_kor_u5_L02_challenge','lesson_challenge','K6-2-u5-C6',2,'mc','auto','『국어』 227쪽 4번에서 상황 2에 음성 언어를 고른 까닭으로 예시 답안과 같은 것은 무엇인가요?',ARRAY['K6-2-u5-X03','K6-2-u5-X09','K6-2-u5-X10']::text[],false,'{"seq":1,"concept":"K6-2-u5-C6","difficulty":2,"kind":"mc","stem":"『국어』 227쪽 4번에서 상황 2에 음성 언어를 고른 까닭으로 예시 답안과 같은 것은 무엇인가요?","options":[{"t":"얼굴을 보고 목소리에 진심을 담아 미안한 마음을 전하는 것이 좋기 때문","correct":true},{"t":"음성 언어가 문자 언어보다 언제나 더 좋은 언어이기 때문","mis":"K6-2-u5-X03"},{"t":"글로 쓰면 오래 남아서 다시 볼 수 있기 때문","mis":"K6-2-u5-X09"},{"t":"말은 빨리 끝나서 편하기 때문","mis":"K6-2-u5-X10"}],"explanation":["상황 2는 말다툼을 한 친구에게 미안한 마음을 전하는 상황이에요.","음성 언어는 목소리에 진심을 담을 수 있어요.","어느 언어가 더 좋은지가 아니라 상황에 알맞은지를 보아요."],"asset":{"type":"passage","lines":["상황 1 우리 반 친구에게 복잡한 종이접기 순서를 설명해 주는 상황","상황 2 어제 말다툼을 한 친구에게 미안한 마음을 전하고 싶은 상황"],"numbered":false,"title":"『국어』 227쪽 4번"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L02_challenge#2','kor',6,2,'u5','L02','tb_g6_2_kor_u5_L02_challenge','lesson_challenge','K6-2-u5-C27',2,'sa','auto','『국어』 225쪽 (3)의 보기는 「보존」과 「크기나 굵기」예요. 「글자의 (    )을/를 다르게 하거나 문장 부호를 이용해 중요한 내용을 시각적으로 나타낼 수 있다.」 빈칸에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"K6-2-u5-C27","difficulty":2,"kind":"sa","stem":"『국어』 225쪽 (3)의 보기는 「보존」과 「크기나 굵기」예요. 「글자의 (    )을/를 다르게 하거나 문장 부호를 이용해 중요한 내용을 시각적으로 나타낼 수 있다.」 빈칸에 알맞은 말을 쓰세요.","answer":["크기나 굵기","크기나굵기"],"explanation":["「‘작가와의 만남’ 행사 안내」는 제목을 큰 글자로 썼어요.","중요한 내용은 글자 크기나 굵기를 다르게 했어요.","문자 언어는 중요한 내용을 눈에 보이게 나타낼 수 있어요."],"mis":"K6-2-u5-X06"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L02_challenge#3','kor',6,2,'u5','L02','tb_g6_2_kor_u5_L02_challenge','lesson_challenge','K6-2-u5-C4',3,'mc','auto','여러 사람이 같은 정보를 정확하게 나누어 가져야 할 때 문자 언어가 효과적인 까닭으로 가장 알맞은 것은 무엇인가요?',ARRAY['K6-2-u5-X06','K6-2-u5-X07','K6-2-u5-X16']::text[],false,'{"seq":3,"concept":"K6-2-u5-C4","difficulty":3,"kind":"mc","stem":"여러 사람이 같은 정보를 정확하게 나누어 가져야 할 때 문자 언어가 효과적인 까닭으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"한 번 제시된 내용이 사라지지 않아 여러 사람이 반복해서 똑같이 확인할 수 있기 때문","correct":true},{"t":"목소리의 크기와 억양으로 감정을 전할 수 있기 때문","mis":"K6-2-u5-X06"},{"t":"글은 한번 쓰고 나면 절대 고칠 수 없어 믿을 수 있기 때문","mis":"K6-2-u5-X07"},{"t":"글자로 쓰면 읽는 사람 누구나 같은 느낌을 받기 때문","mis":"K6-2-u5-X16"}],"explanation":["공지문, 안내문, 설명서가 그런 예예요.","글은 사라지지 않아 반복해서 확인할 수 있어요.","그래서 같은 정보를 정확하게 나눌 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L02_challenge#4','kor',6,2,'u5','L02','tb_g6_2_kor_u5_L02_challenge','lesson_challenge','K6-2-u5-C28',3,'error','auto','「선생님의 안내 말씀」을 듣고 친구들이 음성 언어의 특성을 이야기했어요. 들은 내용을 되풀이하기만 하고 음성 언어의 특성은 말하지 않은 친구는 누구인가요?',ARRAY['K6-2-u5-X47','K6-2-u5-X08','K6-2-u5-X02']::text[],false,'{"seq":4,"concept":"K6-2-u5-C28","difficulty":3,"kind":"error","stem":"「선생님의 안내 말씀」을 듣고 친구들이 음성 언어의 특성을 이야기했어요. 들은 내용을 되풀이하기만 하고 음성 언어의 특성은 말하지 않은 친구는 누구인가요?","options":[{"t":"친구 3 — 「6학년 자리는 무대를 바라보고 강당 오른편이래.」","correct":true,"mis_target":"K6-2-u5-X47"},{"t":"친구 1 — 「중요한 내용일 때 목소리를 크게 하셔서 귀에 잘 들어왔어.」","mis":"K6-2-u5-X08"},{"t":"친구 2 — 「말은 끝나면 사라지니까 집중해서 들어야 내용을 잘 이해할 수 있어.」","mis":"K6-2-u5-X02"}],"explanation":["특성을 말하려면 음성 언어가 어떻게 뜻을 전하는지 보아야 해요.","친구 1은 목소리의 크기, 친구 2는 사라지는 특성을 말했어요.","친구 3은 들은 내용만 되풀이했어요."],"asset":{"type":"passage","lines":["(간추림) 내일 재능 발표회는 오전 9시 30분에 학교 강당에서 시작된다.","[이 부분은 목소리를 크고 또박또박하게 말씀하신다.]","(간추림) 발표하는 친구는 등교하자마자 강당에 가서 나무반 선생님께 말씀드린다.","(간추림) 관람하는 친구는 교실에 모였다가 9시에 선생님과 함께 강당으로 간다.","(간추림) 6학년 자리는 무대를 바라보고 강당 오른편이다.","(간추림) 당부 셋 — 큰 박수로 응원 · 자리를 지키며 집중 · 뛰지 말고 안전하게"],"numbered":false,"title":"「선생님의 안내 말씀」(『국어』 226쪽 듣기 자료, 간추림)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L02_challenge#5','kor',6,2,'u5','L02','tb_g6_2_kor_u5_L02_challenge','lesson_challenge','K6-2-u5-C6',3,'ox','auto','『국어』 227쪽 4번에서 「사용할 언어 — 문자 언어」라고만 쓰고 까닭을 쓰지 않아도 충분한 답이에요.',ARRAY['K6-2-u5-X09']::text[],false,'{"seq":5,"concept":"K6-2-u5-C6","difficulty":3,"kind":"ox","stem":"『국어』 227쪽 4번에서 「사용할 언어 — 문자 언어」라고만 쓰고 까닭을 쓰지 않아도 충분한 답이에요.","answer":"X","reason_options":[{"t":"선택한 언어의 특성이 잘 드러나게 그 까닭까지 써야 하기 때문에","correct":true},{"t":"알맞은 언어를 고르기만 하면 까닭은 필요 없기 때문에","mis":"K6-2-u5-X09"}],"mis":"K6-2-u5-X09","explanation":["『국어』는 「선택한 언어의 특성이 잘 드러나게 그 까닭을 써 봐요.」라고 해요.","고른 언어와 그 특성을 이어 말해야 해요.","까닭까지 써야 완성된 답이에요."],"asset":{"type":"passage","lines":["상황 1 우리 반 친구에게 복잡한 종이접기 순서를 설명해 주는 상황","상황 2 어제 말다툼을 한 친구에게 미안한 마음을 전하고 싶은 상황"],"numbered":false,"title":"『국어』 227쪽 4번"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L02_challenge#6','kor',6,2,'u5','L02','tb_g6_2_kor_u5_L02_challenge','lesson_challenge','K6-2-u5-C5',3,'mc','auto','말로 일정을 들을 때 생기기 쉬운 어려움과 그것을 줄이는 방법을 바르게 짝 지은 것은 무엇인가요?',ARRAY['K6-2-u5-X06','K6-2-u5-X02','K6-2-u5-X08']::text[],false,'{"seq":6,"concept":"K6-2-u5-C5","difficulty":3,"kind":"mc","stem":"말로 일정을 들을 때 생기기 쉬운 어려움과 그것을 줄이는 방법을 바르게 짝 지은 것은 무엇인가요?","options":[{"t":"말이 끝나면 소리가 사라져 다시 확인하기 어렵다 — 중요한 내용을 간단히 메모하며 듣는다","correct":true},{"t":"글자의 크기와 굵기를 알 수 없다 — 내 목소리를 더 크게 낸다","mis":"K6-2-u5-X06"},{"t":"말이 오래 남아 머릿속이 헷갈린다 — 들은 것을 빨리 잊어버린다","mis":"K6-2-u5-X02"},{"t":"말로는 감정을 전할 수 없다 — 웃는 얼굴로 듣기만 한다","mis":"K6-2-u5-X08"}],"explanation":["음성 언어는 말이 끝나면 사라져요.","그래서 핵심 내용을 간단히 메모하며 들어요.","들은 내용을 다시 떠올려 말해 보는 것도 좋아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L02_challenge#7','kor',6,2,'u5','L02','tb_g6_2_kor_u5_L02_challenge','lesson_challenge','K6-2-u5-C7',3,'match','auto','같은 일정 안내를 글과 말로 전할 때의 좋은 점을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K6-2-u5-C7","difficulty":3,"kind":"match","stem":"같은 일정 안내를 글과 말로 전할 때의 좋은 점을 알맞게 이으세요.","pairs":[{"l":"글로 쓴 안내","r":"내용을 다시 확인할 수 있다"},{"l":"말로 하는 안내","r":"즉각적이고 생생하게 전해진다"},{"l":"글과 말을 함께 쓴 안내","r":"생생하게 들으면서 놓친 내용은 글로 다시 확인할 수 있다"}],"mis":"K6-2-u5-X11","explanation":["글은 다시 볼 수 있어요.","말은 즉각적이고 생생해요.","함께 쓰면 서로 모자란 점을 채워 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L02_challenge#8','kor',6,2,'u5','L02','tb_g6_2_kor_u5_L02_challenge','lesson_challenge','K6-2-u5-C6',4,'essay','teacher','『국어』 227쪽 4번의 상황 1에서 문자 언어와 음성 언어 가운데 어느 것을 쓰면 좋을지 고르고, 그 언어의 특성이 드러나게 까닭을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K6-2-u5-C6","difficulty":4,"kind":"essay","stem":"『국어』 227쪽 4번의 상황 1에서 문자 언어와 음성 언어 가운데 어느 것을 쓰면 좋을지 고르고, 그 언어의 특성이 드러나게 까닭을 쓰세요.","answer_guide":{"answer":"예: 문자 언어를 쓰겠다. 종이를 같이 접으면서 말로 순서를 설명해 줘도 친구가 나중에 잊어버릴 수 있기 때문이다. 순서를 글로 적어 주면 기록으로 남아 친구가 필요할 때 다시 보며 접을 수 있다.","scoring_points":["알맞은 언어를 골랐는가","고른 언어의 특성(기록으로 남음·다시 볼 수 있음 등)을 까닭으로 썼는가","상황과 이어지게 썼는가"]},"explanation":["상황 1은 복잡한 종이접기 순서를 설명하는 상황이에요.","순서가 여럿이면 다시 볼 수 있는 글이 알맞아요.","고른 까닭을 특성과 이어 써요."],"asset":{"type":"passage","lines":["상황 1 우리 반 친구에게 복잡한 종이접기 순서를 설명해 주는 상황","상황 2 어제 말다툼을 한 친구에게 미안한 마음을 전하고 싶은 상황"],"numbered":false,"title":"『국어』 227쪽 4번"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L02_challenge#9','kor',6,2,'u5','L02','tb_g6_2_kor_u5_L02_challenge','lesson_challenge','K6-2-u5-C27',4,'essay','teacher','「‘작가와의 만남’ 행사 안내」에서 찾을 수 있는 문자 언어의 특성을 두 가지 쓰세요. 날짜나 장소 같은 내용을 되풀이하지 말고, 글이 정보를 어떻게 전하는지에 초점을 두세요.','{}'::text[],false,'{"seq":9,"concept":"K6-2-u5-C27","difficulty":4,"kind":"essay","stem":"「‘작가와의 만남’ 행사 안내」에서 찾을 수 있는 문자 언어의 특성을 두 가지 쓰세요. 날짜나 장소 같은 내용을 되풀이하지 말고, 글이 정보를 어떻게 전하는지에 초점을 두세요.","answer_guide":{"answer":"예: 첫째, 글자로 쓰여 있어서 나중에 다시 읽으며 자리나 준비할 일을 확인할 수 있다. 둘째, 제목은 큰 글자로 쓰고 중요한 내용은 글자 크기나 굵기를 다르게 하거나 따옴표를 붙여 강조해서 어떤 정보가 중요한지 금방 알 수 있다.","scoring_points":["다시 볼 수 있음·보존 같은 특성을 썼는가","글자 크기·굵기·문장 부호로 강조하는 특성을 썼는가","내용 되풀이가 아니라 표현 방식에 초점을 두었는가"]},"explanation":["「어떤 정보가 중요한지 쉽게 알 수 있었는가?」를 떠올려요.","「왜 글자의 크기나 배열을 다르게 했을까?」도 생각해요.","특성은 글이 정보를 전하는 방식이에요."],"asset":{"type":"passage","lines":["일시 11월 ○○일 수요일 3교시","장소 1층 시청각실","주제 꿈으로 책 쓰기(작가 김○○)","[자리 안내] 6학년 하늘반은 시청각실 첫째 줄부터 셋째 줄까지 앉는다.","[자리 안내] 이동 시간이 겹치지 않도록 3교시 시작 5분 전까지 앉는다.","[준비할 일] 학교 도서관 ‘이달의 추천 도서’인 작가님의 책을 읽고 질문을 생각해 온다.","[준비할 일] 작가님께 질문하고 대답을 듣는 시간이 있다."],"numbered":false,"title":"「‘작가와의 만남’ 행사 안내」(『국어』 224쪽, 간추림)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L02_challenge#10','kor',6,2,'u5','L02','tb_g6_2_kor_u5_L02_challenge','lesson_challenge','K6-2-u5-C28',4,'essay','teacher','「선생님의 안내 말씀」을 듣는 친구에게 알려 줄, 음성 언어의 특성을 생각한 듣기 방법을 두 가지 쓰고 까닭을 함께 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-2-u5-C28","difficulty":4,"kind":"essay","stem":"「선생님의 안내 말씀」을 듣는 친구에게 알려 줄, 음성 언어의 특성을 생각한 듣기 방법을 두 가지 쓰고 까닭을 함께 쓰세요.","answer_guide":{"answer":"예: 첫째, 선생님 목소리가 커지거나 또박또박해지는 부분을 잘 듣는다. 목소리의 크기나 억양으로 중요한 내용을 강조하기 때문이다. 둘째, 시각과 장소처럼 중요한 내용은 간단히 메모하며 듣는다. 말은 끝나면 소리가 사라져 다시 확인하기 어렵기 때문이다.","scoring_points":["목소리의 크기·억양에 주의하는 방법을 썼는가","메모하며 듣기 같은 방법을 썼는가","방법마다 음성 언어의 특성을 까닭으로 썼는가"]},"explanation":["음성 언어는 목소리로 중요한 곳을 알려 줘요.","말은 끝나면 사라져요.","그래서 귀 기울이고 메모하며 들어요."],"asset":{"type":"passage","lines":["(간추림) 내일 재능 발표회는 오전 9시 30분에 학교 강당에서 시작된다.","[이 부분은 목소리를 크고 또박또박하게 말씀하신다.]","(간추림) 발표하는 친구는 등교하자마자 강당에 가서 나무반 선생님께 말씀드린다.","(간추림) 관람하는 친구는 교실에 모였다가 9시에 선생님과 함께 강당으로 간다.","(간추림) 6학년 자리는 무대를 바라보고 강당 오른편이다.","(간추림) 당부 셋 — 큰 박수로 응원 · 자리를 지키며 집중 · 뛰지 말고 안전하게"],"numbered":false,"title":"「선생님의 안내 말씀」(『국어』 226쪽 듣기 자료, 간추림)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L04_basic#1','kor',6,2,'u5','L04','tb_g6_2_kor_u5_L04_basic','lesson_basic','K6-2-u5-C29',1,'mc','auto','「아동 안전 ― 운전자가 보호자 ―」의 주제로 예시 답안과 같은 것은 무엇인가요?',ARRAY['K6-2-u5-X15','K6-2-u5-X12']::text[],false,'{"seq":1,"concept":"K6-2-u5-C29","difficulty":1,"kind":"mc","stem":"「아동 안전 ― 운전자가 보호자 ―」의 주제로 예시 답안과 같은 것은 무엇인가요?","options":[{"t":"아동의 안전을 위해 운전하는 사람이 차량 안전을 생각해야 한다","correct":true},{"t":"영상에 나오는 음악이 신나고 화면이 멋지다","mis":"K6-2-u5-X15"},{"t":"도로 위에 운전면허증 모양의 글자가 나온다","mis":"K6-2-u5-X12"},{"t":"어린이 보호 구역 표지판이 길가에 서 있다","mis":"K6-2-u5-X12"}],"explanation":["주제는 영상이 전하려는 중심 생각이에요.","운전하는 사람과 아동이 같이 조심하면 안전해질 수 있다는 답도 있어요.","느낌이나 표현 요소는 주제가 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L04_basic#2','kor',6,2,'u5','L04','tb_g6_2_kor_u5_L04_basic','lesson_basic','K6-2-u5-C29',1,'mc','auto','「아동 안전 ― 운전자가 보호자 ―」를 만든 까닭으로 알맞은 것은 무엇인가요?',ARRAY['K6-2-u5-X05']::text[],false,'{"seq":2,"concept":"K6-2-u5-C29","difficulty":1,"kind":"mc","stem":"「아동 안전 ― 운전자가 보호자 ―」를 만든 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"공공의 이익을 위해 여러 사람에게 효과적으로 알리려고","correct":true},{"t":"영상을 만든 사람의 이름을 알리려고","mis":"K6-2-u5-X05"},{"t":"영상을 본 사람 수를 늘려 인기를 얻으려고","mis":"K6-2-u5-X05"}],"explanation":["이 영상은 공익 광고예요.","공공의 이익을 위해 만들었어요.","여러 사람에게 효과적으로 무엇인가를 알리려는 것이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L04_basic#3','kor',6,2,'u5','L04','tb_g6_2_kor_u5_L04_basic','lesson_basic','K6-2-u5-C8',1,'sa','auto','『국어』 228쪽 (3)의 예시 답안이에요. 「동영상, 대사, (    ), 음악 등으로 정보를 전달하고 있습니다.」 빈칸에 알맞은 두 글자 낱말을 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"K6-2-u5-C8","difficulty":1,"kind":"sa","stem":"『국어』 228쪽 (3)의 예시 답안이에요. 「동영상, 대사, (    ), 음악 등으로 정보를 전달하고 있습니다.」 빈칸에 알맞은 두 글자 낱말을 쓰세요.","answer":["자막"],"explanation":["영상에는 여러 표현 방법이 함께 쓰여요.","화면에 나오는 글자를 자막이라고 해요.","동영상, 대사, 자막, 음악이 어우러져 정보를 전해요."],"mis":"K6-2-u5-X12"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L04_basic#4','kor',6,2,'u5','L04','tb_g6_2_kor_u5_L04_basic','lesson_basic','K6-2-u5-C9',1,'ox','auto','『국어』 229쪽 장면 ㉡에서는 어린이 보호 구역 표지판과 자막으로 속도를 줄여야 한다는 내용을 전달해요.',ARRAY['K6-2-u5-X12']::text[],false,'{"seq":4,"concept":"K6-2-u5-C9","difficulty":1,"kind":"ox","stem":"『국어』 229쪽 장면 ㉡에서는 어린이 보호 구역 표지판과 자막으로 속도를 줄여야 한다는 내용을 전달해요.","answer":"O","reason_options":[{"t":"표지판과 「스쿨 존에서는 속도를 줄이고」라는 자막을 함께 보여 주기 때문에","correct":true},{"t":"음성 언어로만 설명하고 글자는 쓰지 않기 때문에","mis":"K6-2-u5-X12"}],"mis":"K6-2-u5-X12","explanation":["장면 ㉡에 어린이 보호 구역 표지판이 나와요.","「스쿨 존에서는 속도를 줄이고」라는 자막도 나와요.","글자로 보여 주어 중요한 내용을 또렷하게 전해요."],"asset":{"type":"passage","lines":["㉠ [음성 언어] 「도로에서는 운전자가 보호자입니다.」라고 설명한다.","㉠ [문자 언어] 「운전면허는 보행자 보호 면허」라는 글자를 운전면허증처럼 도로 위에","㉡ 어린이 보호 구역 표지판과 「스쿨 존에서는 속도를 줄이고」라는 자막","㉢ [음성 언어] 「지켜 주셔서 고맙습니다.」라는 아이의 말과 안전하게 길을 건너는 장면"],"numbered":false,"title":"「아동 안전 ― 운전자가 보호자 ―」(『국어』 229쪽 장면 설명)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L04_basic#5','kor',6,2,'u5','L04','tb_g6_2_kor_u5_L04_basic','lesson_basic','K6-2-u5-C9',2,'mc','auto','『국어』 229쪽 장면 ㉠에서 문자 언어로 나타낸 표현 방법은 무엇인가요?',ARRAY['K6-2-u5-X01','K6-2-u5-X12']::text[],false,'{"seq":5,"concept":"K6-2-u5-C9","difficulty":2,"kind":"mc","stem":"『국어』 229쪽 장면 ㉠에서 문자 언어로 나타낸 표현 방법은 무엇인가요?","options":[{"t":"「운전면허는 보행자 보호 면허」라는 글자를 운전면허증처럼 도로 위에 보여 주었다","correct":true},{"t":"「도로에서는 운전자가 보호자입니다.」라고 목소리로 설명했다","mis":"K6-2-u5-X01"},{"t":"아이가 「지켜 주셔서 고맙습니다.」라고 목소리로 말했다","mis":"K6-2-u5-X01"},{"t":"장면 내내 잔잔한 배경 음악만 들려주었다","mis":"K6-2-u5-X12"}],"explanation":["문자 언어는 글자로 나타내는 말이에요.","장면 ㉠은 「운전면허는 보행자 보호 면허」라는 글자를 보여 줘요.","목소리로 한 설명과 아이의 말은 음성 언어예요."],"asset":{"type":"passage","lines":["㉠ [음성 언어] 「도로에서는 운전자가 보호자입니다.」라고 설명한다.","㉠ [문자 언어] 「운전면허는 보행자 보호 면허」라는 글자를 운전면허증처럼 도로 위에","㉡ 어린이 보호 구역 표지판과 「스쿨 존에서는 속도를 줄이고」라는 자막","㉢ [음성 언어] 「지켜 주셔서 고맙습니다.」라는 아이의 말과 안전하게 길을 건너는 장면"],"numbered":false,"title":"「아동 안전 ― 운전자가 보호자 ―」(『국어』 229쪽 장면 설명)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L04_basic#6','kor',6,2,'u5','L04','tb_g6_2_kor_u5_L04_basic','lesson_basic','K6-2-u5-C9',2,'mc','auto','『국어』 230쪽 3번에서 「이해하기 어렵거나 헷갈리는 내용에는 문자 언어와 음성 언어를 같이 사용할 수 있어.」라고 했어요. 두 언어를 같이 쓰는 까닭은 무엇인가요?',ARRAY['K6-2-u5-X11','K6-2-u5-X13','K6-2-u5-X03']::text[],false,'{"seq":6,"concept":"K6-2-u5-C9","difficulty":2,"kind":"mc","stem":"『국어』 230쪽 3번에서 「이해하기 어렵거나 헷갈리는 내용에는 문자 언어와 음성 언어를 같이 사용할 수 있어.」라고 했어요. 두 언어를 같이 쓰는 까닭은 무엇인가요?","options":[{"t":"두 언어가 서로를 보완해 어려운 내용을 효과적으로 전할 수 있기 때문","correct":true},{"t":"같은 내용이 겹치면 시간을 채울 수 있기 때문","mis":"K6-2-u5-X11"},{"t":"언어를 많이 쓸수록 무조건 좋기 때문","mis":"K6-2-u5-X13"},{"t":"음성 언어만으로는 아무것도 전할 수 없기 때문","mis":"K6-2-u5-X03"}],"explanation":["어렵거나 헷갈리는 내용은 한 번 듣고 알기 어려워요.","말로 설명하고 글로도 보여 주면 서로 보완해요.","많이 쓰는 것이 목적이 아니라 잘 전하는 것이 목적이에요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"동영상을 볼 때 음성 언어의 내용을 요약해서 문자 언어로 보여 주면 이해하기가 쉬워."},{"who":"친구 2","text":"이해하기 어렵거나 헷갈리는 내용에는 문자 언어와 음성 언어를 같이 사용할 수 있어."},{"who":"친구 3","text":"문자 언어는 다양한 색, 크기, 모양으로 내용을 강조할 수 있어. 음성 언어는 음악이나 소리를 함께 사용해 내용을 강조할 수 있어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L04_basic#7','kor',6,2,'u5','L04','tb_g6_2_kor_u5_L04_basic','lesson_basic','K6-2-u5-C8',2,'blank','auto','『국어』 230쪽 4번의 정리예요. 「영상 매체는 음성 언어, 문자 언어, 동영상, 음악, 소리 같은 것이 다양하게 어우러져 정보를 전달하는 매체이다. (    ) 같은 것이 있다.」 빈칸에 알맞은 것은 무엇인가요?',ARRAY['K6-2-u5-X04']::text[],false,'{"seq":7,"concept":"K6-2-u5-C8","difficulty":2,"kind":"blank","stem":"『국어』 230쪽 4번의 정리예요. 「영상 매체는 음성 언어, 문자 언어, 동영상, 음악, 소리 같은 것이 다양하게 어우러져 정보를 전달하는 매체이다. (    ) 같은 것이 있다.」 빈칸에 알맞은 것은 무엇인가요?","options":[{"t":"텔레비전","correct":true},{"t":"신문","mis":"K6-2-u5-X04"},{"t":"오디오 북","mis":"K6-2-u5-X04"},{"t":"책","mis":"K6-2-u5-X04"}],"explanation":["영상 매체는 여러 표현 방법이 어우러져요.","텔레비전이 영상 매체의 예예요.","신문과 책은 인쇄 매체, 오디오 북은 음성 매체예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L04_basic#8','kor',6,2,'u5','L04','tb_g6_2_kor_u5_L04_basic','lesson_basic','K6-2-u5-C9',2,'match','auto','『국어』 230쪽 3번에서 친구들이 말한 내용을 알맞게 이으세요.','{}'::text[],false,'{"seq":8,"concept":"K6-2-u5-C9","difficulty":2,"kind":"match","stem":"『국어』 230쪽 3번에서 친구들이 말한 내용을 알맞게 이으세요.","pairs":[{"l":"문자 언어로 강조할 때","r":"다양한 색, 크기, 모양을 쓴다"},{"l":"음성 언어로 강조할 때","r":"음악이나 소리를 함께 쓴다"},{"l":"음성 언어의 내용을 요약해 문자 언어로 보여 주면","r":"이해하기가 쉬워진다"}],"mis":"K6-2-u5-X06","explanation":["글은 색, 크기, 모양으로 눈에 띄게 해요.","말은 음악이나 소리로 귀에 띄게 해요.","말을 글로 요약해 보여 주면 이해하기 쉬워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L04_basic#9','kor',6,2,'u5','L04','tb_g6_2_kor_u5_L04_basic','lesson_basic','K6-2-u5-C10',2,'ox','auto','『국어』 229쪽 장면 ㉢처럼 아이의 말(음성 언어)과 장면을 함께 보여 주면, 전하려는 내용이 더 생생하게 전달돼요.',ARRAY['K6-2-u5-X11']::text[],false,'{"seq":9,"concept":"K6-2-u5-C10","difficulty":2,"kind":"ox","stem":"『국어』 229쪽 장면 ㉢처럼 아이의 말(음성 언어)과 장면을 함께 보여 주면, 전하려는 내용이 더 생생하게 전달돼요.","answer":"O","reason_options":[{"t":"말과 장면이 어우러져 운전자가 지켜 준 덕분에 아이가 안전하게 길을 건넌다는 것을 한눈에 알 수 있기 때문에","correct":true},{"t":"여러 요소를 함께 쓰면 전하려는 내용이 흐려지기만 하기 때문에","mis":"K6-2-u5-X11"}],"mis":"K6-2-u5-X11","explanation":["장면 ㉢은 「지켜 주셔서 고맙습니다.」라는 아이의 말을 들려줘요.","안전하게 길을 건너는 장면도 함께 보여 줘요.","말과 장면이 함께 주제를 전해요."],"asset":{"type":"passage","lines":["㉠ [음성 언어] 「도로에서는 운전자가 보호자입니다.」라고 설명한다.","㉠ [문자 언어] 「운전면허는 보행자 보호 면허」라는 글자를 운전면허증처럼 도로 위에","㉡ 어린이 보호 구역 표지판과 「스쿨 존에서는 속도를 줄이고」라는 자막","㉢ [음성 언어] 「지켜 주셔서 고맙습니다.」라는 아이의 말과 안전하게 길을 건너는 장면"],"numbered":false,"title":"「아동 안전 ― 운전자가 보호자 ―」(『국어』 229쪽 장면 설명)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L04_basic#10','kor',6,2,'u5','L04','tb_g6_2_kor_u5_L04_basic','lesson_basic','K6-2-u5-C10',3,'mc','auto','『국어』 230쪽 3번에서 「동영상을 볼 때 음성 언어의 내용을 요약해서 문자 언어로 보여 주면 이해하기가 쉬워.」라고 했어요. 이 말에 비추어 자막을 쓰는 방법으로 가장 알맞은 것은 무엇인가요?',ARRAY['K6-2-u5-X13','K6-2-u5-X12']::text[],false,'{"seq":10,"concept":"K6-2-u5-C10","difficulty":3,"kind":"mc","stem":"『국어』 230쪽 3번에서 「동영상을 볼 때 음성 언어의 내용을 요약해서 문자 언어로 보여 주면 이해하기가 쉬워.」라고 했어요. 이 말에 비추어 자막을 쓰는 방법으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"해설하는 말의 중요한 내용을 간추려 자막으로 보여 준다","correct":true},{"t":"해설하는 말을 한 글자도 빼지 않고 화면 가득 자막으로 채운다","mis":"K6-2-u5-X13"},{"t":"자막은 아무 때나 많이 넣을수록 좋다","mis":"K6-2-u5-X13"},{"t":"말과 다른 내용을 자막으로 보여 준다","mis":"K6-2-u5-X12"}],"explanation":["친구는 「요약해서」 보여 주라고 했어요.","중요한 내용을 간추리면 무엇이 중요한지 또렷해져요.","자막이 많다고 잘 전달되는 것은 아니에요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"동영상을 볼 때 음성 언어의 내용을 요약해서 문자 언어로 보여 주면 이해하기가 쉬워."},{"who":"친구 2","text":"이해하기 어렵거나 헷갈리는 내용에는 문자 언어와 음성 언어를 같이 사용할 수 있어."},{"who":"친구 3","text":"문자 언어는 다양한 색, 크기, 모양으로 내용을 강조할 수 있어. 음성 언어는 음악이나 소리를 함께 사용해 내용을 강조할 수 있어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L04_challenge#1','kor',6,2,'u5','L04','tb_g6_2_kor_u5_L04_challenge','lesson_challenge','K6-2-u5-C29',2,'sa','auto','『국어』 228쪽 (1)의 예시 답안이에요. 「서로 (    )하면 함께 행복해질 수 있다는 것입니다.」 빈칸에 알맞은 두 글자 낱말을 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K6-2-u5-C29","difficulty":2,"kind":"sa","stem":"『국어』 228쪽 (1)의 예시 답안이에요. 「서로 (    )하면 함께 행복해질 수 있다는 것입니다.」 빈칸에 알맞은 두 글자 낱말을 쓰세요.","answer":["배려"],"explanation":["「아동 안전 ― 운전자가 보호자 ―」의 주제를 정리한 답이에요.","운전하는 사람과 아동이 서로 생각해 주는 것을 배려라고 해요.","서로 배려하면 함께 행복해질 수 있어요."],"mis":"K6-2-u5-X15"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L04_challenge#2','kor',6,2,'u5','L04','tb_g6_2_kor_u5_L04_challenge','lesson_challenge','K6-2-u5-C8',2,'mc','auto','「아동 안전 ― 운전자가 보호자 ―」에서 정보를 전달하는 표현 방법이 아닌 것은 무엇인가요?',ARRAY['K6-2-u5-X12']::text[],false,'{"seq":2,"concept":"K6-2-u5-C8","difficulty":2,"kind":"mc","stem":"「아동 안전 ― 운전자가 보호자 ―」에서 정보를 전달하는 표현 방법이 아닌 것은 무엇인가요?","options":[{"t":"영상을 올린 날짜","correct":true},{"t":"「도로에서는 운전자가 보호자입니다.」 같은 대사","mis":"K6-2-u5-X12"},{"t":"「스쿨 존에서는 속도를 줄이고」 같은 자막","mis":"K6-2-u5-X12"},{"t":"장면에 함께 나오는 음악","mis":"K6-2-u5-X12"}],"explanation":["동영상, 대사, 자막, 음악 등으로 정보를 전달해요.","이것들은 화면과 소리로 뜻을 날라요.","올린 날짜는 내용을 전하는 표현 방법이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L04_challenge#3','kor',6,2,'u5','L04','tb_g6_2_kor_u5_L04_challenge','lesson_challenge','K6-2-u5-C9',3,'mc','auto','『국어』 229쪽 장면 ㉠에서 음성 언어로 「도로에서는 운전자가 보호자입니다.」라고 설명하면서 「운전면허는 보행자 보호 면허」라는 글자를 함께 보여 준 효과로 가장 알맞은 것은 무엇인가요?',ARRAY['K6-2-u5-X12','K6-2-u5-X05','K6-2-u5-X11']::text[],false,'{"seq":3,"concept":"K6-2-u5-C9","difficulty":3,"kind":"mc","stem":"『국어』 229쪽 장면 ㉠에서 음성 언어로 「도로에서는 운전자가 보호자입니다.」라고 설명하면서 「운전면허는 보행자 보호 면허」라는 글자를 함께 보여 준 효과로 가장 알맞은 것은 무엇인가요?","options":[{"t":"말로 설명한 내용을 글자로 정리·강조해 운전자의 책임을 또렷하게 전한다","correct":true},{"t":"두 언어가 서로 다른 내용을 말해 궁금증을 남긴다","mis":"K6-2-u5-X12"},{"t":"글자를 넣어 도로 장면을 화려하고 멋지게 꾸민다","mis":"K6-2-u5-X05"},{"t":"같은 말을 말과 글로 되풀이해 쓸모가 없다","mis":"K6-2-u5-X11"}],"explanation":["동영상은 음성 언어로 설명하면서 문자 언어로도 정리하거나 강조해요.","운전자가 보행자를 보호해야 한다는 뜻이 또렷해져요.","꾸밈이나 되풀이가 아니라 효과적으로 전하려는 것이에요."],"asset":{"type":"passage","lines":["㉠ [음성 언어] 「도로에서는 운전자가 보호자입니다.」라고 설명한다.","㉠ [문자 언어] 「운전면허는 보행자 보호 면허」라는 글자를 운전면허증처럼 도로 위에","㉡ 어린이 보호 구역 표지판과 「스쿨 존에서는 속도를 줄이고」라는 자막","㉢ [음성 언어] 「지켜 주셔서 고맙습니다.」라는 아이의 말과 안전하게 길을 건너는 장면"],"numbered":false,"title":"「아동 안전 ― 운전자가 보호자 ―」(『국어』 229쪽 장면 설명)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L04_challenge#4','kor',6,2,'u5','L04','tb_g6_2_kor_u5_L04_challenge','lesson_challenge','K6-2-u5-C10',3,'error','auto','『국어』 230쪽 3번을 읽고 친구들이 매체의 표현 방법을 이야기했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-2-u5-X13','K6-2-u5-X06']::text[],false,'{"seq":4,"concept":"K6-2-u5-C10","difficulty":3,"kind":"error","stem":"『국어』 230쪽 3번을 읽고 친구들이 매체의 표현 방법을 이야기했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"친구 3 — 「자막과 음악은 많이 넣을수록 내용이 잘 전달돼.」","correct":true,"mis_target":"K6-2-u5-X13"},{"t":"친구 1 — 「문자 언어는 색이나 크기, 모양을 바꾸어 내용을 강조할 수 있어.」","mis":"K6-2-u5-X06"},{"t":"친구 2 — 「음성 언어는 음악이나 소리를 함께 써서 내용을 강조할 수 있어.」","mis":"K6-2-u5-X06"}],"explanation":["친구 1과 친구 2는 『국어』에 나온 강조 방법을 말했어요.","자막과 음악이 많으면 무엇이 중요한지 오히려 흐려질 수 있어요.","표현 효과는 개수가 아니라 무엇을 돕는가로 봐요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"동영상을 볼 때 음성 언어의 내용을 요약해서 문자 언어로 보여 주면 이해하기가 쉬워."},{"who":"친구 2","text":"이해하기 어렵거나 헷갈리는 내용에는 문자 언어와 음성 언어를 같이 사용할 수 있어."},{"who":"친구 3","text":"문자 언어는 다양한 색, 크기, 모양으로 내용을 강조할 수 있어. 음성 언어는 음악이나 소리를 함께 사용해 내용을 강조할 수 있어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L04_challenge#5','kor',6,2,'u5','L04','tb_g6_2_kor_u5_L04_challenge','lesson_challenge','K6-2-u5-C9',3,'ox','auto','동영상에서 음성 언어로 설명한 내용을 문자 언어(자막)로 다시 보여 주는 것은 같은 내용을 겹쳐 써서 쓸모없는 일이에요.',ARRAY['K6-2-u5-X11']::text[],false,'{"seq":5,"concept":"K6-2-u5-C9","difficulty":3,"kind":"ox","stem":"동영상에서 음성 언어로 설명한 내용을 문자 언어(자막)로 다시 보여 주는 것은 같은 내용을 겹쳐 써서 쓸모없는 일이에요.","answer":"X","reason_options":[{"t":"말로 들은 내용을 글자로 정리하거나 강조해 더 효과적으로 전달하기 때문에","correct":true},{"t":"한 가지 언어로 전하면 충분하므로 다른 언어는 방해가 되기 때문에","mis":"K6-2-u5-X11"}],"mis":"K6-2-u5-X11","explanation":["말은 들은 뒤 사라지지만 글자는 화면에 남아요.","자막은 말한 내용을 정리하고 강조해 줘요.","두 언어는 서로를 보완해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L04_challenge#6','kor',6,2,'u5','L04','tb_g6_2_kor_u5_L04_challenge','lesson_challenge','K6-2-u5-C29',3,'mc','auto','『국어』 228쪽 (2)의 예시 답안처럼 「아동 안전 ― 운전자가 보호자 ―」가 공공의 이익을 위해 만든 영상이라고 볼 수 있는 까닭으로 가장 알맞은 것은 무엇인가요?',ARRAY['K6-2-u5-X12','K6-2-u5-X05']::text[],false,'{"seq":6,"concept":"K6-2-u5-C29","difficulty":3,"kind":"mc","stem":"『국어』 228쪽 (2)의 예시 답안처럼 「아동 안전 ― 운전자가 보호자 ―」가 공공의 이익을 위해 만든 영상이라고 볼 수 있는 까닭으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"어린이를 보호하자는, 여러 사람에게 도움이 되는 내용을 알리기 때문","correct":true},{"t":"영상에 배경 음악과 자막이 함께 나오기 때문","mis":"K6-2-u5-X12"},{"t":"영상이 짧아서 많은 사람이 끝까지 볼 수 있기 때문","mis":"K6-2-u5-X05"},{"t":"영상을 만든 사람의 이름이 화면에 나오기 때문","mis":"K6-2-u5-X05"}],"explanation":["공익 광고는 여러 사람에게 도움이 되는 내용을 알려요.","이 영상은 운전하는 사람이 아동의 안전을 지키자고 알려요.","음악이나 길이로 만든 까닭을 알 수는 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L04_challenge#7','kor',6,2,'u5','L04','tb_g6_2_kor_u5_L04_challenge','lesson_challenge','K6-2-u5-C29',3,'match','auto','「아동 안전 ― 운전자가 보호자 ―」의 장면과 주로 쓴 표현 방법을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K6-2-u5-C29","difficulty":3,"kind":"match","stem":"「아동 안전 ― 운전자가 보호자 ―」의 장면과 주로 쓴 표현 방법을 알맞게 이으세요.","pairs":[{"l":"장면 ㉠","r":"음성 언어 설명과 운전면허증 모양의 글자"},{"l":"장면 ㉡","r":"어린이 보호 구역 표지판과 자막"},{"l":"장면 ㉢","r":"아이의 말과 안전하게 길을 건너는 장면"}],"mis":"K6-2-u5-X14","explanation":["장면마다 전하려는 내용이 달라요.","그래서 쓰는 표현 방법도 달라요.","장면 ㉡은 표지판과 자막으로 속도를 줄이자고 해요."],"asset":{"type":"passage","lines":["㉠ [음성 언어] 「도로에서는 운전자가 보호자입니다.」라고 설명한다.","㉠ [문자 언어] 「운전면허는 보행자 보호 면허」라는 글자를 운전면허증처럼 도로 위에","㉡ 어린이 보호 구역 표지판과 「스쿨 존에서는 속도를 줄이고」라는 자막","㉢ [음성 언어] 「지켜 주셔서 고맙습니다.」라는 아이의 말과 안전하게 길을 건너는 장면"],"numbered":false,"title":"「아동 안전 ― 운전자가 보호자 ―」(『국어』 229쪽 장면 설명)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L04_challenge#8','kor',6,2,'u5','L04','tb_g6_2_kor_u5_L04_challenge','lesson_challenge','K6-2-u5-C29',4,'essay','teacher','「아동 안전 ― 운전자가 보호자 ―」의 장면 ㉠~㉢ 가운데 하나를 골라, 그 장면에서 문자 언어나 음성 언어를 어떻게 썼는지와 그 표현 효과를 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K6-2-u5-C29","difficulty":4,"kind":"essay","stem":"「아동 안전 ― 운전자가 보호자 ―」의 장면 ㉠~㉢ 가운데 하나를 골라, 그 장면에서 문자 언어나 음성 언어를 어떻게 썼는지와 그 표현 효과를 쓰세요.","answer_guide":{"answer":"예: 장면 ㉡에서는 어린이 보호 구역 표지판과 「스쿨 존에서는 속도를 줄이고」라는 자막을 함께 보여 준다. 글자로 또렷하게 보여 주니 어린이 보호 구역에서는 속도를 줄여야 한다는 내용을 한눈에 알고 오래 기억할 수 있다.","scoring_points":["장면 하나를 골랐는가","그 장면에서 쓴 문자 언어나 음성 언어를 바르게 썼는가","그 표현이 무엇을 돕는지 효과를 썼는가"]},"explanation":["먼저 장면에서 쓰인 언어를 찾아요.","그 언어가 내용 전달을 어떻게 돕는지 이어요.","효과는 「그래서 무엇이 좋아졌나」예요."],"asset":{"type":"passage","lines":["㉠ [음성 언어] 「도로에서는 운전자가 보호자입니다.」라고 설명한다.","㉠ [문자 언어] 「운전면허는 보행자 보호 면허」라는 글자를 운전면허증처럼 도로 위에","㉡ 어린이 보호 구역 표지판과 「스쿨 존에서는 속도를 줄이고」라는 자막","㉢ [음성 언어] 「지켜 주셔서 고맙습니다.」라는 아이의 말과 안전하게 길을 건너는 장면"],"numbered":false,"title":"「아동 안전 ― 운전자가 보호자 ―」(『국어』 229쪽 장면 설명)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L04_challenge#9','kor',6,2,'u5','L04','tb_g6_2_kor_u5_L04_challenge','lesson_challenge','K6-2-u5-C9',4,'essay','teacher','『국어』 230쪽 3번의 친구들 말을 바탕으로, 매체에서 문자 언어와 음성 언어를 함께 쓰면 좋은 점을 두 가지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-2-u5-C9","difficulty":4,"kind":"essay","stem":"『국어』 230쪽 3번의 친구들 말을 바탕으로, 매체에서 문자 언어와 음성 언어를 함께 쓰면 좋은 점을 두 가지 쓰세요.","answer_guide":{"answer":"예: 첫째, 음성 언어의 내용을 요약해서 문자 언어로 보여 주면 이해하기 쉽다. 둘째, 이해하기 어렵거나 헷갈리는 내용은 두 언어를 같이 써서 서로 보완하면 정확하게 전할 수 있다.","scoring_points":["요약해 보여 주면 이해하기 쉽다는 점을 썼는가","어려운 내용을 두 언어가 보완한다는 점을 썼는가","두 가지를 갈라 썼는가"]},"explanation":["말을 글로 요약하면 이해하기 쉬워요.","헷갈리는 내용은 두 언어가 함께 전해요.","말과 글은 서로를 보완해요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"동영상을 볼 때 음성 언어의 내용을 요약해서 문자 언어로 보여 주면 이해하기가 쉬워."},{"who":"친구 2","text":"이해하기 어렵거나 헷갈리는 내용에는 문자 언어와 음성 언어를 같이 사용할 수 있어."},{"who":"친구 3","text":"문자 언어는 다양한 색, 크기, 모양으로 내용을 강조할 수 있어. 음성 언어는 음악이나 소리를 함께 사용해 내용을 강조할 수 있어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L04_challenge#10','kor',6,2,'u5','L04','tb_g6_2_kor_u5_L04_challenge','lesson_challenge','K6-2-u5-C10',4,'essay','teacher','『국어』 230쪽 5번처럼 언어의 표현 효과를 생각하며 매체 자료를 보거나 들은 경험을 하나 쓰세요. 어떤 매체에서 어떤 언어 표현이 쓰였고, 그것이 무엇을 도왔는지 함께 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-2-u5-C10","difficulty":4,"kind":"essay","stem":"『국어』 230쪽 5번처럼 언어의 표현 효과를 생각하며 매체 자료를 보거나 들은 경험을 하나 쓰세요. 어떤 매체에서 어떤 언어 표현이 쓰였고, 그것이 무엇을 도왔는지 함께 쓰세요.","answer_guide":{"answer":"예: 텔레비전 뉴스에서 기자가 말로 설명할 때 화면 아래에 중요한 내용이 자막으로 나왔다. 그래서 말을 놓쳐도 자막을 보고 무슨 일이 있었는지 정확하게 알 수 있었다.","scoring_points":["매체와 그 매체에 쓰인 언어 표현을 썼는가","그 표현이 무엇을 도왔는지 썼는가","자신의 경험으로 썼는가"]},"explanation":["경험한 매체를 떠올려요.","말, 글, 음악 가운데 무엇이 쓰였는지 찾아요.","그 표현 덕분에 무엇이 좋았는지 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L05_basic#1','kor',6,2,'u5','L05','tb_g6_2_kor_u5_L05_basic','lesson_basic','K6-2-u5-C30',1,'mc','auto','『국어』 232쪽 (1)의 예시 답안처럼 화산 쇄설층이 만들어진 과정으로 알맞은 것은 무엇인가요?',ARRAY['K6-2-u5-X41']::text[],false,'{"seq":1,"concept":"K6-2-u5-C30","difficulty":1,"kind":"mc","stem":"『국어』 232쪽 (1)의 예시 답안처럼 화산 쇄설층이 만들어진 과정으로 알맞은 것은 무엇인가요?","options":[{"t":"지하에서 올라온 마그마가 지표에 있는 물과 만나 폭발한 뒤, 화산재와 화산 쇄설물들이 쌓여 만들어졌다","correct":true},{"t":"화산에서 흘러나온 용암이 바다 쪽으로 천천히 흘러내려 그대로 굳어 만들어졌다","mis":"K6-2-u5-X41"},{"t":"오랜 세월 동안 파도가 해안 절벽을 조금씩 깎아 내어 만들어졌다","mis":"K6-2-u5-X41"},{"t":"바닷속 모래와 조개껍데기가 쌓였다가 땅 위로 솟아올라 만들어졌다","mis":"K6-2-u5-X41"}],"explanation":["마그마가 지표의 물과 만나 폭발했어요.","그때 나온 화산재와 화산 쇄설물이 쌓였어요.","그렇게 쌓인 지층이 화산 쇄설층이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L05_basic#2','kor',6,2,'u5','L05','tb_g6_2_kor_u5_L05_basic','lesson_basic','K6-2-u5-C31',1,'sa','auto','『국어』 231쪽의 뜻풀이예요. 「암석 부스러기가 쌓여 형성된 지층」을 무엇이라고 하나요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"K6-2-u5-C31","difficulty":1,"kind":"sa","stem":"『국어』 231쪽의 뜻풀이예요. 「암석 부스러기가 쌓여 형성된 지층」을 무엇이라고 하나요? 세 글자로 쓰세요.","answer":["쇄설층"],"explanation":["영상 제목 「수월봉 화산 쇄설층」에 나오는 낱말이에요.","암석 부스러기가 쌓여 형성된 지층을 쇄설층이라고 해요.","낯선 낱말은 뜻을 먼저 알고 영상을 보아요."],"mis":"K6-2-u5-X42"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L05_basic#3','kor',6,2,'u5','L05','tb_g6_2_kor_u5_L05_basic','lesson_basic','K6-2-u5-C11',1,'mc','auto','「수월봉 화산 쇄설층」의 장면 1에서 쓴 표현 방법은 무엇인가요?',ARRAY['K6-2-u5-X14']::text[],false,'{"seq":3,"concept":"K6-2-u5-C11","difficulty":1,"kind":"mc","stem":"「수월봉 화산 쇄설층」의 장면 1에서 쓴 표현 방법은 무엇인가요?","options":[{"t":"잔잔한 파도 소리와 음악이 들리며 제목이 나타난다","correct":true},{"t":"분화구 추정 위치를 글과 그림으로 표현한다","mis":"K6-2-u5-X14"},{"t":"긴장감이 느껴지는 음악을 사용한다","mis":"K6-2-u5-X14"}],"explanation":["장면 1은 영상이 시작되는 부분이에요.","파도 소리와 음악 속에 제목이 나타나요.","다른 방법은 장면 4와 장면 3에서 써요."],"asset":{"type":"passage","lines":["장면 1 잔잔한 파도 소리와 음악이 들리며 제목이 나타난다.","장면 2 해안 절벽을 다양한 각도로 보여 주고, 해설자의 말을 화면에 문자로 다시 보여 준다.","장면 3 새로운 탄생과 발견을 강조하려고 긴장감이 느껴지는 음악을 사용한다.","장면 4 분화구 추정 위치와 주변 지역을 글과 그림으로 표현한다.","장면 5 대상의 이름과 설명을 해설자의 음성 설명 없이 자막으로 보여 준다."],"numbered":false,"title":"「수월봉 화산 쇄설층」(『국어』 231쪽 장면 설명)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L05_basic#4','kor',6,2,'u5','L05','tb_g6_2_kor_u5_L05_basic','lesson_basic','K6-2-u5-C31',1,'ox','auto','『국어』 232쪽 낱말 알기에서 「지표」는 「지구의 표면」이라는 뜻이에요.',ARRAY['K6-2-u5-X42']::text[],false,'{"seq":4,"concept":"K6-2-u5-C31","difficulty":1,"kind":"ox","stem":"『국어』 232쪽 낱말 알기에서 「지표」는 「지구의 표면」이라는 뜻이에요.","answer":"O","reason_options":[{"t":"보기 낱말 가운데 지구의 표면을 뜻하는 낱말이 지표이기 때문에","correct":true},{"t":"지표는 화산 꼭대기에 생긴 분출구를 뜻하기 때문에","mis":"K6-2-u5-X42"}],"mis":"K6-2-u5-X42","explanation":["보기 낱말은 지층, 지표, 분화구, 화산재예요.","지구의 표면은 지표예요.","화산 꼭대기에 생긴 분출구는 분화구예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L05_basic#5','kor',6,2,'u5','L05','tb_g6_2_kor_u5_L05_basic','lesson_basic','K6-2-u5-C30',2,'mc','auto','『국어』 232쪽 (2)에서 화산 분화구의 중심을 바다 한가운데라고 추측한 까닭은 무엇인가요?',ARRAY['K6-2-u5-X41']::text[],false,'{"seq":5,"concept":"K6-2-u5-C30","difficulty":2,"kind":"mc","stem":"『국어』 232쪽 (2)에서 화산 분화구의 중심을 바다 한가운데라고 추측한 까닭은 무엇인가요?","options":[{"t":"화산탄이 일정한 각도인 것을 보고 추측했다","correct":true},{"t":"바다에 파도가 많이 쳐서","mis":"K6-2-u5-X41"},{"t":"해안 절벽이 길게 이어져 있어서","mis":"K6-2-u5-X41"},{"t":"화산재가 작물 재배에 도움이 되어서","mis":"K6-2-u5-X41"}],"explanation":["영상은 화산탄의 모습을 살펴봐요.","화산탄이 일정한 각도인 것이 실마리예요.","그것을 보고 분화구의 중심을 추측했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L05_basic#6','kor',6,2,'u5','L05','tb_g6_2_kor_u5_L05_basic','lesson_basic','K6-2-u5-C31',2,'blank','auto','『국어』 232쪽 낱말 알기예요. 「(    ): 화산에서 나온 용암의 부스러기 가운데 크기가 작은 알갱이.」 빈칸에 알맞은 낱말은 무엇인가요?',ARRAY['K6-2-u5-X42']::text[],false,'{"seq":6,"concept":"K6-2-u5-C31","difficulty":2,"kind":"blank","stem":"『국어』 232쪽 낱말 알기예요. 「(    ): 화산에서 나온 용암의 부스러기 가운데 크기가 작은 알갱이.」 빈칸에 알맞은 낱말은 무엇인가요?","options":[{"t":"화산재","correct":true},{"t":"분화구","mis":"K6-2-u5-X42"},{"t":"지층","mis":"K6-2-u5-X42"},{"t":"지표","mis":"K6-2-u5-X42"}],"explanation":["보기 낱말 가운데 알갱이를 뜻하는 낱말을 찾아요.","용암의 부스러기 가운데 크기가 작은 알갱이는 화산재예요.","분화구는 분출구, 지층은 퇴적암체, 지표는 지구의 표면이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L05_basic#7','kor',6,2,'u5','L05','tb_g6_2_kor_u5_L05_basic','lesson_basic','K6-2-u5-C11',2,'match','auto','「수월봉 화산 쇄설층」의 장면과 표현 방법을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K6-2-u5-C11","difficulty":2,"kind":"match","stem":"「수월봉 화산 쇄설층」의 장면과 표현 방법을 알맞게 이으세요.","pairs":[{"l":"장면 2","r":"해설자의 말을 화면에 문자로 다시 보여 준다"},{"l":"장면 3","r":"긴장감이 느껴지는 음악으로 새로운 탄생과 발견을 강조한다"},{"l":"장면 4","r":"분화구 추정 위치와 주변 지역을 글과 그림으로 나타낸다"}],"mis":"K6-2-u5-X14","explanation":["장면마다 전하려는 내용이 달라요.","그래서 쓰는 표현 방법도 달라요.","여러 표현 요소를 복합적으로 사용해 내용을 효과적으로 표현해요."],"asset":{"type":"passage","lines":["장면 1 잔잔한 파도 소리와 음악이 들리며 제목이 나타난다.","장면 2 해안 절벽을 다양한 각도로 보여 주고, 해설자의 말을 화면에 문자로 다시 보여 준다.","장면 3 새로운 탄생과 발견을 강조하려고 긴장감이 느껴지는 음악을 사용한다.","장면 4 분화구 추정 위치와 주변 지역을 글과 그림으로 표현한다.","장면 5 대상의 이름과 설명을 해설자의 음성 설명 없이 자막으로 보여 준다."],"numbered":false,"title":"「수월봉 화산 쇄설층」(『국어』 231쪽 장면 설명)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L05_basic#8','kor',6,2,'u5','L05','tb_g6_2_kor_u5_L05_basic','lesson_basic','K6-2-u5-C12',2,'mc','auto','『국어』 233쪽 (2)처럼 「수월봉 화산 쇄설층」에서 인상 깊었던 부분을 언어의 표현을 바탕으로 설명한 말은 무엇인가요?',ARRAY['K6-2-u5-X15']::text[],false,'{"seq":8,"concept":"K6-2-u5-C12","difficulty":2,"kind":"mc","stem":"『국어』 233쪽 (2)처럼 「수월봉 화산 쇄설층」에서 인상 깊었던 부분을 언어의 표현을 바탕으로 설명한 말은 무엇인가요?","options":[{"t":"화산 쇄설층을 설명할 때 문자 언어로도 제시해 주어서 내용을 쉽게 이해할 수 있었어.","correct":true},{"t":"영상이 정말 멋지고 재미있어서 처음부터 끝까지 그냥 좋았어.","mis":"K6-2-u5-X15"},{"t":"제주도 바다가 아름다워서 꼭 한번 가 보고 싶다는 생각이 들었어.","mis":"K6-2-u5-X15"},{"t":"영상이 너무 길고 지루해서 보는 내내 별로였다고 느꼈어.","mis":"K6-2-u5-X15"}],"explanation":["인상 깊은 부분을 「언어의 표현을 바탕으로」 설명해야 해요.","어떤 표현이 쓰였고 무엇을 도왔는지 말해요.","좋았다, 별로였다에서 멈추면 표현 효과를 알 수 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L05_basic#9','kor',6,2,'u5','L05','tb_g6_2_kor_u5_L05_basic','lesson_basic','K6-2-u5-C12',2,'ox','auto','「수월봉 화산 쇄설층」에서 인상 깊었던 부분은 친구마다 다를 수 있어요.',ARRAY['K6-2-u5-X16']::text[],false,'{"seq":9,"concept":"K6-2-u5-C12","difficulty":2,"kind":"ox","stem":"「수월봉 화산 쇄설층」에서 인상 깊었던 부분은 친구마다 다를 수 있어요.","answer":"O","reason_options":[{"t":"느낌은 경험에 따라 다를 수 있으니, 어떤 언어 표현 때문인지 까닭을 함께 말하면 되기 때문에","correct":true},{"t":"인상 깊은 부분은 정답이 하나뿐이어서 나와 다르면 잘못 본 것이기 때문에","mis":"K6-2-u5-X16"}],"mis":"K6-2-u5-X16","explanation":["언어의 표현 효과는 경험에 따라 다르게 느낄 수 있어요.","친구의 생각도 들어 보아요.","무엇이 쓰였는지는 영상에서 함께 확인할 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L05_basic#10','kor',6,2,'u5','L05','tb_g6_2_kor_u5_L05_basic','lesson_basic','K6-2-u5-C11',3,'mc','auto','『국어』 231쪽 장면 5에서 해설자의 음성 설명 없이 대상의 이름과 설명을 자막으로만 보여 준 효과를 가장 알맞게 말한 것은 무엇인가요?',ARRAY['K6-2-u5-X11','K6-2-u5-X12','K6-2-u5-X14']::text[],false,'{"seq":10,"concept":"K6-2-u5-C11","difficulty":3,"kind":"mc","stem":"『국어』 231쪽 장면 5에서 해설자의 음성 설명 없이 대상의 이름과 설명을 자막으로만 보여 준 효과를 가장 알맞게 말한 것은 무엇인가요?","options":[{"t":"음성 언어 없이 문자 언어로 자막을 보여 주어 집중하며 읽을 수 있다","correct":true},{"t":"소리가 없어서 아무 내용도 전해지지 않는다","mis":"K6-2-u5-X11"},{"t":"자막이 있으니 음악과 장면은 없어도 된다","mis":"K6-2-u5-X12"},{"t":"해설자가 실수로 말을 빠뜨린 것이다","mis":"K6-2-u5-X14"}],"explanation":["장면 5는 일부러 음성 설명을 빼고 자막을 보여 줘요.","그래서 화면의 글자에 집중하게 돼요.","장면마다 방법을 고른 까닭이 있어요."],"asset":{"type":"passage","lines":["장면 1 잔잔한 파도 소리와 음악이 들리며 제목이 나타난다.","장면 2 해안 절벽을 다양한 각도로 보여 주고, 해설자의 말을 화면에 문자로 다시 보여 준다.","장면 3 새로운 탄생과 발견을 강조하려고 긴장감이 느껴지는 음악을 사용한다.","장면 4 분화구 추정 위치와 주변 지역을 글과 그림으로 표현한다.","장면 5 대상의 이름과 설명을 해설자의 음성 설명 없이 자막으로 보여 준다."],"numbered":false,"title":"「수월봉 화산 쇄설층」(『국어』 231쪽 장면 설명)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L05_challenge#1','kor',6,2,'u5','L05','tb_g6_2_kor_u5_L05_challenge','lesson_challenge','K6-2-u5-C30',2,'sa','auto','『국어』 232쪽 (2)의 예시 답안이에요. 「(    )이 일정한 각도인 것을 보고 추측했습니다.」 빈칸에 알맞은 세 글자 낱말을 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K6-2-u5-C30","difficulty":2,"kind":"sa","stem":"『국어』 232쪽 (2)의 예시 답안이에요. 「(    )이 일정한 각도인 것을 보고 추측했습니다.」 빈칸에 알맞은 세 글자 낱말을 쓰세요.","answer":["화산탄"],"explanation":["화산 분화구의 중심을 추측한 실마리를 묻는 문제예요.","화산탄이 일정한 각도였어요.","그래서 분화구의 중심을 바다 한가운데라고 추측했어요."],"mis":"K6-2-u5-X41"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L05_challenge#2','kor',6,2,'u5','L05','tb_g6_2_kor_u5_L05_challenge','lesson_challenge','K6-2-u5-C12',2,'mc','auto','『국어』 235쪽 점검하기 (2)의 물음으로 알맞은 것은 무엇인가요?',ARRAY['K6-2-u5-X13','K6-2-u5-X15','K6-2-u5-X05']::text[],false,'{"seq":2,"concept":"K6-2-u5-C12","difficulty":2,"kind":"mc","stem":"『국어』 235쪽 점검하기 (2)의 물음으로 알맞은 것은 무엇인가요?","options":[{"t":"동영상, 문자, 소리, 음악과 같이 여러 가지 표현 방법이 어떻게 어울리는지 생각하며 시청했나요?","correct":true},{"t":"영상에 나온 자막과 장면이 모두 몇 개인지 하나하나 세며 시청했나요?","mis":"K6-2-u5-X13"},{"t":"영상이 재미있었는지, 지루했는지만 생각하며 끝까지 시청했나요?","mis":"K6-2-u5-X15"},{"t":"영상을 올린 사람의 이름과 올린 날짜를 기억하며 시청했나요?","mis":"K6-2-u5-X05"}],"explanation":["점검하기는 매체 시청 과정을 스스로 확인하는 활동이에요.","내용 확인, 두 언어의 특성, 표현 방법의 어울림을 물어요.","개수나 재미, 올린 사람은 점검할 점이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L05_challenge#3','kor',6,2,'u5','L05','tb_g6_2_kor_u5_L05_challenge','lesson_challenge','K6-2-u5-C11',3,'mc','auto','『국어』 233쪽 (1)에서 장면 3을 보고 「긴장감이 느껴지는 음악과 함께 내용을 전달하고 있어.」라고 했어요. 이 장면에서 그런 음악을 쓴 까닭으로 가장 알맞은 것은 무엇인가요?',ARRAY['K6-2-u5-X14','K6-2-u5-X12','K6-2-u5-X13']::text[],false,'{"seq":3,"concept":"K6-2-u5-C11","difficulty":3,"kind":"mc","stem":"『국어』 233쪽 (1)에서 장면 3을 보고 「긴장감이 느껴지는 음악과 함께 내용을 전달하고 있어.」라고 했어요. 이 장면에서 그런 음악을 쓴 까닭으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"새로운 탄생과 발견을 강조하려고","correct":true},{"t":"장면이 지루해서 아무 음악이나 넣으려고","mis":"K6-2-u5-X14"},{"t":"해설자의 말을 대신해 내용을 모두 설명하려고","mis":"K6-2-u5-X12"},{"t":"음악은 클수록 좋아서","mis":"K6-2-u5-X13"}],"explanation":["장면 3은 새로운 탄생과 발견을 다뤄요.","긴장감 있는 음악이 그 순간을 강조해요.","음악도 장면에서 해야 할 일에 맞추어 골라요."],"asset":{"type":"passage","lines":["장면 1 잔잔한 파도 소리와 음악이 들리며 제목이 나타난다.","장면 2 해안 절벽을 다양한 각도로 보여 주고, 해설자의 말을 화면에 문자로 다시 보여 준다.","장면 3 새로운 탄생과 발견을 강조하려고 긴장감이 느껴지는 음악을 사용한다.","장면 4 분화구 추정 위치와 주변 지역을 글과 그림으로 표현한다.","장면 5 대상의 이름과 설명을 해설자의 음성 설명 없이 자막으로 보여 준다."],"numbered":false,"title":"「수월봉 화산 쇄설층」(『국어』 231쪽 장면 설명)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L05_challenge#4','kor',6,2,'u5','L05','tb_g6_2_kor_u5_L05_challenge','lesson_challenge','K6-2-u5-C30',3,'error','auto','「수월봉 화산 쇄설층」을 보고 친구들이 내용을 정리했어요. 영상 내용과 다르게 말한 친구는 누구인가요?',ARRAY['K6-2-u5-X41']::text[],false,'{"seq":4,"concept":"K6-2-u5-C30","difficulty":3,"kind":"error","stem":"「수월봉 화산 쇄설층」을 보고 친구들이 내용을 정리했어요. 영상 내용과 다르게 말한 친구는 누구인가요?","options":[{"t":"친구 3 — 「화산 쇄설층은 용암이 천천히 흘러서 그대로 굳은 것이래.」","correct":true,"mis_target":"K6-2-u5-X41"},{"t":"친구 1 — 「마그마가 지표의 물과 만나 폭발한 뒤 화산재와 화산 쇄설물이 쌓였대.」","mis":"K6-2-u5-X41"},{"t":"친구 2 — 「화산탄이 일정한 각도라서 분화구 중심을 바다 한가운데라고 추측했대.」","mis":"K6-2-u5-X41"}],"explanation":["화산 쇄설층은 폭발 뒤 화산재와 화산 쇄설물이 쌓여 만들어졌어요.","용암이 흘러 굳었다는 말은 영상 내용과 달라요.","분화구 중심은 화산탄의 각도로 추측했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L05_challenge#5','kor',6,2,'u5','L05','tb_g6_2_kor_u5_L05_challenge','lesson_challenge','K6-2-u5-C30',3,'ox','auto','「수월봉 화산 쇄설층」에서는 화산탄의 휜 모습으로 방향성을 찾을 수 있다고 해요.',ARRAY['K6-2-u5-X41']::text[],false,'{"seq":5,"concept":"K6-2-u5-C30","difficulty":3,"kind":"ox","stem":"「수월봉 화산 쇄설층」에서는 화산탄의 휜 모습으로 방향성을 찾을 수 있다고 해요.","answer":"O","reason_options":[{"t":"화산탄이 일정한 각도로 휘어 있는 것을 보고 분화구가 있던 쪽을 추측하기 때문에","correct":true},{"t":"화산탄은 아무렇게나 흩어져 있어 아무것도 알 수 없기 때문에","mis":"K6-2-u5-X41"}],"mis":"K6-2-u5-X41","explanation":["『국어』 232쪽 (2)와 이어지는 내용이에요.","화산탄의 휜 모습이 방향을 알려 줘요.","그래서 분화구의 중심을 추측할 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L05_challenge#6','kor',6,2,'u5','L05','tb_g6_2_kor_u5_L05_challenge','lesson_challenge','K6-2-u5-C31',3,'mc','auto','『국어』 232쪽 낱말 알기의 낱말과 뜻을 바르게 짝 지은 것은 무엇인가요?',ARRAY['K6-2-u5-X42']::text[],false,'{"seq":6,"concept":"K6-2-u5-C31","difficulty":3,"kind":"mc","stem":"『국어』 232쪽 낱말 알기의 낱말과 뜻을 바르게 짝 지은 것은 무엇인가요?","options":[{"t":"분화구 — 화산 꼭대기에 생긴 용암과 화산 가스 따위의 분출구","correct":true},{"t":"지층 — 지구의 표면","mis":"K6-2-u5-X42"},{"t":"화산재 — 위아래의 퇴적암과 구분되는 퇴적암체","mis":"K6-2-u5-X42"},{"t":"지표 — 용암의 부스러기 가운데 크기가 작은 알갱이","mis":"K6-2-u5-X42"}],"explanation":["지표는 지구의 표면이에요.","지층은 위아래의 퇴적암과 구분되는 퇴적암체예요.","화산재는 용암의 부스러기 가운데 크기가 작은 알갱이예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L05_challenge#7','kor',6,2,'u5','L05','tb_g6_2_kor_u5_L05_challenge','lesson_challenge','K6-2-u5-C12',3,'match','auto','『국어』 234쪽 다른 글과 연결하기의 예시 답안이에요. 영상 내용과 언어의 표현 효과를 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K6-2-u5-C12","difficulty":3,"kind":"match","stem":"『국어』 234쪽 다른 글과 연결하기의 예시 답안이에요. 영상 내용과 언어의 표현 효과를 알맞게 이으세요.","pairs":[{"l":"인구 변화를 알려 주는 내용","r":"설명하는 음성 언어와 함께 문자로 연도를 알려 주어서 이해하기 쉽다"},{"l":"산성 용액과 염기성 용액의 성질을 과학 실험으로 확인하는 내용","r":"실험의 순서와 용액의 이름을 문자 언어로 알려 주어서 이해하기 쉽다"}],"mis":"K6-2-u5-X12","explanation":["다른 교과 시간에 본 영상에도 언어의 표현 효과가 있어요.","연도나 용액 이름처럼 놓치기 쉬운 것을 문자로 보여 줘요.","그래서 내용을 이해하기 쉬워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L05_challenge#8','kor',6,2,'u5','L05','tb_g6_2_kor_u5_L05_challenge','lesson_challenge','K6-2-u5-C11',4,'essay','teacher','「수월봉 화산 쇄설층」의 장면 1~5 가운데 두 장면을 골라, 장면마다 표현 방법이 다른 까닭을 그 장면에서 전하려는 내용과 이어 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K6-2-u5-C11","difficulty":4,"kind":"essay","stem":"「수월봉 화산 쇄설층」의 장면 1~5 가운데 두 장면을 골라, 장면마다 표현 방법이 다른 까닭을 그 장면에서 전하려는 내용과 이어 쓰세요.","answer_guide":{"answer":"예: 장면 3에서는 새로운 탄생과 발견을 강조하려고 긴장감이 느껴지는 음악을 썼다. 장면 4에서는 분화구가 있었을 것으로 추정되는 위치를 말로만 들으면 알기 어려워 글과 그림으로 나타냈다. 장면마다 전하려는 내용이 달라서 알맞은 표현 방법도 다르다.","scoring_points":["두 장면의 표현 방법을 바르게 썼는가","그 장면에서 전하려는 내용과 표현 방법을 이었는가","장면마다 방법이 다른 까닭을 정리했는가"]},"explanation":["장면마다 해야 할 일이 달라요.","그 일에 맞는 표현 방법을 골라요.","그래서 같은 영상 안에서도 방법이 달라요."],"asset":{"type":"passage","lines":["장면 1 잔잔한 파도 소리와 음악이 들리며 제목이 나타난다.","장면 2 해안 절벽을 다양한 각도로 보여 주고, 해설자의 말을 화면에 문자로 다시 보여 준다.","장면 3 새로운 탄생과 발견을 강조하려고 긴장감이 느껴지는 음악을 사용한다.","장면 4 분화구 추정 위치와 주변 지역을 글과 그림으로 표현한다.","장면 5 대상의 이름과 설명을 해설자의 음성 설명 없이 자막으로 보여 준다."],"numbered":false,"title":"「수월봉 화산 쇄설층」(『국어』 231쪽 장면 설명)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L05_challenge#9','kor',6,2,'u5','L05','tb_g6_2_kor_u5_L05_challenge','lesson_challenge','K6-2-u5-C12',4,'essay','teacher','『국어』 234쪽처럼 다른 교과 시간에 본 영상 하나를 떠올려, 영상 내용과 그 영상에 쓰인 언어의 표현 효과를 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-2-u5-C12","difficulty":4,"kind":"essay","stem":"『국어』 234쪽처럼 다른 교과 시간에 본 영상 하나를 떠올려, 영상 내용과 그 영상에 쓰인 언어의 표현 효과를 쓰세요.","answer_guide":{"answer":"예: 사회 시간에 인구 변화를 알려 주는 영상을 보았다. 설명하는 음성 언어와 함께 연도를 문자로 알려 주어서 언제 어떻게 바뀌었는지 이해하기 쉬웠다.","scoring_points":["영상 내용을 썼는가","그 영상에 쓰인 언어 표현을 찾았는가","그 표현이 이해를 어떻게 도왔는지 썼는가"]},"explanation":["사회나 과학 시간의 영상을 떠올려요.","말과 함께 글자로 보여 준 것을 찾아요.","그 덕분에 무엇이 쉬워졌는지 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L05_challenge#10','kor',6,2,'u5','L05','tb_g6_2_kor_u5_L05_challenge','lesson_challenge','K6-2-u5-C12',4,'essay','teacher','『국어』 235쪽 (1)의 친구들처럼 영상에서 사용하는 언어의 표현 효과를 하나 말하고, 점검하기 (2)의 세 물음 가운데 내가 더 노력할 점 하나를 골라 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-2-u5-C12","difficulty":4,"kind":"essay","stem":"『국어』 235쪽 (1)의 친구들처럼 영상에서 사용하는 언어의 표현 효과를 하나 말하고, 점검하기 (2)의 세 물음 가운데 내가 더 노력할 점 하나를 골라 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 자막이 있어서 음성 언어의 정보를 쉽게 이해할 수 있었다. 나는 「여러 가지 표현 방법이 어떻게 어울리는지 생각하며 시청했나요?」를 더 노력하고 싶다. 지금까지는 내용만 보고 음악이나 소리가 어떤 효과를 내는지는 잘 생각하지 않았기 때문이다.","scoring_points":["영상의 언어 표현 효과를 하나 썼는가","점검하기 물음 가운데 하나를 골랐는가","노력할 까닭을 자신의 시청 경험과 이어 썼는가"]},"explanation":["먼저 표현 효과를 하나 말해요.","점검하기 세 물음으로 내 시청 과정을 돌아봐요.","더 노력할 점과 까닭을 써요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"자막이 있어서 음성 언어의 정보를 쉽게 이해할 수 있었어."},{"who":"친구 2","text":"음성 언어의 설명에서 빠진 부분을 문자 언어로 표시해 주어서 정확하게 알 수 있었어."},{"who":"친구 3","text":"그림과 문자 언어를 사용하여 설명해 주어서 내용을 한눈에 이해하기 쉬웠어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L07_basic#1','kor',6,2,'u5','L07','tb_g6_2_kor_u5_L07_basic','lesson_basic','K6-2-u5-C32',1,'mc','auto','『국어』 236쪽에서 독자가 「운동장 놀이의 좋은 점」을 읽고 어려워하는 까닭으로 알맞은 것은 무엇인가요?',ARRAY['K6-2-u5-X22','K6-2-u5-X23','K6-2-u5-X19']::text[],false,'{"seq":1,"concept":"K6-2-u5-C32","difficulty":1,"kind":"mc","stem":"『국어』 236쪽에서 독자가 「운동장 놀이의 좋은 점」을 읽고 어려워하는 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"이해하기 어려운 낱말이 있고, 독자가 관심 있는 내용이 아니어서","correct":true},{"t":"글씨가 작고 줄 간격이 좁아서 읽기 불편해서","mis":"K6-2-u5-X22"},{"t":"글에 그림이나 사진이 하나도 들어 있지 않아서","mis":"K6-2-u5-X23"},{"t":"운동장 놀이라는 소재가 학생들과 관계없어서","mis":"K6-2-u5-X19"}],"explanation":["독자 2는 「심폐 지구력은 무슨 뜻일까?」 하고 물었어요.","독자 1은 놀이 방법에 관심이 있는데 글이 관련이 없다고 했어요.","어려운 낱말과 관심 없는 내용 때문에 어려워해요."],"asset":{"type":"speech","turns":[{"who":"글쓴이","text":"운동장 놀이를 조사해서 써 봐야지."},{"who":"[글] 「운동장 놀이의 좋은 점」","text":"운동장 놀이는 학생들의 신체 발달과 정서 함양에 긍정적인 영향을 미친다. 어린이들은 신체 활동에 참여하면서 심폐 지구력을 향상할 수 있다."},{"who":"독자 1","text":"나는 운동장에서 할 수 있는 놀이 방법에 관심이 있는데 이 글은 관련이 없는 것 같아."},{"who":"독자 2","text":"심폐 지구력은 무슨 뜻일까?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L07_basic#2','kor',6,2,'u5','L07','tb_g6_2_kor_u5_L07_basic','lesson_basic','K6-2-u5-C14',1,'sa','auto','『국어』 241쪽 7번 정리예요. 「글을 쓰기 전에 독자의 (    )나 관심사, 겪고 있는 문제 같은 것을 조사한다.」 빈칸에 알맞은 낱말을 보기(주제, 흥미, 이해)에서 골라 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"K6-2-u5-C14","difficulty":1,"kind":"sa","stem":"『국어』 241쪽 7번 정리예요. 「글을 쓰기 전에 독자의 (    )나 관심사, 겪고 있는 문제 같은 것을 조사한다.」 빈칸에 알맞은 낱말을 보기(주제, 흥미, 이해)에서 골라 쓰세요.","answer":["흥미"],"explanation":["글을 쓰기 전에 독자를 먼저 알아봐요.","독자의 흥미나 관심사, 겪고 있는 문제를 조사해요.","그래야 독자에게 맞는 글을 쓸 수 있어요."],"mis":"K6-2-u5-X19"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L07_basic#3','kor',6,2,'u5','L07','tb_g6_2_kor_u5_L07_basic','lesson_basic','K6-2-u5-C33',1,'ox','auto','「계단을 안전하게 이용합시다」에서 글쓴이는 학생들에게 실제로 계단에서 위험했던 적이 있는지 조사했어요.',ARRAY['K6-2-u5-X27']::text[],false,'{"seq":3,"concept":"K6-2-u5-C33","difficulty":1,"kind":"ox","stem":"「계단을 안전하게 이용합시다」에서 글쓴이는 학생들에게 실제로 계단에서 위험했던 적이 있는지 조사했어요.","answer":"O","reason_options":[{"t":"학교 정문에서 등교하는 학생 50명에게 계단에서 위험한 상황을 겪은 적이 있는지 물었기 때문에","correct":true},{"t":"글쓴이는 아무것도 조사하지 않고 생각만 썼기 때문에","mis":"K6-2-u5-X27"}],"mis":"K6-2-u5-X27","explanation":["글쓴이는 등교하는 학생 50명을 대상으로 조사했어요.","실제로 계단에서 위험했던 적이 있는지 물었어요.","그 결과를 그래프로 보여 주었어요."],"asset":{"type":"passage","lines":["[그래프] 계단에서 위험한 상황을 겪은 적이 있습니까?","[그래프] 있다 40명 · 거의 없다 6명 · 없다 4명","(간추림) 학교 정문에서 등교하는 학생 50명에게 물었더니 40명이 위험한 상황을 겪었다.","[별표 기호] 뛰지 말고 천천히 걸어요!","[별표 기호] 필요할 때에는 계단 난간을 잡아요!","[별표 기호] 앞을 잘 보고 걸어요!","[쓴 사람] ○○초등학교 전교 어린이회"],"numbered":false,"title":"「계단을 안전하게 이용합시다」(『국어』 240쪽, 간추림)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L07_basic#4','kor',6,2,'u5','L07','tb_g6_2_kor_u5_L07_basic','lesson_basic','K6-2-u5-C16',1,'mc','auto','『국어』 238~239쪽 4번에서 독자를 고려하며 글을 쓰는 과정의 차례로 알맞은 것은 무엇인가요?',ARRAY['K6-2-u5-X21']::text[],false,'{"seq":4,"concept":"K6-2-u5-C16","difficulty":1,"kind":"mc","stem":"『국어』 238~239쪽 4번에서 독자를 고려하며 글을 쓰는 과정의 차례로 알맞은 것은 무엇인가요?","options":[{"t":"글을 쓸 계획 세우기 → 내용 생성 및 조직 하기 → 글을 쓰고 고쳐 쓰기","correct":true},{"t":"글을 쓰고 고쳐 쓰기 → 글을 쓸 계획 세우기 → 내용 생성 및 조직 하기","mis":"K6-2-u5-X21"},{"t":"내용 생성 및 조직 하기 → 글을 쓰고 고쳐 쓰기 → 글을 쓸 계획 세우기","mis":"K6-2-u5-X21"}],"explanation":["먼저 독자를 조사하고 계획을 세워요.","다음에 내용을 정하고 조직해요.","마지막으로 글을 쓰고 고쳐 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L07_basic#5','kor',6,2,'u5','L07','tb_g6_2_kor_u5_L07_basic','lesson_basic','K6-2-u5-C32',2,'mc','auto','『국어』 237쪽에서 새로 쓴 「그림자 술래잡기」는 236쪽의 글과 어떤 점이 달라졌나요?',ARRAY['K6-2-u5-X24','K6-2-u5-X43','K6-2-u5-X20']::text[],false,'{"seq":5,"concept":"K6-2-u5-C32","difficulty":2,"kind":"mc","stem":"『국어』 237쪽에서 새로 쓴 「그림자 술래잡기」는 236쪽의 글과 어떤 점이 달라졌나요?","options":[{"t":"독자가 이해하기 쉬운 표현을 쓰고, 독자가 관심 있는 것에 대해 썼다","correct":true},{"t":"심폐 지구력처럼 어려운 낱말을 더 많이 넣었다","mis":"K6-2-u5-X24"},{"t":"글쓴이가 조사한 운동장 놀이의 좋은 점만 더 길게 썼다","mis":"K6-2-u5-X43"},{"t":"독자가 좋아할 말만 골라 알릴 내용을 모두 뺐다","mis":"K6-2-u5-X20"}],"explanation":["독자 1은 「낱말이 쉬워서 글 내용을 이해하기 쉬워.」라고 했어요.","독자 2는 찾던 놀이라서 해 보면 재미있겠다고 했어요.","쓰는 사람이 독자를 고려해 다시 썼어요."],"asset":{"type":"passage","lines":["(간추림) 그림자를 밟아 잡는 놀이이다. 먼저 술래를 한 명 정한다.","(간추림) 술래는 친구들의 그림자를 밟으려고 따라다니고, 친구들은 도망 다닌다.","(간추림) 술래가 친구의 그림자를 밟으면 그 친구가 다음 술래가 된다.","(간추림) 햇빛이 있는 장소에서 하면 더욱 재미있다.","[독자 1] 낱말이 쉬워서 글 내용을 이해하기 쉬워.","[독자 2] 운동장이나 놀이터에서 할 놀이를 찾고 있었는데 해 보면 재미있을 것 같아."],"numbered":false,"title":"「그림자 술래잡기」(『국어』 237쪽, 간추림)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L07_basic#6','kor',6,2,'u5','L07','tb_g6_2_kor_u5_L07_basic','lesson_basic','K6-2-u5-C14',2,'blank','auto','『국어』 238쪽 「글을 쓸 계획 세우기」에서 정리한 메모예요. 「특성: 우리 학교 학생들은 (    )(이)나 그래프가 있을 때 내용을 더 쉽게 이해함.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['K6-2-u5-X24','K6-2-u5-X22']::text[],false,'{"seq":6,"concept":"K6-2-u5-C14","difficulty":2,"kind":"blank","stem":"『국어』 238쪽 「글을 쓸 계획 세우기」에서 정리한 메모예요. 「특성: 우리 학교 학생들은 (    )(이)나 그래프가 있을 때 내용을 더 쉽게 이해함.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"그림","correct":true},{"t":"어려운 낱말","mis":"K6-2-u5-X24"},{"t":"긴 문장","mis":"K6-2-u5-X22"},{"t":"작은 글씨","mis":"K6-2-u5-X22"}],"explanation":["계획 단계에서 독자의 특성을 조사했어요.","우리 학교 학생들은 그림이나 그래프가 있을 때 더 쉽게 이해해요.","그래서 글에 그래프를 넣었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L07_basic#7','kor',6,2,'u5','L07','tb_g6_2_kor_u5_L07_basic','lesson_basic','K6-2-u5-C16',2,'match','auto','『국어』 238~239쪽 글쓰기 과정과 그 단계에서 하는 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K6-2-u5-C16","difficulty":2,"kind":"match","stem":"『국어』 238~239쪽 글쓰기 과정과 그 단계에서 하는 일을 알맞게 이으세요.","pairs":[{"l":"글을 쓸 계획 세우기","r":"독자가 누구인지, 관심과 어려움을 조사하고 주제를 정한다"},{"l":"내용 생성 및 조직 하기","r":"독자의 관심과 흥미를 고려해 내용을 정하고 자료를 배치한다"},{"l":"글을 쓰고 고쳐 쓰기","r":"이해하기 쉬운 표현으로 쓰고 오해할 만한 부분을 고친다"}],"mis":"K6-2-u5-X21","explanation":["계획하기에서는 독자를 조사해요.","내용 생성 및 조직 하기에서는 내용과 자료를 정해요.","쓰고 고쳐 쓰기에서는 표현을 다듬어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L07_basic#8','kor',6,2,'u5','L07','tb_g6_2_kor_u5_L07_basic','lesson_basic','K6-2-u5-C17',2,'mc','auto','『국어』 241쪽 6번에서 「계단을 안전하게 이용합시다」가 조사 결과를 그래프로 보여 주어 좋은 점으로 말한 것은 무엇인가요?',ARRAY['K6-2-u5-X23','K6-2-u5-X13','K6-2-u5-X24']::text[],false,'{"seq":8,"concept":"K6-2-u5-C17","difficulty":2,"kind":"mc","stem":"『국어』 241쪽 6번에서 「계단을 안전하게 이용합시다」가 조사 결과를 그래프로 보여 주어 좋은 점으로 말한 것은 무엇인가요?","options":[{"t":"한눈에 보기 좋아 학생들이 내용을 쉽게 이해할 수 있다","correct":true},{"t":"그래프가 있으면 글을 덜 써도 된다","mis":"K6-2-u5-X23"},{"t":"자료는 많이 넣을수록 좋은 글이 된다","mis":"K6-2-u5-X13"},{"t":"그래프를 넣으면 글이 어려워 보여 훌륭해 보인다","mis":"K6-2-u5-X24"}],"explanation":["친구는 「조사 결과를 그래프로 보여 주어서 한눈에 보기 좋아.」라고 했어요.","학생들이 그래프를 보며 내용을 쉽게 이해할 수 있어요.","자료는 독자의 이해를 도우려고 넣어요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"조사 결과를 그래프로 보여 주어서 한눈에 보기 좋아. ○○초등학교 학생들이 그래프를 보며 내용을 쉽게 이해할 수 있었을 거야."},{"who":"친구 2","text":"별표 기호를 활용해서 안전 수칙을 나누어 보여 주니까 기억하기도 쉬워. 어린 동생들도 읽고 오래 기억할 수 있을 거야."},{"who":"친구 3","text":"학생들은 학교에서 안전하게 다니는 것에 관심이 많기 때문에 주의 깊게 이 글을 읽을 거야."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L07_basic#9','kor',6,2,'u5','L07','tb_g6_2_kor_u5_L07_basic','lesson_basic','K6-2-u5-C15',2,'ox','auto','독자를 고려해 글을 쓴다는 것은 독자가 읽고 싶어 하는 내용만 다루어야 한다는 뜻이에요.',ARRAY['K6-2-u5-X20']::text[],false,'{"seq":9,"concept":"K6-2-u5-C15","difficulty":2,"kind":"ox","stem":"독자를 고려해 글을 쓴다는 것은 독자가 읽고 싶어 하는 내용만 다루어야 한다는 뜻이에요.","answer":"X","reason_options":[{"t":"독자의 관점에서 정보를 효과적으로 전달하고 있는지에 초점을 두어야 하기 때문에","correct":true},{"t":"독자가 좋아하지 않는 내용은 모두 빼야 독자를 고려한 것이기 때문에","mis":"K6-2-u5-X20"}],"mis":"K6-2-u5-X20","explanation":["독자를 고려한다고 좋아하는 내용만 쓰는 것은 아니에요.","전하려는 내용을 독자가 잘 받아들이게 전하는 것이 중요해요.","독자의 관점에서 효과적으로 전달되는지 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L07_basic#10','kor',6,2,'u5','L07','tb_g6_2_kor_u5_L07_basic','lesson_basic','K6-2-u5-C14',3,'mc','auto','『국어』 236쪽에서 글쓴이가 「운동장 놀이를 조사해서 써 봐야지.」라고 한 뒤 쓴 글에서, 독자를 고려하지 않은 점을 가장 알맞게 말한 것은 무엇인가요?',ARRAY['K6-2-u5-X19','K6-2-u5-X22','K6-2-u5-X20']::text[],false,'{"seq":10,"concept":"K6-2-u5-C14","difficulty":3,"kind":"mc","stem":"『국어』 236쪽에서 글쓴이가 「운동장 놀이를 조사해서 써 봐야지.」라고 한 뒤 쓴 글에서, 독자를 고려하지 않은 점을 가장 알맞게 말한 것은 무엇인가요?","options":[{"t":"자신이 조사한 내용을 쓰는 데에만 집중해, 독자의 관심사와 낱말 수준을 생각하지 않았다","correct":true},{"t":"운동장 놀이라는 소재 자체가 학생들에게 알맞지 않은 것을 골랐다","mis":"K6-2-u5-X19"},{"t":"글이 두 문장뿐이라 길이가 너무 짧고 글씨도 작게 썼다","mis":"K6-2-u5-X22"},{"t":"독자가 좋아하는 놀이 이야기만 골라 써서 전할 내용이 빠졌다","mis":"K6-2-u5-X20"}],"explanation":["글쓴이는 자신이 조사한 내용만 썼어요.","독자는 놀이 방법에 관심이 있었고 어려운 낱말도 몰랐어요.","237쪽 글은 같은 운동장 놀이를 다루어도 독자를 고려했어요."],"asset":{"type":"speech","turns":[{"who":"글쓴이","text":"운동장 놀이를 조사해서 써 봐야지."},{"who":"[글] 「운동장 놀이의 좋은 점」","text":"운동장 놀이는 학생들의 신체 발달과 정서 함양에 긍정적인 영향을 미친다. 어린이들은 신체 활동에 참여하면서 심폐 지구력을 향상할 수 있다."},{"who":"독자 1","text":"나는 운동장에서 할 수 있는 놀이 방법에 관심이 있는데 이 글은 관련이 없는 것 같아."},{"who":"독자 2","text":"심폐 지구력은 무슨 뜻일까?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L07_challenge#1','kor',6,2,'u5','L07','tb_g6_2_kor_u5_L07_challenge','lesson_challenge','K6-2-u5-C33',2,'sa','auto','「계단을 안전하게 이용합시다」의 그래프에서 학생 50명 가운데 계단에서 위험한 상황을 겪은 적이 있다고 답한 학생은 몇 명인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K6-2-u5-C33","difficulty":2,"kind":"sa","stem":"「계단을 안전하게 이용합시다」의 그래프에서 학생 50명 가운데 계단에서 위험한 상황을 겪은 적이 있다고 답한 학생은 몇 명인가요? 숫자로 쓰세요.","answer":["40","40명"],"explanation":["그래프는 있다, 거의 없다, 없다로 나뉘어요.","있다고 답한 학생은 40명이에요.","그래프로 보여 주니 한눈에 알 수 있어요."],"asset":{"type":"passage","lines":["[그래프] 계단에서 위험한 상황을 겪은 적이 있습니까?","[그래프] 있다 40명 · 거의 없다 6명 · 없다 4명","(간추림) 학교 정문에서 등교하는 학생 50명에게 물었더니 40명이 위험한 상황을 겪었다.","[별표 기호] 뛰지 말고 천천히 걸어요!","[별표 기호] 필요할 때에는 계단 난간을 잡아요!","[별표 기호] 앞을 잘 보고 걸어요!","[쓴 사람] ○○초등학교 전교 어린이회"],"numbered":false,"title":"「계단을 안전하게 이용합시다」(『국어』 240쪽, 간추림)"},"mis":"K6-2-u5-X27"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L07_challenge#2','kor',6,2,'u5','L07','tb_g6_2_kor_u5_L07_challenge','lesson_challenge','K6-2-u5-C14',2,'mc','auto','『국어』 237쪽 3번에서 「독자가 무엇을 알고 있는지 생각하면 독자가 이해하기 쉬운 글을 쓸 수 있어.」라고 했어요. 이 말에서 고려한 독자의 특성은 무엇인가요?',ARRAY['K6-2-u5-X19','K6-2-u5-X43']::text[],false,'{"seq":2,"concept":"K6-2-u5-C14","difficulty":2,"kind":"mc","stem":"『국어』 237쪽 3번에서 「독자가 무엇을 알고 있는지 생각하면 독자가 이해하기 쉬운 글을 쓸 수 있어.」라고 했어요. 이 말에서 고려한 독자의 특성은 무엇인가요?","options":[{"t":"독자의 배경지식","correct":true},{"t":"독자의 관심사","mis":"K6-2-u5-X19"},{"t":"독자가 선호하는 보조 자료","mis":"K6-2-u5-X19"},{"t":"글쓴이가 조사한 내용","mis":"K6-2-u5-X43"}],"explanation":["독자가 무엇을 알고 있는지는 배경지식이에요.","관심사, 선호하는 자료도 고려할 점이지만 이 말과는 달라요.","독자의 흥미, 배경지식, 수준을 두루 고려해요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"글을 쓸 때 독자의 관심사를 고려해서 쓰면 독자가 더 흥미롭게 읽을 수 있어."},{"who":"친구 2","text":"독자가 무엇을 알고 있는지 생각하면 독자가 이해하기 쉬운 글을 쓸 수 있어."},{"who":"친구 3","text":"그림이나 사진, 그래프처럼 독자가 선호하는 보조 자료를 넣으면 이해를 도울 수 있어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L07_challenge#3','kor',6,2,'u5','L07','tb_g6_2_kor_u5_L07_challenge','lesson_challenge','K6-2-u5-C16',3,'mc','auto','『국어』 239쪽 「글을 쓰고 고쳐 쓰기」에서 고쳐 쓸 때 확인할 점으로 가장 알맞은 것은 무엇인가요?',ARRAY['K6-2-u5-X22','K6-2-u5-X21']::text[],false,'{"seq":3,"concept":"K6-2-u5-C16","difficulty":3,"kind":"mc","stem":"『국어』 239쪽 「글을 쓰고 고쳐 쓰기」에서 고쳐 쓸 때 확인할 점으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"독자가 오해할 만한 부분은 없는지, 독자 수준에 맞는지 확인한다","correct":true},{"t":"글씨가 예쁜지만 확인한다","mis":"K6-2-u5-X22"},{"t":"독자는 계획할 때 이미 생각했으니 다시 떠올리지 않는다","mis":"K6-2-u5-X21"},{"t":"글의 길이가 길어졌는지 확인한다","mis":"K6-2-u5-X22"}],"explanation":["고쳐 쓸 때에도 독자를 다시 떠올려요.","독자 수준, 주제, 잘못된 낱말이나 문장, 오해할 표현을 확인해요.","친구와 글을 바꾸어 읽어 보고 고칠 수도 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L07_challenge#4','kor',6,2,'u5','L07','tb_g6_2_kor_u5_L07_challenge','lesson_challenge','K6-2-u5-C15',3,'error','auto','독자를 고려한 글쓰기에 대해 친구들이 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-2-u5-X20','K6-2-u5-X19','K6-2-u5-X23']::text[],false,'{"seq":4,"concept":"K6-2-u5-C15","difficulty":3,"kind":"error","stem":"독자를 고려한 글쓰기에 대해 친구들이 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"친구 2 — 「독자를 고려하려면 어려운 내용은 다 빼고 재미있는 이야기만 써야 해.」","correct":true,"mis_target":"K6-2-u5-X20"},{"t":"친구 1 — 「독자의 관심사를 고려해서 쓰면 독자가 더 흥미롭게 읽을 수 있어.」","mis":"K6-2-u5-X19"},{"t":"친구 3 — 「독자가 선호하는 그래프 같은 보조 자료를 넣으면 이해를 도울 수 있어.」","mis":"K6-2-u5-X23"}],"explanation":["친구 1과 친구 3은 『국어』 237쪽 3번과 같은 말이에요.","독자를 고려한다고 전할 내용을 빼는 것은 아니에요.","전할 내용을 독자가 알기 쉽게 전하는 것이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L07_challenge#5','kor',6,2,'u5','L07','tb_g6_2_kor_u5_L07_challenge','lesson_challenge','K6-2-u5-C14',3,'ox','auto','누리 소통망에 짧은 글을 올릴 때에도 읽는 사람을 고려하지 않은 표현이 오해를 부를 수 있어요.',ARRAY['K6-2-u5-X45']::text[],false,'{"seq":5,"concept":"K6-2-u5-C14","difficulty":3,"kind":"ox","stem":"누리 소통망에 짧은 글을 올릴 때에도 읽는 사람을 고려하지 않은 표현이 오해를 부를 수 있어요.","answer":"O","reason_options":[{"t":"짧은 글이라도 읽는 사람의 관점에서 생각하지 않으면 뜻이 잘못 전해질 수 있기 때문에","correct":true},{"t":"짧은 글은 독자를 생각하지 않고 마음대로 써도 되기 때문에","mis":"K6-2-u5-X45"}],"mis":"K6-2-u5-X45","explanation":["우리가 자주 쓰는 누리 소통망 글에도 읽는 사람이 있어요.","읽는 사람을 생각하지 않은 표현은 오해를 부를 수 있어요.","독자 고려는 생활 속 글쓰기에도 필요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L07_challenge#6','kor',6,2,'u5','L07','tb_g6_2_kor_u5_L07_challenge','lesson_challenge','K6-2-u5-C17',3,'mc','auto','『국어』 239쪽 「내용 생성 및 조직 하기」에서 친구가 「우리 학교 학생들이 이해하기 쉽게 그림이나 그래프로 제시하면 어떨까?」라고 한 까닭으로 가장 알맞은 것은 무엇인가요?',ARRAY['K6-2-u5-X23','K6-2-u5-X13','K6-2-u5-X24']::text[],false,'{"seq":6,"concept":"K6-2-u5-C17","difficulty":3,"kind":"mc","stem":"『국어』 239쪽 「내용 생성 및 조직 하기」에서 친구가 「우리 학교 학생들이 이해하기 쉽게 그림이나 그래프로 제시하면 어떨까?」라고 한 까닭으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"학생들이 그림이나 그래프로 더 쉽게 이해한다는 특성을 계획 단계에서 조사했기 때문","correct":true},{"t":"그래프를 넣으면 그만큼 글을 덜 써도 되어 쓰기가 편하기 때문","mis":"K6-2-u5-X23"},{"t":"자료는 종류와 개수가 많을수록 좋은 글이 되기 때문","mis":"K6-2-u5-X13"},{"t":"그래프가 들어가면 글이 어렵고 전문적으로 보여 훌륭하기 때문","mis":"K6-2-u5-X24"}],"explanation":["계획하기에서 조사한 독자의 특성이 다음 단계로 이어져요.","독자가 그림이나 그래프로 더 쉽게 이해하니 그래프를 넣어요.","자료는 개수가 아니라 이해를 돕는지로 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L07_challenge#7','kor',6,2,'u5','L07','tb_g6_2_kor_u5_L07_challenge','lesson_challenge','K6-2-u5-C33',3,'match','auto','「계단을 안전하게 이용합시다」에서 독자를 고려한 점과 그 효과를 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K6-2-u5-C33","difficulty":3,"kind":"match","stem":"「계단을 안전하게 이용합시다」에서 독자를 고려한 점과 그 효과를 알맞게 이으세요.","pairs":[{"l":"조사 결과를 그래프로 보여 줌","r":"한눈에 보기 좋아 내용을 쉽게 이해할 수 있다"},{"l":"별표 기호로 안전 수칙을 나누어 보여 줌","r":"기억하기 쉬워 어린 동생들도 오래 기억할 수 있다"},{"l":"학생들이 관심 많은 안전한 학교생활을 다룸","r":"학생들이 주의 깊게 글을 읽는다"}],"mis":"K6-2-u5-X23","explanation":["그래프는 한눈에 보게 해요.","기호로 나누면 기억하기 쉬워요.","관심 있는 주제는 주의 깊게 읽게 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L07_challenge#8','kor',6,2,'u5','L07','tb_g6_2_kor_u5_L07_challenge','lesson_challenge','K6-2-u5-C32',4,'essay','teacher','『국어』 236쪽 「운동장 놀이의 좋은 점」과 237쪽 「그림자 술래잡기」를 견주어, 독자의 반응이 달라진 까닭을 낱말과 내용 두 가지 면에서 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K6-2-u5-C32","difficulty":4,"kind":"essay","stem":"『국어』 236쪽 「운동장 놀이의 좋은 점」과 237쪽 「그림자 술래잡기」를 견주어, 독자의 반응이 달라진 까닭을 낱말과 내용 두 가지 면에서 쓰세요.","answer_guide":{"answer":"예: 「운동장 놀이의 좋은 점」은 「심폐 지구력」처럼 어려운 낱말이 있고, 독자가 관심 있는 놀이 방법이 아니라 글쓴이가 조사한 내용을 써서 독자가 어려워했다. 「그림자 술래잡기」는 낱말이 쉬워 이해하기 쉽고, 독자가 찾던 놀이 방법을 다루어 재미있게 읽었다. 쓰는 사람이 독자를 고려해 글을 썼기 때문에 반응이 달라졌다.","scoring_points":["낱말 면에서 차이(어려운 낱말 ↔ 쉬운 낱말)를 썼는가","내용 면에서 차이(글쓴이의 조사 내용 ↔ 독자의 관심사)를 썼는가","독자를 고려했기 때문이라는 까닭으로 정리했는가"]},"explanation":["두 글은 같은 운동장 놀이를 다뤄요.","낱말의 수준과 독자의 관심사가 달라요.","그래서 독자의 반응이 달라졌어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L07_challenge#9','kor',6,2,'u5','L07','tb_g6_2_kor_u5_L07_challenge','lesson_challenge','K6-2-u5-C16',4,'essay','teacher','『국어』 238~239쪽처럼 「우리 학교 학생들이 안전하게 지내려면 어떻게 해야 할까?」를 주제로 글을 쓴다고 할 때, 글쓰기 과정의 세 단계에서 독자를 어떻게 고려할지 단계마다 한 가지씩 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-2-u5-C16","difficulty":4,"kind":"essay","stem":"『국어』 238~239쪽처럼 「우리 학교 학생들이 안전하게 지내려면 어떻게 해야 할까?」를 주제로 글을 쓴다고 할 때, 글쓰기 과정의 세 단계에서 독자를 어떻게 고려할지 단계마다 한 가지씩 쓰세요.","answer_guide":{"answer":"예: 계획하기에서는 우리 학교 학생들이 학교생활에서 어떤 어려움을 겪는지 조사한다. 내용 생성 및 조직 하기에서는 학생들이 관심 있는 내용을 고르고 이해하기 쉽게 그래프를 넣는다. 쓰고 고쳐 쓰기에서는 학생 전부가 이해하기 쉬운 표현인지, 오해할 만한 표현은 없는지 확인하며 고친다.","scoring_points":["계획하기에서 독자 조사를 썼는가","내용 생성 및 조직 하기에서 독자의 관심·이해를 고려한 내용과 자료를 썼는가","쓰고 고쳐 쓰기에서 표현 확인을 썼는가"]},"explanation":["세 단계마다 독자를 다시 떠올려요.","처음에는 조사, 가운데에는 내용과 자료, 끝에는 표현이에요.","독자는 처음 한 번만 생각하는 것이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L07_challenge#10','kor',6,2,'u5','L07','tb_g6_2_kor_u5_L07_challenge','lesson_challenge','K6-2-u5-C33',4,'essay','teacher','「계단을 안전하게 이용합시다」를 어린 동생이 읽는다고 생각하고, 이 글이 동생에게 잘 전달되는 까닭을 한 가지 쓰고 동생을 위해 더 고쳐 쓸 점을 한 가지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-2-u5-C33","difficulty":4,"kind":"essay","stem":"「계단을 안전하게 이용합시다」를 어린 동생이 읽는다고 생각하고, 이 글이 동생에게 잘 전달되는 까닭을 한 가지 쓰고 동생을 위해 더 고쳐 쓸 점을 한 가지 쓰세요.","answer_guide":{"answer":"예: 별표 기호로 안전 수칙을 나누어 보여 주어 어린 동생도 기억하기 쉽다. 하지만 「안전사고」 같은 낱말은 동생이 어려워할 수 있으니 「다치는 일」처럼 쉬운 말로 바꾸어 쓰면 좋겠다.","scoring_points":["잘 전달되는 까닭을 글의 특징과 이어 썼는가","동생의 수준을 생각해 고쳐 쓸 점을 썼는가","고쳐 쓸 점이 독자를 고려한 것인가"]},"explanation":["독자가 바뀌면 고려할 점도 달라져요.","어린 동생의 낱말 수준을 생각해요.","전할 내용은 그대로 두고 표현을 고쳐요."],"asset":{"type":"passage","lines":["[그래프] 계단에서 위험한 상황을 겪은 적이 있습니까?","[그래프] 있다 40명 · 거의 없다 6명 · 없다 4명","(간추림) 학교 정문에서 등교하는 학생 50명에게 물었더니 40명이 위험한 상황을 겪었다.","[별표 기호] 뛰지 말고 천천히 걸어요!","[별표 기호] 필요할 때에는 계단 난간을 잡아요!","[별표 기호] 앞을 잘 보고 걸어요!","[쓴 사람] ○○초등학교 전교 어린이회"],"numbered":false,"title":"「계단을 안전하게 이용합시다」(『국어』 240쪽, 간추림)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L09_basic#1','kor',6,2,'u5','L09','tb_g6_2_kor_u5_L09_basic','lesson_basic','K6-2-u5-C19',1,'mc','auto','기사문에서 「신문 기사의 제목」을 무엇이라고 하나요?',ARRAY['K6-2-u5-X28']::text[],false,'{"seq":1,"concept":"K6-2-u5-C19","difficulty":1,"kind":"mc","stem":"기사문에서 「신문 기사의 제목」을 무엇이라고 하나요?","options":[{"t":"표제","correct":true},{"t":"부제","mis":"K6-2-u5-X28"},{"t":"전문","mis":"K6-2-u5-X28"},{"t":"본문","mis":"K6-2-u5-X28"}],"explanation":["『국어』 242쪽에서 기사문의 짜임을 살펴봤어요.","신문 기사의 제목은 표제예요.","부제는 표제를 보충하는 제목이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L09_basic#2','kor',6,2,'u5','L09','tb_g6_2_kor_u5_L09_basic','lesson_basic','K6-2-u5-C34',1,'sa','auto','「희망초등학교, ‘전문가와 함께 하는 예술 진로 캠프’ 개최」에서 3~4학년 학생들은 어떤 직업이 하는 일을 익혔나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"K6-2-u5-C34","difficulty":1,"kind":"sa","stem":"「희망초등학교, ‘전문가와 함께 하는 예술 진로 캠프’ 개최」에서 3~4학년 학생들은 어떤 직업이 하는 일을 익혔나요? 두 글자로 쓰세요.","answer":["성우"],"explanation":["3~4학년은 시청각실에 모였어요.","만화 영화에서 목소리 연기를 한 성우 선생님이 오셨어요.","성우가 하는 일과 목소리 연기 방법을 배웠어요."],"asset":{"type":"passage","lines":["[본문] (간추림) 11월 8일 — 1~2학년, 미술실, 그림 작가 체험","[본문] (간추림) 같은 날 — 3~4학년, 시청각실, 성우가 하는 일 익히기","[본문] (간추림) 11월 9일 — 5~6학년, 실과 실습실, 특수 분장 체험","[본문] (간추림) 6학년 김○○ 학생과 3학년 박○○ 학생의 소감","[쓴 사람] 희망초등학교 조○○ 기자"],"numbered":false,"title":"「희망초등학교, ‘전문가와 함께 하는 예술 진로 캠프’ 개최」(『국어』 243쪽, 간추림)"},"mis":"K6-2-u5-X29"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L09_basic#3','kor',6,2,'u5','L09','tb_g6_2_kor_u5_L09_basic','lesson_basic','K6-2-u5-C18',1,'ox','auto','기사문은 어떤 사실을 전달하고자 직접 보고, 듣고, 조사해 객관적으로 쓴 글이에요.',ARRAY['K6-2-u5-X26']::text[],false,'{"seq":3,"concept":"K6-2-u5-C18","difficulty":1,"kind":"ox","stem":"기사문은 어떤 사실을 전달하고자 직접 보고, 듣고, 조사해 객관적으로 쓴 글이에요.","answer":"O","reason_options":[{"t":"기사문은 쓴 사람의 느낌이 아니라 확인한 사실을 독자에게 전하는 글이기 때문에","correct":true},{"t":"기사문은 쓴 사람이 상상한 이야기를 재미있게 꾸민 글이기 때문에","mis":"K6-2-u5-X26"}],"mis":"K6-2-u5-X26","explanation":["『국어』 244쪽에서 기사문을 이렇게 정리했어요.","직접 보고, 듣고, 조사한 사실을 써요.","독자가 이해하기 쉽게 사진, 그림, 그래프를 넣을 수도 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L09_basic#4','kor',6,2,'u5','L09','tb_g6_2_kor_u5_L09_basic','lesson_basic','K6-2-u5-C19',1,'blank','auto','『국어』 244쪽의 정리예요. 「기사문은 제목, 전문, (    )(으)로 구성되어 있다.」 빈칸에 알맞은 낱말은 무엇인가요?',ARRAY['K6-2-u5-X28','K6-2-u5-X29']::text[],false,'{"seq":4,"concept":"K6-2-u5-C19","difficulty":1,"kind":"blank","stem":"『국어』 244쪽의 정리예요. 「기사문은 제목, 전문, (    )(으)로 구성되어 있다.」 빈칸에 알맞은 낱말은 무엇인가요?","options":[{"t":"본문","correct":true},{"t":"부제","mis":"K6-2-u5-X28"},{"t":"사실","mis":"K6-2-u5-X28"},{"t":"육하원칙","mis":"K6-2-u5-X29"}],"explanation":["기사문은 세 부분으로 이루어져요.","제목, 전문, 본문이에요.","본문은 기사문의 주된 내용을 담은 부분이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L09_basic#5','kor',6,2,'u5','L09','tb_g6_2_kor_u5_L09_basic','lesson_basic','K6-2-u5-C19',2,'mc','auto','「희망초등학교, ‘전문가와 함께 하는 예술 진로 캠프’ 개최」에서 「― 다양한 예술 직업의 세계를 탐구하고 꿈을 키워요 ―」 부분은 무엇인가요?',ARRAY['K6-2-u5-X28']::text[],false,'{"seq":5,"concept":"K6-2-u5-C19","difficulty":2,"kind":"mc","stem":"「희망초등학교, ‘전문가와 함께 하는 예술 진로 캠프’ 개최」에서 「― 다양한 예술 직업의 세계를 탐구하고 꿈을 키워요 ―」 부분은 무엇인가요?","options":[{"t":"표제에 덧붙어 그것을 보충하는 부제","correct":true},{"t":"기사의 주된 내용을 담은 본문","mis":"K6-2-u5-X28"},{"t":"본문 앞에 놓이는 요약 부분인 전문","mis":"K6-2-u5-X28"},{"t":"기사를 쓴 기자의 이름","mis":"K6-2-u5-X28"}],"explanation":["표제 바로 아래에 붙은 제목이에요.","표제에 덧붙어 그것을 보충하는 제목을 부제라고 해요.","부제는 필요할 때 붙여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L09_basic#6','kor',6,2,'u5','L09','tb_g6_2_kor_u5_L09_basic','lesson_basic','K6-2-u5-C34',2,'mc','auto','「희망초등학교, ‘전문가와 함께 하는 예술 진로 캠프’ 개최」의 전문에서 알 수 있는 내용을 육하원칙으로 바르게 정리한 것은 무엇인가요?',ARRAY['K6-2-u5-X29']::text[],false,'{"seq":6,"concept":"K6-2-u5-C34","difficulty":2,"kind":"mc","stem":"「희망초등학교, ‘전문가와 함께 하는 예술 진로 캠프’ 개최」의 전문에서 알 수 있는 내용을 육하원칙으로 바르게 정리한 것은 무엇인가요?","options":[{"t":"누가 — 희망초등학교 1~6학년 학생들, 언제 — 11월 8일부터 9일까지","correct":true},{"t":"누가 — 그림 작가 선생님, 언제 — 11월 9일만","mis":"K6-2-u5-X29"},{"t":"어디에서 — 학교 강당, 무엇을 — 운동회","mis":"K6-2-u5-X29"},{"t":"왜 — 캠프가 재미있어서, 어떻게 — 혼자서","mis":"K6-2-u5-X29"}],"explanation":["전문은 기사문의 내용을 육하원칙 중심으로 요약해요.","누가는 1~6학년 학생들, 언제는 11월 8일부터 9일까지예요.","전문만 읽어도 기사 내용을 알 수 있어요."],"asset":{"type":"passage","lines":["[표제] 희망초등학교, ‘전문가와 함께 하는 예술 진로 캠프’ 개최","[부제] ― 다양한 예술 직업의 세계를 탐구하고 꿈을 키워요 ―","[전문] (간추림) 1~6학년 학생들이 11월 8일부터 9일까지 이틀간 캠프에 참여했다.","[전문] (간추림) 예술 관련 직업을 이해하고 소질과 적성을 찾게 하려고 열렸다.","[전문] (간추림) 미술실·시청각실·실과 실습실에서 그림 작가, 성우, 특수 분장을 경험했다."],"numbered":false,"title":"「희망초등학교, ‘전문가와 함께 하는 예술 진로 캠프’ 개최」(『국어』 242쪽)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L09_basic#7','kor',6,2,'u5','L09','tb_g6_2_kor_u5_L09_basic','lesson_basic','K6-2-u5-C34',2,'match','auto','「희망초등학교, ‘전문가와 함께 하는 예술 진로 캠프’ 개최」의 본문에서 학년과 체험을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K6-2-u5-C34","difficulty":2,"kind":"match","stem":"「희망초등학교, ‘전문가와 함께 하는 예술 진로 캠프’ 개최」의 본문에서 학년과 체험을 알맞게 이으세요.","pairs":[{"l":"1~2학년","r":"미술실에서 그림 작가 체험"},{"l":"3~4학년","r":"시청각실에서 성우가 하는 일 익히기"},{"l":"5~6학년","r":"실과 실습실에서 특수 분장 체험"}],"mis":"K6-2-u5-X29","explanation":["본문은 날짜와 학년별로 체험을 자세히 썼어요.","누가, 어디에서, 무엇을 했는지 정리해요.","육하원칙으로 정리하면 내용이 또렷해져요."],"asset":{"type":"passage","lines":["[본문] (간추림) 11월 8일 — 1~2학년, 미술실, 그림 작가 체험","[본문] (간추림) 같은 날 — 3~4학년, 시청각실, 성우가 하는 일 익히기","[본문] (간추림) 11월 9일 — 5~6학년, 실과 실습실, 특수 분장 체험","[본문] (간추림) 6학년 김○○ 학생과 3학년 박○○ 학생의 소감","[쓴 사람] 희망초등학교 조○○ 기자"],"numbered":false,"title":"「희망초등학교, ‘전문가와 함께 하는 예술 진로 캠프’ 개최」(『국어』 243쪽, 간추림)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L09_basic#8','kor',6,2,'u5','L09','tb_g6_2_kor_u5_L09_basic','lesson_basic','K6-2-u5-C21',2,'mc','auto','『국어』 245쪽 계획하기 예시 답안에서 기삿거리를 「에너지 절약 생활화」로, 필요한 자료를 「학생의 생각을 나타내는 자료」로 정했어요. 알맞은 자료 수집 방법은 무엇인가요?',ARRAY['K6-2-u5-X27','K6-2-u5-X23']::text[],false,'{"seq":8,"concept":"K6-2-u5-C21","difficulty":2,"kind":"mc","stem":"『국어』 245쪽 계획하기 예시 답안에서 기삿거리를 「에너지 절약 생활화」로, 필요한 자료를 「학생의 생각을 나타내는 자료」로 정했어요. 알맞은 자료 수집 방법은 무엇인가요?","options":[{"t":"학생을 대상으로 설문 조사를 실시한다","correct":true},{"t":"친구에게 들은 소문을 그대로 쓴다","mis":"K6-2-u5-X27"},{"t":"그럴 것 같은 숫자를 짐작해 쓴다","mis":"K6-2-u5-X27"},{"t":"에너지와 관계없는 사진을 많이 모은다","mis":"K6-2-u5-X23"}],"explanation":["학생의 생각을 알려면 학생에게 물어야 해요.","그래서 학생을 대상으로 설문 조사를 해요.","소문이나 짐작한 숫자는 기사문에 쓸 수 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L09_basic#9','kor',6,2,'u5','L09','tb_g6_2_kor_u5_L09_basic','lesson_basic','K6-2-u5-C21',2,'ox','auto','기사문을 쓸 때 제목은 반드시 본문보다 먼저 정해야 해요.',ARRAY['K6-2-u5-X46']::text[],false,'{"seq":9,"concept":"K6-2-u5-C21","difficulty":2,"kind":"ox","stem":"기사문을 쓸 때 제목은 반드시 본문보다 먼저 정해야 해요.","answer":"X","reason_options":[{"t":"제목을 먼저 정할 수도 있지만, 작성한 본문의 내용을 보고 제목을 정할 수도 있기 때문에","correct":true},{"t":"제목을 먼저 정하지 않으면 기사문을 쓸 수 없기 때문에","mis":"K6-2-u5-X46"}],"mis":"K6-2-u5-X46","explanation":["제목을 먼저 정해도 돼요.","본문을 다 쓴 뒤 내용을 보고 제목을 정해도 돼요.","어느 쪽이든 제목은 기사 내용을 간결하게 드러내야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L09_basic#10','kor',6,2,'u5','L09','tb_g6_2_kor_u5_L09_basic','lesson_basic','K6-2-u5-C20',3,'mc','auto','『국어』 246쪽 예시 기사문의 전문에 대한 설명으로 가장 알맞은 것은 무엇인가요?',ARRAY['K6-2-u5-X26','K6-2-u5-X27','K6-2-u5-X28']::text[],false,'{"seq":10,"concept":"K6-2-u5-C20","difficulty":3,"kind":"mc","stem":"『국어』 246쪽 예시 기사문의 전문에 대한 설명으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"어린이 기자단이 취재한 에너지 낭비 실태와 설문 조사 결과를 간결하게 요약했다","correct":true},{"t":"기자가 상상한 교실 이야기를 재미있게 꾸며 썼다","mis":"K6-2-u5-X26"},{"t":"출처를 알 수 없는 소문과 짐작한 숫자를 모아 썼다","mis":"K6-2-u5-X27"},{"t":"기사 내용과 관계없는 기자의 느낌과 다짐만 썼다","mis":"K6-2-u5-X28"}],"explanation":["전문은 본문 앞에 놓이는 요약 부분이에요.","취재 결과와 설문 조사 결과를 짧게 정리했어요.","확인한 사실을 바탕으로 썼어요."],"asset":{"type":"passage","lines":["[제목] 텅 빈 교실에 전등만 ‘활짝’…… 우리 학교 에너지 낭비 이대로 괜찮을까?","[전문] (간추림) 어린이 기자단 취재 결과, 점심시간 텅 빈 교실에도 전등이 켜져 있었다.","[전문] (간추림) 학생들은 설문 조사에서 ‘전등 끄기’를 가장 좋은 실천 방법으로 꼽았다.","[본문] (간추림) 지난 1일부터 3일까지 점심시간에 교실들을 둘러본 일을 자세히 썼다.","[본문] (간추림) 기후 위기와 에너지 절약, 마지막에 나가는 사람이 전등 확인하기"],"numbered":false,"title":"예시 기사문(『국어』 246쪽, 간추림)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L09_challenge#1','kor',6,2,'u5','L09','tb_g6_2_kor_u5_L09_challenge','lesson_challenge','K6-2-u5-C19',2,'sa','auto','『국어』 244쪽의 정리예요. 「전문은 기사문의 내용을 ‘누가, 언제, 어디에서, 무엇을, 어떻게, 왜’와 같이 (    )을/를 중심으로 요약하여 제시한 것이다.」 빈칸에 알맞은 낱말을 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K6-2-u5-C19","difficulty":2,"kind":"sa","stem":"『국어』 244쪽의 정리예요. 「전문은 기사문의 내용을 ‘누가, 언제, 어디에서, 무엇을, 어떻게, 왜’와 같이 (    )을/를 중심으로 요약하여 제시한 것이다.」 빈칸에 알맞은 낱말을 쓰세요.","answer":["육하원칙"],"explanation":["누가, 언제, 어디에서, 무엇을, 어떻게, 왜를 육하원칙이라고 해요.","전문은 육하원칙을 중심으로 요약해요.","그래서 전문만 읽어도 내용을 알 수 있어요."],"mis":"K6-2-u5-X29"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L09_challenge#2','kor',6,2,'u5','L09','tb_g6_2_kor_u5_L09_challenge','lesson_challenge','K6-2-u5-C21',2,'mc','auto','『국어』 245쪽에서 기삿거리를 정할 때 친구들이 생각한 점으로 알맞은 것은 무엇인가요?',ARRAY['K6-2-u5-X30','K6-2-u5-X31']::text[],false,'{"seq":2,"concept":"K6-2-u5-C21","difficulty":2,"kind":"mc","stem":"『국어』 245쪽에서 기삿거리를 정할 때 친구들이 생각한 점으로 알맞은 것은 무엇인가요?","options":[{"t":"친구들이 관심을 두는 일이고 우리 주변에서 경험할 수 있는 일인지","correct":true},{"t":"아무도 모르는 먼 나라에서 들려온 소문인지","mis":"K6-2-u5-X30"},{"t":"내가 직접 가서 보거나 확인할 수 없는 일인지","mis":"K6-2-u5-X30"},{"t":"제목을 크고 놀랍게 부풀려 쓸 수 있는 일인지","mis":"K6-2-u5-X31"}],"explanation":["친구는 「친구들이 관심을 두는 일이 무엇인지 생각해야 해.」라고 했어요.","「우리 주변에서 경험할 수 있는 일이면 좋을 것 같아.」라고도 했어요.","독자의 관심과 확인할 수 있는지를 함께 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L09_challenge#3','kor',6,2,'u5','L09','tb_g6_2_kor_u5_L09_challenge','lesson_challenge','K6-2-u5-C18',3,'mc','auto','『국어』 245쪽에서 독자의 특성을 「초등학생이므로 실천할 수 있는 내용에 관심이 많다.」라고 정리했어요. 이 특성을 고려해 기삿거리를 「에너지 절약 생활화」로 정한 까닭으로 가장 알맞은 것은 무엇인가요?',ARRAY['K6-2-u5-X24','K6-2-u5-X27','K6-2-u5-X30']::text[],false,'{"seq":3,"concept":"K6-2-u5-C18","difficulty":3,"kind":"mc","stem":"『국어』 245쪽에서 독자의 특성을 「초등학생이므로 실천할 수 있는 내용에 관심이 많다.」라고 정리했어요. 이 특성을 고려해 기삿거리를 「에너지 절약 생활화」로 정한 까닭으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"전등 끄기처럼 학생들이 생활에서 직접 실천할 수 있는 내용이라서","correct":true},{"t":"어려운 낱말을 많이 쓸 수 있는 내용이라서","mis":"K6-2-u5-X24"},{"t":"조사하지 않고도 쓸 수 있는 내용이라서","mis":"K6-2-u5-X27"},{"t":"학생들이 관심 없는 내용이어도 상관없어서","mis":"K6-2-u5-X30"}],"explanation":["독자는 실천할 수 있는 내용에 관심이 많아요.","에너지 절약은 생활 속에서 직접 실천할 수 있어요.","독자의 특성에 맞추어 기삿거리를 골랐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L09_challenge#4','kor',6,2,'u5','L09','tb_g6_2_kor_u5_L09_challenge','lesson_challenge','K6-2-u5-C20',3,'error','auto','『국어』 246쪽 예시 기사문을 읽고 친구들이 말했어요. 기사문의 특성을 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-2-u5-X27','K6-2-u5-X26','K6-2-u5-X28']::text[],false,'{"seq":4,"concept":"K6-2-u5-C20","difficulty":3,"kind":"error","stem":"『국어』 246쪽 예시 기사문을 읽고 친구들이 말했어요. 기사문의 특성을 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"친구 3 — 「기사문이니까 확인하지 않은 소문이라도 재미있으면 넣어도 돼.」","correct":true,"mis_target":"K6-2-u5-X27"},{"t":"친구 1 — 「설문 조사 결과처럼 조사한 사실을 바탕으로 썼어.」","mis":"K6-2-u5-X26"},{"t":"친구 2 — 「전문만 읽어도 기사 내용을 알 수 있게 요약했어.」","mis":"K6-2-u5-X28"}],"explanation":["기사문은 확인한 사실을 전해요.","확인하지 않은 소문은 재미있어도 쓰지 않아요.","전문은 내용을 요약하는 부분이에요."],"asset":{"type":"passage","lines":["[제목] 텅 빈 교실에 전등만 ‘활짝’…… 우리 학교 에너지 낭비 이대로 괜찮을까?","[전문] (간추림) 어린이 기자단 취재 결과, 점심시간 텅 빈 교실에도 전등이 켜져 있었다.","[전문] (간추림) 학생들은 설문 조사에서 ‘전등 끄기’를 가장 좋은 실천 방법으로 꼽았다.","[본문] (간추림) 지난 1일부터 3일까지 점심시간에 교실들을 둘러본 일을 자세히 썼다.","[본문] (간추림) 기후 위기와 에너지 절약, 마지막에 나가는 사람이 전등 확인하기"],"numbered":false,"title":"예시 기사문(『국어』 246쪽, 간추림)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L09_challenge#5','kor',6,2,'u5','L09','tb_g6_2_kor_u5_L09_challenge','lesson_challenge','K6-2-u5-C21',3,'ox','auto','기사문에 필요한 자료를 제시할 때에는 반드시 출처를 밝혀야 해요.',ARRAY['K6-2-u5-X32']::text[],false,'{"seq":5,"concept":"K6-2-u5-C21","difficulty":3,"kind":"ox","stem":"기사문에 필요한 자료를 제시할 때에는 반드시 출처를 밝혀야 해요.","answer":"O","reason_options":[{"t":"독자가 자료를 믿고 확인할 수 있도록 자료를 어디에서 얻었는지 알려야 하기 때문에","correct":true},{"t":"자료가 들어가면 출처는 밝히지 않아도 독자가 알아서 믿기 때문에","mis":"K6-2-u5-X32"}],"mis":"K6-2-u5-X32","explanation":["기사문에 사진, 그래프 같은 자료를 넣을 수 있어요.","그때는 반드시 출처를 밝혀요.","그래야 독자가 기사 내용을 믿을 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L09_challenge#6','kor',6,2,'u5','L09','tb_g6_2_kor_u5_L09_challenge','lesson_challenge','K6-2-u5-C21',3,'mc','auto','『국어』 247쪽 수정하기 (1)에서 기사문을 잘 썼는지 스스로 확인하는 물음으로 알맞은 것은 무엇인가요?',ARRAY['K6-2-u5-X22','K6-2-u5-X13','K6-2-u5-X24']::text[],false,'{"seq":6,"concept":"K6-2-u5-C21","difficulty":3,"kind":"mc","stem":"『국어』 247쪽 수정하기 (1)에서 기사문을 잘 썼는지 스스로 확인하는 물음으로 알맞은 것은 무엇인가요?","options":[{"t":"독자의 이해를 돕는 자료를 적절하게 사용했나요?","correct":true},{"t":"글씨를 예쁘게 꾸몄나요?","mis":"K6-2-u5-X22"},{"t":"자료를 될 수 있는 대로 많이 넣었나요?","mis":"K6-2-u5-X13"},{"t":"어려운 낱말을 많이 썼나요?","mis":"K6-2-u5-X24"}],"explanation":["수정하기 (1)은 네 가지를 물어요.","기삿거리, 제목, 이해하기 쉬운 말, 자료를 확인해요.","모두 독자를 고려했는지 보는 물음이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L09_challenge#7','kor',6,2,'u5','L09','tb_g6_2_kor_u5_L09_challenge','lesson_challenge','K6-2-u5-C19',3,'match','auto','『국어』 244쪽에서 정리한 기사문의 부분과 하는 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K6-2-u5-C19","difficulty":3,"kind":"match","stem":"『국어』 244쪽에서 정리한 기사문의 부분과 하는 일을 알맞게 이으세요.","pairs":[{"l":"표제","r":"기사 내용을 간결하게 드러내는 제목"},{"l":"부제","r":"필요할 때 표제를 보충하는 제목"},{"l":"전문","r":"본문 앞에서 내용을 육하원칙 중심으로 요약"},{"l":"본문","r":"기사문의 주된 내용을 자세히 담음"}],"mis":"K6-2-u5-X28","explanation":["제목은 표제와 부제로 이루어져요.","전문은 요약, 본문은 주된 내용이에요.","부분마다 하는 일이 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L09_challenge#8','kor',6,2,'u5','L09','tb_g6_2_kor_u5_L09_challenge','lesson_challenge','K6-2-u5-C34',4,'essay','teacher','「희망초등학교, ‘전문가와 함께 하는 예술 진로 캠프’ 개최」의 전문을 육하원칙(누가, 언제, 어디에서, 무엇을, 어떻게, 왜)에 따라 정리해 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K6-2-u5-C34","difficulty":4,"kind":"essay","stem":"「희망초등학교, ‘전문가와 함께 하는 예술 진로 캠프’ 개최」의 전문을 육하원칙(누가, 언제, 어디에서, 무엇을, 어떻게, 왜)에 따라 정리해 쓰세요.","answer_guide":{"answer":"예: 누가 — 희망초등학교 1~6학년 학생들이, 언제 — 11월 8일부터 9일까지 이틀간, 어디에서 — 희망초등학교 미술실·시청각실·실과 실습실에서, 무엇을 — ‘전문가와 함께 하는 예술 진로 캠프’에 참여했다, 어떻게 — 그림 작가·성우·특수 분장과 관련 있는 예술 직업을 경험하며, 왜 — 예술과 관련 있는 다양한 직업을 이해하고 자신의 소질과 적성을 찾으려고.","scoring_points":["누가·언제·어디에서를 바르게 썼는가","무엇을·어떻게를 바르게 썼는가","왜(캠프를 연 목적)를 썼는가"]},"explanation":["전문에는 육하원칙이 다 들어 있어요.","하나씩 찾아 정리해요.","왜는 캠프를 연 목적이에요."],"asset":{"type":"passage","lines":["[표제] 희망초등학교, ‘전문가와 함께 하는 예술 진로 캠프’ 개최","[부제] ― 다양한 예술 직업의 세계를 탐구하고 꿈을 키워요 ―","[전문] (간추림) 1~6학년 학생들이 11월 8일부터 9일까지 이틀간 캠프에 참여했다.","[전문] (간추림) 예술 관련 직업을 이해하고 소질과 적성을 찾게 하려고 열렸다.","[전문] (간추림) 미술실·시청각실·실과 실습실에서 그림 작가, 성우, 특수 분장을 경험했다."],"numbered":false,"title":"「희망초등학교, ‘전문가와 함께 하는 예술 진로 캠프’ 개최」(『국어』 242쪽)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L09_challenge#9','kor',6,2,'u5','L09','tb_g6_2_kor_u5_L09_challenge','lesson_challenge','K6-2-u5-C21',4,'essay','teacher','『국어』 245쪽처럼 학교 신문에 실을 기사문 작성 계획을 세워 쓰세요. 독자의 특성, 기삿거리, 필요한 자료, 자료 수집 방법을 모두 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-2-u5-C21","difficulty":4,"kind":"essay","stem":"『국어』 245쪽처럼 학교 신문에 실을 기사문 작성 계획을 세워 쓰세요. 독자의 특성, 기삿거리, 필요한 자료, 자료 수집 방법을 모두 쓰세요.","answer_guide":{"answer":"예: 독자의 특성 — 우리 학교 학생들은 실천할 수 있는 내용에 관심이 많다. 기삿거리 — 에너지 절약 생활화. 필요한 자료 — 학생의 생각을 나타내는 자료. 자료 수집 방법 — 학생을 대상으로 설문 조사를 실시한다.","scoring_points":["독자의 특성을 썼는가","독자의 특성에 맞는 기삿거리를 정했는가","필요한 자료와 수집 방법이 기삿거리와 이어지는가"]},"explanation":["먼저 독자가 누구이고 무엇에 관심이 있는지 써요.","그 관심에 맞는 기삿거리를 정해요.","필요한 자료와 모을 방법까지 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L09_challenge#10','kor',6,2,'u5','L09','tb_g6_2_kor_u5_L09_challenge','lesson_challenge','K6-2-u5-C20',4,'essay','teacher','『국어』 246쪽 예시 기사문을 짝과 바꾸어 읽었다고 생각하고, 『국어』 247쪽 수정하기 (1)의 네 물음 가운데 두 가지로 이 기사문을 점검해 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-2-u5-C20","difficulty":4,"kind":"essay","stem":"『국어』 246쪽 예시 기사문을 짝과 바꾸어 읽었다고 생각하고, 『국어』 247쪽 수정하기 (1)의 네 물음 가운데 두 가지로 이 기사문을 점검해 쓰세요.","answer_guide":{"answer":"예: 관심을 끌 만한 기삿거리를 골랐나요? — 우리 학교 교실의 에너지 낭비는 학생들이 직접 겪는 일이라 관심을 끈다. 흥미를 끄는 제목을 썼나요? — 「텅 빈 교실에 전등만 ‘활짝’……」은 궁금증을 일으켜 읽고 싶게 만든다.","scoring_points":["수정하기 물음 두 가지를 골랐는가","물음마다 기사문의 내용을 근거로 점검했는가","독자의 관점에서 판단했는가"]},"explanation":["수정하기 물음은 독자를 고려했는지 보는 물음이에요.","기사문에서 근거를 찾아 판단해요.","고쳐 쓸 점이 있으면 함께 적어요."],"asset":{"type":"passage","lines":["[제목] 텅 빈 교실에 전등만 ‘활짝’…… 우리 학교 에너지 낭비 이대로 괜찮을까?","[전문] (간추림) 어린이 기자단 취재 결과, 점심시간 텅 빈 교실에도 전등이 켜져 있었다.","[전문] (간추림) 학생들은 설문 조사에서 ‘전등 끄기’를 가장 좋은 실천 방법으로 꼽았다.","[본문] (간추림) 지난 1일부터 3일까지 점심시간에 교실들을 둘러본 일을 자세히 썼다.","[본문] (간추림) 기후 위기와 에너지 절약, 마지막에 나가는 사람이 전등 확인하기"],"numbered":false,"title":"예시 기사문(『국어』 246쪽, 간추림)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L12_basic#1','kor',6,2,'u5','L12','tb_g6_2_kor_u5_L12_basic','lesson_basic','K6-2-u5-C22',1,'mc','auto','편지글을 이루는 부분을 바르게 모은 것은 무엇인가요?',ARRAY['K6-2-u5-X33','K6-2-u5-X28']::text[],false,'{"seq":1,"concept":"K6-2-u5-C22","difficulty":1,"kind":"mc","stem":"편지글을 이루는 부분을 바르게 모은 것은 무엇인가요?","options":[{"t":"받는 사람, 첫인사, 하고 싶은 말, 끝인사, 쓴 날짜, 보내는 사람","correct":true},{"t":"받는 사람, 하고 싶은 말, 끝인사, 보내는 사람","mis":"K6-2-u5-X33"},{"t":"첫인사, 하고 싶은 말, 끝인사, 쓴 날짜","mis":"K6-2-u5-X33"},{"t":"제목, 전문, 본문, 쓴 날짜, 보내는 사람","mis":"K6-2-u5-X28"}],"explanation":["편지글은 기본적으로 여섯 부분으로 이루어져요.","받는 사람, 첫인사, 하고 싶은 말, 끝인사, 쓴 날짜, 보내는 사람이에요.","제목, 전문, 본문은 기사문의 짜임이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L12_basic#2','kor',6,2,'u5','L12','tb_g6_2_kor_u5_L12_basic','lesson_basic','K6-2-u5-C25',1,'sa','auto','『국어』 253쪽 기초 다지기예요. 「맑다」는 어떻게 소리 나나요? [ ] 안에 들어갈 발음을 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"K6-2-u5-C25","difficulty":1,"kind":"sa","stem":"『국어』 253쪽 기초 다지기예요. 「맑다」는 어떻게 소리 나나요? [ ] 안에 들어갈 발음을 쓰세요.","answer":["막따"],"explanation":["겹받침 ㄺ 뒤에 자음자 ㄷ이 와요.","겹받침 ㄺ이 자음자와 만나면 [ㄱ]으로 소리 나요.","그래서 「맑다」는 [막따]로 발음해요."],"mis":"K6-2-u5-X38"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L12_basic#3','kor',6,2,'u5','L12','tb_g6_2_kor_u5_L12_basic','lesson_basic','K6-2-u5-C25',1,'ox','auto','겹받침 ㄺ이 들어 있는 「읽다」는 뒤에 자음자가 와서 [ㄱ]으로 소리 나요.',ARRAY['K6-2-u5-X38']::text[],false,'{"seq":3,"concept":"K6-2-u5-C25","difficulty":1,"kind":"ox","stem":"겹받침 ㄺ이 들어 있는 「읽다」는 뒤에 자음자가 와서 [ㄱ]으로 소리 나요.","answer":"O","reason_options":[{"t":"「읽다」는 [익따]처럼 받침 ㄱ만 소리 나기 때문에","correct":true},{"t":"겹받침은 언제나 두 소리를 다 내기 때문에","mis":"K6-2-u5-X38"}],"mis":"K6-2-u5-X38","explanation":["겹받침 ㄺ이 자음자와 만나면 [ㄱ]으로 소리 나요.","「읽다」는 [익따]로 발음해요.","받침 자리에서는 한 소리만 나요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L12_basic#4','kor',6,2,'u5','L12','tb_g6_2_kor_u5_L12_basic','lesson_basic','K6-2-u5-C35',1,'mc','auto','감사한 마음을 전할 때 쓰는 편지는 무엇인가요?',ARRAY['K6-2-u5-X44']::text[],false,'{"seq":4,"concept":"K6-2-u5-C35","difficulty":1,"kind":"mc","stem":"감사한 마음을 전할 때 쓰는 편지는 무엇인가요?","options":[{"t":"감사 편지","correct":true},{"t":"초대 편지","mis":"K6-2-u5-X44"},{"t":"사과 편지","mis":"K6-2-u5-X44"},{"t":"알림 편지","mis":"K6-2-u5-X44"}],"explanation":["편지는 쓰는 목적에 따라 종류가 달라요.","감사한 마음을 전할 때에는 감사 편지를 써요.","초대할 때는 초대 편지, 미안할 때는 사과 편지예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L12_basic#5','kor',6,2,'u5','L12','tb_g6_2_kor_u5_L12_basic','lesson_basic','K6-2-u5-C22',2,'mc','auto','『국어』 248쪽 「쓰고 싶은 글의 내용 정리하기」에서 생각할 물음으로 알맞은 것은 무엇인가요?',ARRAY['K6-2-u5-X37','K6-2-u5-X13','K6-2-u5-X43']::text[],false,'{"seq":5,"concept":"K6-2-u5-C22","difficulty":2,"kind":"mc","stem":"『국어』 248쪽 「쓰고 싶은 글의 내용 정리하기」에서 생각할 물음으로 알맞은 것은 무엇인가요?","options":[{"t":"독자는 어떤 것에 관심이 있고 무엇을 궁금해하나요?","correct":true},{"t":"편지지를 얼마나 화려하게 꾸밀까요?","mis":"K6-2-u5-X37"},{"t":"편지를 몇 줄 이상 길게 쓸까요?","mis":"K6-2-u5-X13"},{"t":"받는 사람과 상관없이 내가 하고 싶은 말만 쓸까요?","mis":"K6-2-u5-X43"}],"explanation":["하고 싶은 인사말, 독자의 관심과 궁금한 점을 생각해요.","전하고 싶은 마음, 알맞은 매체, 끝인사도 정리해요.","꾸미기나 길이는 편지 내용을 정리하는 물음이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L12_basic#6','kor',6,2,'u5','L12','tb_g6_2_kor_u5_L12_basic','lesson_basic','K6-2-u5-C25',2,'blank','auto','『국어』 253쪽 기초 다지기예요. 「밟고」는 [ (    ) ](으)로 소리 나요. 빈칸에 알맞은 발음은 무엇인가요?',ARRAY['K6-2-u5-X39','K6-2-u5-X38']::text[],false,'{"seq":6,"concept":"K6-2-u5-C25","difficulty":2,"kind":"blank","stem":"『국어』 253쪽 기초 다지기예요. 「밟고」는 [ (    ) ](으)로 소리 나요. 빈칸에 알맞은 발음은 무엇인가요?","options":[{"t":"밥ː꼬","correct":true},{"t":"발꼬","mis":"K6-2-u5-X39"},{"t":"발브고","mis":"K6-2-u5-X38"},{"t":"밥고","mis":"K6-2-u5-X39"}],"explanation":["겹받침 ㄼ은 보통 자음자와 만나면 [ㄹ]로 소리 나요.","하지만 「밟-」은 예외적으로 [ㅂ]으로 발음해요.","그래서 「밟고」는 [밥ː꼬]예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L12_basic#7','kor',6,2,'u5','L12','tb_g6_2_kor_u5_L12_basic','lesson_basic','K6-2-u5-C35',2,'match','auto','편지를 쓰는 목적과 편지의 종류를 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K6-2-u5-C35","difficulty":2,"kind":"match","stem":"편지를 쓰는 목적과 편지의 종류를 알맞게 이으세요.","pairs":[{"l":"행사에 초대할 때","r":"초대 편지"},{"l":"미안한 마음을 전할 때","r":"사과 편지"},{"l":"기쁜 일을 축하할 때","r":"축하 편지"},{"l":"힘든 일을 위로할 때","r":"위로 편지"}],"mis":"K6-2-u5-X44","explanation":["편지는 전하려는 마음에 따라 종류가 달라요.","초대, 사과, 축하, 위로 편지가 있어요.","소식은 안부 편지, 정보는 알림 편지예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L12_basic#8','kor',6,2,'u5','L12','tb_g6_2_kor_u5_L12_basic','lesson_basic','K6-2-u5-C24',2,'mc','auto','『국어』 248쪽에서 「전하고 싶은 마음을 잘 드러내려면 어떤 매체를 사용해서 편지를 써야 하나요?」라고 물었어요. 이 물음에 답할 때 생각할 점으로 가장 알맞은 것은 무엇인가요?',ARRAY['K6-2-u5-X03','K6-2-u5-X10','K6-2-u5-X37']::text[],false,'{"seq":8,"concept":"K6-2-u5-C24","difficulty":2,"kind":"mc","stem":"『국어』 248쪽에서 「전하고 싶은 마음을 잘 드러내려면 어떤 매체를 사용해서 편지를 써야 하나요?」라고 물었어요. 이 물음에 답할 때 생각할 점으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"전하고 싶은 마음과 받는 사람에게 알맞은 매체인지","correct":true},{"t":"가장 새로운 매체가 언제나 가장 좋은 매체인지","mis":"K6-2-u5-X03"},{"t":"보내기 가장 빠르고 편한 매체인지만","mis":"K6-2-u5-X10"},{"t":"예쁘게 꾸미기 가장 좋은 매체인지만","mis":"K6-2-u5-X37"}],"explanation":["매체에는 등수가 없어요.","전하고 싶은 마음과 받는 사람에게 알맞은지를 봐요.","손 편지는 오래 남고, 영상 편지는 목소리와 표정이 생생해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L12_basic#9','kor',6,2,'u5','L12','tb_g6_2_kor_u5_L12_basic','lesson_basic','K6-2-u5-C22',2,'ox','auto','편지를 받는 사람에 따라 글의 내용이나 표현이 달라져야 해요.',ARRAY['K6-2-u5-X34']::text[],false,'{"seq":9,"concept":"K6-2-u5-C22","difficulty":2,"kind":"ox","stem":"편지를 받는 사람에 따라 글의 내용이나 표현이 달라져야 해요.","answer":"O","reason_options":[{"t":"받는 사람에게 알맞게 존칭을 쓰고 쓴 목적이 뚜렷하게 드러나게 써야 하기 때문에","correct":true},{"t":"편지는 누구에게 쓰든 똑같은 말로 쓰면 되기 때문에","mis":"K6-2-u5-X34"}],"mis":"K6-2-u5-X34","explanation":["편지는 비교적 자유롭게 쓰지만 독자를 고려해야 해요.","받는 사람에게 알맞게 존칭을 써요.","편지를 쓴 목적이 뚜렷하게 드러나야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L12_basic#10','kor',6,2,'u5','L12','tb_g6_2_kor_u5_L12_basic','lesson_basic','K6-2-u5-C23',3,'mc','auto','어제 말다툼을 한 친구에게 사과 편지를 쓸 때 하고 싶은 말로 가장 알맞은 것은 무엇인가요?',ARRAY['K6-2-u5-X35','K6-2-u5-X44','K6-2-u5-X36']::text[],false,'{"seq":10,"concept":"K6-2-u5-C23","difficulty":3,"kind":"mc","stem":"어제 말다툼을 한 친구에게 사과 편지를 쓸 때 하고 싶은 말로 가장 알맞은 것은 무엇인가요?","options":[{"t":"내가 화를 내며 말해서 미안했다는 마음을 먼저 진심으로 전한다","correct":true},{"t":"네가 먼저 잘못했으니 다음부터 조심하라고 충고한다","mis":"K6-2-u5-X35"},{"t":"미안하다는 말 없이 다음 주 생일잔치에 오라고 초대한다","mis":"K6-2-u5-X44"},{"t":"「그냥 미안해」라고만 짧게 쓴다","mis":"K6-2-u5-X36"}],"explanation":["사과 편지의 목적은 미안한 마음을 전하는 것이에요.","무엇이 미안한지 먼저 진심으로 써요.","충고나 초대는 목적과 맞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L12_challenge#1','kor',6,2,'u5','L12','tb_g6_2_kor_u5_L12_challenge','lesson_challenge','K6-2-u5-C35',2,'sa','auto','편지 쓰기 활동의 예시인 「영상 편지 만들기」 차례예요. ① 전하고 싶은 마음을 편지지에 쓴다. → ② 촬영 도구를 준비한다. → ③ 편지지에 쓴 내용을 바탕으로 영상을 촬영한다. → ④ 촬영한 영상을 확인하고 (    )한다. → ⑤ 전하고 싶은 사람에게 전달한다. 빈칸에 알맞은 두 글자 낱말을 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K6-2-u5-C35","difficulty":2,"kind":"sa","stem":"편지 쓰기 활동의 예시인 「영상 편지 만들기」 차례예요. ① 전하고 싶은 마음을 편지지에 쓴다. → ② 촬영 도구를 준비한다. → ③ 편지지에 쓴 내용을 바탕으로 영상을 촬영한다. → ④ 촬영한 영상을 확인하고 (    )한다. → ⑤ 전하고 싶은 사람에게 전달한다. 빈칸에 알맞은 두 글자 낱말을 쓰세요.","answer":["편집"],"explanation":["영상을 찍은 뒤에는 확인하고 다듬어요.","촬영한 영상을 다듬는 일을 편집이라고 해요.","마지막에는 전하고 싶은 사람에게 꼭 전달해요."],"mis":"K6-2-u5-X37"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L12_challenge#2','kor',6,2,'u5','L12','tb_g6_2_kor_u5_L12_challenge','lesson_challenge','K6-2-u5-C25',2,'mc','auto','『국어』 253쪽 기초 다지기에서 「맑고」와 「읽고」의 발음을 바르게 짝 지은 것은 무엇인가요?',ARRAY['K6-2-u5-X39']::text[],false,'{"seq":2,"concept":"K6-2-u5-C25","difficulty":2,"kind":"mc","stem":"『국어』 253쪽 기초 다지기에서 「맑고」와 「읽고」의 발음을 바르게 짝 지은 것은 무엇인가요?","options":[{"t":"맑고[말꼬] · 읽고[일꼬]","correct":true},{"t":"맑고[막꼬] · 읽고[익꼬]","mis":"K6-2-u5-X39"},{"t":"맑고[말고] · 읽고[일고]","mis":"K6-2-u5-X39"},{"t":"맑고[말꼬] · 읽고[익꼬]","mis":"K6-2-u5-X39"}],"explanation":["겹받침 ㄺ은 보통 [ㄱ]으로 소리 나요.","하지만 ㄱ과 만나면 [ㄹ]로 발음되는 것도 있어요.","「맑고」는 [말꼬], 「읽고」는 [일꼬]예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L12_challenge#3','kor',6,2,'u5','L12','tb_g6_2_kor_u5_L12_challenge','lesson_challenge','K6-2-u5-C23',3,'mc','auto','감사 편지를 받은 사람이 마음이 잘 전해졌다고 느끼게 하려면 하고 싶은 말을 어떻게 쓰는 것이 가장 알맞은가요?',ARRAY['K6-2-u5-X36','K6-2-u5-X35','K6-2-u5-X37']::text[],false,'{"seq":3,"concept":"K6-2-u5-C23","difficulty":3,"kind":"mc","stem":"감사 편지를 받은 사람이 마음이 잘 전해졌다고 느끼게 하려면 하고 싶은 말을 어떻게 쓰는 것이 가장 알맞은가요?","options":[{"t":"무엇이 고마웠는지 그 일을 콕 집어 쓴다","correct":true},{"t":"「고마워」라고만 쓴다","mis":"K6-2-u5-X36"},{"t":"고마운 일 대신 충고를 쓴다","mis":"K6-2-u5-X35"},{"t":"편지지를 꾸미는 데 시간을 다 쓴다","mis":"K6-2-u5-X37"}],"explanation":["막연한 말은 마음이 잘 닿지 않아요.","무엇이 고마웠는지 그 일을 집어 써요.","전하려는 마음에 맞는 내용을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L12_challenge#4','kor',6,2,'u5','L12','tb_g6_2_kor_u5_L12_challenge','lesson_challenge','K6-2-u5-C22',3,'error','auto','친구들이 편지를 쓰는 방법을 이야기했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-2-u5-X34','K6-2-u5-X33']::text[],false,'{"seq":4,"concept":"K6-2-u5-C22","difficulty":3,"kind":"error","stem":"친구들이 편지를 쓰는 방법을 이야기했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"친구 2 — 「선생님께 쓰는 편지도 친구에게 쓰듯이 반말로 쓰면 돼.」","correct":true,"mis_target":"K6-2-u5-X34"},{"t":"친구 1 — 「편지를 쓴 목적이 뚜렷하게 드러나게 써야 해.」","mis":"K6-2-u5-X33"},{"t":"친구 3 — 「편지 끝에는 쓴 날짜와 보내는 사람을 써.」","mis":"K6-2-u5-X33"}],"explanation":["편지는 받는 사람에게 알맞게 존칭을 써야 해요.","선생님께는 높임말로 써요.","목적, 쓴 날짜, 보내는 사람은 편지에 꼭 필요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L12_challenge#5','kor',6,2,'u5','L12','tb_g6_2_kor_u5_L12_challenge','lesson_challenge','K6-2-u5-C24',3,'ox','auto','편지는 다 쓰고 나서 받는 사람에게 전달해 읽어 볼 수 있게 하고, 소감을 나누는 것까지 해 보는 것이 좋아요.',ARRAY['K6-2-u5-X37']::text[],false,'{"seq":5,"concept":"K6-2-u5-C24","difficulty":3,"kind":"ox","stem":"편지는 다 쓰고 나서 받는 사람에게 전달해 읽어 볼 수 있게 하고, 소감을 나누는 것까지 해 보는 것이 좋아요.","answer":"O","reason_options":[{"t":"마음을 전하는 편지는 받는 사람에게 건네져 읽혀야 실천이 이루어지기 때문에","correct":true},{"t":"편지는 예쁘게 꾸며 서랍에 넣어 두기만 하면 되기 때문에","mis":"K6-2-u5-X37"}],"mis":"K6-2-u5-X37","explanation":["친구에게 쓴 편지를 전달해 읽어 볼 수 있게 해요.","편지를 읽은 친구는 소감을 이야기해요.","서로 긍정적인 반응을 주고받아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L12_challenge#6','kor',6,2,'u5','L12','tb_g6_2_kor_u5_L12_challenge','lesson_challenge','K6-2-u5-C22',3,'mc','auto','편지 예시 「그리운 친구 민석이에게」에서 「민석아, 전학 간 학교에서는 잘 지내고 있니?」는 편지의 어느 부분인가요?',ARRAY['K6-2-u5-X33']::text[],false,'{"seq":6,"concept":"K6-2-u5-C22","difficulty":3,"kind":"mc","stem":"편지 예시 「그리운 친구 민석이에게」에서 「민석아, 전학 간 학교에서는 잘 지내고 있니?」는 편지의 어느 부분인가요?","options":[{"t":"첫인사","correct":true},{"t":"끝인사","mis":"K6-2-u5-X33"},{"t":"보내는 사람","mis":"K6-2-u5-X33"},{"t":"쓴 날짜","mis":"K6-2-u5-X33"}],"explanation":["받는 사람을 쓴 뒤 안부를 묻는 부분이에요.","이 부분을 첫인사라고 해요.","끝인사는 「즐겁고 행복하게 잘 지내고 다시 만나자.」예요."],"asset":{"type":"passage","lines":["[받는 사람] 그리운 친구 민석이에게","[첫인사] 민석아, 전학 간 학교에서는 잘 지내고 있니?","[하고 싶은 말] (간추림) 학급 어린이 회장이 되어 책임감 있게 생활하려고 노력한다.","[하고 싶은 말] (간추림) 연말에 지난해 우리 반 친구들과 함께 만나자.","[끝인사] 즐겁고 행복하게 잘 지내고 다시 만나자.","[쓴 날짜] ○○○○년 ○○월 ○○일","[보내는 사람] 친구 현수가"],"numbered":false,"title":"편지 예시 「그리운 친구 민석이에게」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L12_challenge#7','kor',6,2,'u5','L12','tb_g6_2_kor_u5_L12_challenge','lesson_challenge','K6-2-u5-C25',3,'match','auto','『국어』 253쪽 기초 다지기의 낱말과 바른 발음을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K6-2-u5-C25","difficulty":3,"kind":"match","stem":"『국어』 253쪽 기초 다지기의 낱말과 바른 발음을 알맞게 이으세요.","pairs":[{"l":"넓다","r":"[널따]"},{"l":"넓어요","r":"[널버요]"},{"l":"밟다","r":"[밥ː따]"},{"l":"밟아요","r":"[발바요]"}],"mis":"K6-2-u5-X39","explanation":["겹받침 ㄼ은 자음자와 만나면 [ㄹ]로 소리 나요.","「밟-」은 예외로 [ㅂ]으로 발음해요.","뒤에 모음이 오면 뒤엣것이 뒤 글자로 넘어가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L12_challenge#8','kor',6,2,'u5','L12','tb_g6_2_kor_u5_L12_challenge','lesson_challenge','K6-2-u5-C23',4,'essay','teacher','『국어』 248쪽 「전하고 싶은 말 정리하기」처럼 마음을 전하고 싶은 사람을 한 명 떠올려 그 사람과 까닭, 고려할 점을 쓰고, 전하고 싶은 마음에 맞는 하고 싶은 말을 두세 문장으로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K6-2-u5-C23","difficulty":4,"kind":"essay","stem":"『국어』 248쪽 「전하고 싶은 말 정리하기」처럼 마음을 전하고 싶은 사람을 한 명 떠올려 그 사람과 까닭, 고려할 점을 쓰고, 전하고 싶은 마음에 맞는 하고 싶은 말을 두세 문장으로 쓰세요.","answer_guide":{"answer":"예: 마음을 전하고 싶은 사람은 전학 간 친구이다. 오랫동안 소식을 전하지 못해 안부를 묻고 싶기 때문이다. 친구가 우리 반 소식을 궁금해할 것이니 요즘 있었던 일을 자세히 쓰겠다. 하고 싶은 말 — 전학 간 학교에서 잘 지내고 있니? 나는 학급 어린이 회장이 되어 책임감 있게 생활하려고 노력하고 있어. 시간이 되면 꼭 다시 만나자.","scoring_points":["대상과 까닭을 썼는가","독자의 관심이나 궁금한 점을 고려할 점으로 썼는가","전하고 싶은 마음에 맞는 하고 싶은 말을 썼는가"]},"explanation":["대상, 까닭, 고려할 점을 먼저 정리해요.","독자가 궁금해할 것을 생각해요.","그 마음에 맞는 말을 골라 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L12_challenge#9','kor',6,2,'u5','L12','tb_g6_2_kor_u5_L12_challenge','lesson_challenge','K6-2-u5-C24',4,'essay','teacher','마음을 전하는 편지를 손 편지와 영상 편지 가운데 하나로 쓴다고 할 때, 하나를 골라 그 매체를 고른 까닭을 이 단원에서 배운 문자 언어나 음성 언어의 특성과 이어 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-2-u5-C24","difficulty":4,"kind":"essay","stem":"마음을 전하는 편지를 손 편지와 영상 편지 가운데 하나로 쓴다고 할 때, 하나를 골라 그 매체를 고른 까닭을 이 단원에서 배운 문자 언어나 음성 언어의 특성과 이어 쓰세요.","answer_guide":{"answer":"예: 멀리 계신 할머니께 영상 편지를 보내겠다. 영상 편지는 음성 언어로 목소리와 표정을 생생하게 전할 수 있어서 반가운 마음을 더 잘 전할 수 있기 때문이다.","scoring_points":["매체 하나를 골랐는가","고른 까닭을 문자 언어나 음성 언어의 특성과 이었는가","받는 사람과 전하려는 마음을 함께 생각했는가"]},"explanation":["손 편지는 글로 남아 오래 간직할 수 있어요.","영상 편지는 목소리와 표정이 생생해요.","마음과 받는 사람에게 맞는 매체를 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_L12_challenge#10','kor',6,2,'u5','L12','tb_g6_2_kor_u5_L12_challenge','lesson_challenge','K6-2-u5-C25',4,'essay','teacher','『국어』 253쪽 기초 다지기를 보고, 「읽다」와 「읽어요」의 발음이 다른 까닭을 겹받침 뒤에 오는 소리와 이어 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-2-u5-C25","difficulty":4,"kind":"essay","stem":"『국어』 253쪽 기초 다지기를 보고, 「읽다」와 「읽어요」의 발음이 다른 까닭을 겹받침 뒤에 오는 소리와 이어 쓰세요.","answer_guide":{"answer":"예: 「읽다」는 겹받침 ㄺ 뒤에 자음자 ㄷ이 와서 받침 ㄱ만 소리 나 [익따]로 발음한다. 「읽어요」는 뒤에 모음이 와서 ㄹ은 받침으로 소리 나고 ㄱ은 뒤 글자의 첫소리로 넘어가 [일거요]로 발음한다.","scoring_points":["「읽다」의 발음과 까닭(뒤에 자음자)을 썼는가","「읽어요」의 발음과 까닭(뒤에 모음)을 썼는가","겹받침이 소리 나는 규칙으로 정리했는가"]},"explanation":["뒤에 자음자가 오면 겹받침 가운데 하나만 소리 나요.","뒤에 모음이 오면 두 소리가 다 나요.","뒤엣것이 뒤 글자로 넘어가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_review_a#1','kor',6,2,'u5','','tb_g6_2_kor_u5_review_a','unit_review','K6-2-u5-C1',1,'mc','auto','『국어』 223쪽에서 정리한 문자 언어와 음성 언어의 뜻으로 알맞은 것은 무엇인가요?',ARRAY['K6-2-u5-X01','K6-2-u5-X03']::text[],false,'{"seq":1,"concept":"K6-2-u5-C1","difficulty":1,"kind":"mc","stem":"『국어』 223쪽에서 정리한 문자 언어와 음성 언어의 뜻으로 알맞은 것은 무엇인가요?","options":[{"t":"문자 언어는 글자로 나타내는 말이고, 음성 언어는 음성으로 나타내는 말이다","correct":true},{"t":"문자 언어는 음성으로 나타내는 말이고, 음성 언어는 글자로 나타내는 말이다","mis":"K6-2-u5-X01"},{"t":"문자 언어는 그림으로 나타내는 말이다","mis":"K6-2-u5-X01"},{"t":"음성 언어가 문자 언어보다 언제나 더 좋은 말이다","mis":"K6-2-u5-X03"}],"explanation":["문자 언어는 글자로 나타내는 말이에요.","음성 언어는 음성으로 나타내는 말이에요.","두 언어는 알맞은 쓰임이 다를 뿐 등수가 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_review_a#2','kor',6,2,'u5','','tb_g6_2_kor_u5_review_a','unit_review','K6-2-u5-C1',1,'mc','auto','『국어』 250쪽 그림 ㉮에서 두 친구는 어떻게 의사소통하고 있나요?',ARRAY['K6-2-u5-X01','K6-2-u5-X05']::text[],false,'{"seq":2,"concept":"K6-2-u5-C1","difficulty":1,"kind":"mc","stem":"『국어』 250쪽 그림 ㉮에서 두 친구는 어떻게 의사소통하고 있나요?","options":[{"t":"직접 만나서 음성 언어로 의사소통한다","correct":true},{"t":"글을 써서 문자 언어로 의사소통한다","mis":"K6-2-u5-X01"},{"t":"그림만 그려서 의사소통한다","mis":"K6-2-u5-X05"}],"explanation":["그림 ㉮의 두 친구는 마주 보고 이야기를 나눠요.","직접 만나서 음성 언어로 의사소통해요.","음성 언어는 주로 직접 만나서 대화할 때 써요."],"asset":{"type":"passage","lines":["㉮ [그림] 두 친구가 직접 만나서 이야기를 나눈다.","㉯ [그림] 한 친구가 책상에 앉아 글을 쓰고 있다."],"numbered":false,"title":"『국어』 250쪽 1번"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_review_a#3','kor',6,2,'u5','','tb_g6_2_kor_u5_review_a','unit_review','K6-2-u5-C3',1,'blank','auto','『국어』 230쪽 4번이에요. 「인쇄 매체는 (    ) 언어를 기반으로 표, 그림, 사진 같은 자료를 함께 사용하면서 정보를 전달하는 매체이다.」 빈칸에 알맞은 낱말은 무엇인가요?',ARRAY['K6-2-u5-X04']::text[],false,'{"seq":3,"concept":"K6-2-u5-C3","difficulty":1,"kind":"blank","stem":"『국어』 230쪽 4번이에요. 「인쇄 매체는 (    ) 언어를 기반으로 표, 그림, 사진 같은 자료를 함께 사용하면서 정보를 전달하는 매체이다.」 빈칸에 알맞은 낱말은 무엇인가요?","options":[{"t":"문자","correct":true},{"t":"음성","mis":"K6-2-u5-X04"},{"t":"음악","mis":"K6-2-u5-X04"},{"t":"텔레비전","mis":"K6-2-u5-X04"}],"explanation":["인쇄 매체에는 책, 신문이 있어요.","글자로 된 문자 언어가 바탕이에요.","표, 그림, 사진을 함께 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_review_a#4','kor',6,2,'u5','','tb_g6_2_kor_u5_review_a','unit_review','K6-2-u5-C4',1,'mc','auto','문자 언어의 특성으로 알맞은 것은 무엇인가요?',ARRAY['K6-2-u5-X01','K6-2-u5-X06','K6-2-u5-X07']::text[],false,'{"seq":4,"concept":"K6-2-u5-C4","difficulty":1,"kind":"mc","stem":"문자 언어의 특성으로 알맞은 것은 무엇인가요?","options":[{"t":"쓰인 내용을 나중에 다시 볼 수 있다","correct":true},{"t":"말이 끝나면서 소리가 사라진다","mis":"K6-2-u5-X01"},{"t":"목소리의 크기나 억양으로 감정을 전한다","mis":"K6-2-u5-X06"},{"t":"쓰고 나면 절대 고칠 수 없다","mis":"K6-2-u5-X07"}],"explanation":["글자로 쓰인 내용은 남아 있어요.","그래서 나중에 다시 볼 수 있어요.","소리가 사라지는 것은 음성 언어의 특성이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_review_a#5','kor',6,2,'u5','','tb_g6_2_kor_u5_review_a','unit_review','K6-2-u5-C5',1,'mc','auto','음성 언어의 특성으로 알맞은 것은 무엇인가요?',ARRAY['K6-2-u5-X01','K6-2-u5-X06','K6-2-u5-X02']::text[],false,'{"seq":5,"concept":"K6-2-u5-C5","difficulty":1,"kind":"mc","stem":"음성 언어의 특성으로 알맞은 것은 무엇인가요?","options":[{"t":"목소리의 크기나 억양으로 감정과 의도를 전달할 수 있다","correct":true},{"t":"기록한 내용이 오랫동안 보존된다","mis":"K6-2-u5-X01"},{"t":"글자의 굵기를 바꾸어 강조한다","mis":"K6-2-u5-X06"},{"t":"한 번 들으면 언제든 다시 들을 수 있다","mis":"K6-2-u5-X02"}],"explanation":["음성 언어는 목소리로 전해요.","목소리의 크기나 억양으로 감정과 의도를 전해요.","보존과 글자 굵기는 문자 언어의 특성이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_review_a#6','kor',6,2,'u5','','tb_g6_2_kor_u5_review_a','unit_review','K6-2-u5-C19',1,'mc','auto','기사문에서 「기사에서 본문 앞에 놓이는 요약 부분」을 무엇이라고 하나요?',ARRAY['K6-2-u5-X28']::text[],false,'{"seq":6,"concept":"K6-2-u5-C19","difficulty":1,"kind":"mc","stem":"기사문에서 「기사에서 본문 앞에 놓이는 요약 부분」을 무엇이라고 하나요?","options":[{"t":"전문","correct":true},{"t":"표제","mis":"K6-2-u5-X28"},{"t":"부제","mis":"K6-2-u5-X28"},{"t":"본문","mis":"K6-2-u5-X28"}],"explanation":["기사문은 제목, 전문, 본문으로 이루어져요.","본문 앞의 요약 부분은 전문이에요.","전문만 읽어도 기사 내용을 알 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_review_a#7','kor',6,2,'u5','','tb_g6_2_kor_u5_review_a','unit_review','K6-2-u5-C14',1,'blank','auto','『국어』 241쪽 7번이에요. 「독자의 관심과 흥미를 끌 수 있는 (    )와 내용을 정한다.」 빈칸에 알맞은 낱말은 무엇인가요?',ARRAY['K6-2-u5-X19','K6-2-u5-X22']::text[],false,'{"seq":7,"concept":"K6-2-u5-C14","difficulty":1,"kind":"blank","stem":"『국어』 241쪽 7번이에요. 「독자의 관심과 흥미를 끌 수 있는 (    )와 내용을 정한다.」 빈칸에 알맞은 낱말은 무엇인가요?","options":[{"t":"주제","correct":true},{"t":"흥미","mis":"K6-2-u5-X19"},{"t":"이해","mis":"K6-2-u5-X19"},{"t":"글씨","mis":"K6-2-u5-X22"}],"explanation":["보기는 주제, 흥미, 이해예요.","독자의 관심과 흥미를 끌 주제와 내용을 정해요.","흥미와 이해는 다른 빈칸에 들어가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_review_a#8','kor',6,2,'u5','','tb_g6_2_kor_u5_review_a','unit_review','K6-2-u5-C25',1,'mc','auto','「읽어요」의 바른 발음은 무엇인가요?',ARRAY['K6-2-u5-X38','K6-2-u5-X39']::text[],false,'{"seq":8,"concept":"K6-2-u5-C25","difficulty":1,"kind":"mc","stem":"「읽어요」의 바른 발음은 무엇인가요?","options":[{"t":"[일거요]","correct":true},{"t":"[익어요]","mis":"K6-2-u5-X38"},{"t":"[이거요]","mis":"K6-2-u5-X39"},{"t":"[익꺼요]","mis":"K6-2-u5-X38"}],"explanation":["겹받침 ㄺ 뒤에 모음이 와요.","ㄹ은 받침으로, ㄱ은 뒤 글자로 넘어가요.","그래서 [일거요]로 발음해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_review_a#9','kor',6,2,'u5','','tb_g6_2_kor_u5_review_a','unit_review','K6-2-u5-C29',2,'mc','auto','「아동 안전 ― 운전자가 보호자 ―」 장면 ㉡에서 「스쿨 존에서는 속도를 줄이고」를 자막으로 보여 준 까닭으로 알맞은 것은 무엇인가요?',ARRAY['K6-2-u5-X05','K6-2-u5-X13','K6-2-u5-X12']::text[],false,'{"seq":9,"concept":"K6-2-u5-C29","difficulty":2,"kind":"mc","stem":"「아동 안전 ― 운전자가 보호자 ―」 장면 ㉡에서 「스쿨 존에서는 속도를 줄이고」를 자막으로 보여 준 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"어린이 보호 구역에서는 속도를 줄여야 한다는 중요한 내용을 눈으로 확인하게 하려고","correct":true},{"t":"글자를 넣어 화면을 화려하고 보기 좋게 꾸미려고","mis":"K6-2-u5-X05"},{"t":"해설하는 목소리를 대신해 영상의 모든 말을 글자로 적으려고","mis":"K6-2-u5-X13"},{"t":"표지판이 알려 주는 것과 다른 새로운 내용을 알리려고","mis":"K6-2-u5-X12"}],"explanation":["장면 ㉡은 어린이 보호 구역 표지판과 자막을 보여 줘요.","중요한 내용을 글자로 보여 주면 또렷하게 기억돼요.","자막은 꾸밈이 아니라 내용을 전하는 방법이에요."],"asset":{"type":"passage","lines":["㉠ [음성 언어] 「도로에서는 운전자가 보호자입니다.」라고 설명한다.","㉠ [문자 언어] 「운전면허는 보행자 보호 면허」라는 글자를 운전면허증처럼 도로 위에","㉡ 어린이 보호 구역 표지판과 「스쿨 존에서는 속도를 줄이고」라는 자막","㉢ [음성 언어] 「지켜 주셔서 고맙습니다.」라는 아이의 말과 안전하게 길을 건너는 장면"],"numbered":false,"title":"「아동 안전 ― 운전자가 보호자 ―」(『국어』 229쪽 장면 설명)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_review_a#10','kor',6,2,'u5','','tb_g6_2_kor_u5_review_a','unit_review','K6-2-u5-C11',2,'mc','auto','「수월봉 화산 쇄설층」 장면 2에서 해설자의 말을 화면에 문자로 다시 보여 준 효과로 알맞은 것은 무엇인가요?',ARRAY['K6-2-u5-X11','K6-2-u5-X13','K6-2-u5-X12']::text[],false,'{"seq":10,"concept":"K6-2-u5-C11","difficulty":2,"kind":"mc","stem":"「수월봉 화산 쇄설층」 장면 2에서 해설자의 말을 화면에 문자로 다시 보여 준 효과로 알맞은 것은 무엇인가요?","options":[{"t":"설명하는 사람의 음성 언어를 자막으로도 보여 주어 쉽게 이해할 수 있게 한다","correct":true},{"t":"같은 말이 말과 글로 겹쳐 나와 오히려 헷갈리게 한다","mis":"K6-2-u5-X11"},{"t":"화면을 글자로 가득 채울수록 좋은 영상이 되게 한다","mis":"K6-2-u5-X13"},{"t":"해설자의 목소리를 숨기고 글자만 보게 한다","mis":"K6-2-u5-X12"}],"explanation":["『국어』 233쪽 (1)에서 이 장면을 정리했어요.","음성 언어를 자막이라는 문자 언어로도 보여 줘요.","두 언어가 함께 이해를 도와요."],"asset":{"type":"passage","lines":["장면 1 잔잔한 파도 소리와 음악이 들리며 제목이 나타난다.","장면 2 해안 절벽을 다양한 각도로 보여 주고, 해설자의 말을 화면에 문자로 다시 보여 준다.","장면 3 새로운 탄생과 발견을 강조하려고 긴장감이 느껴지는 음악을 사용한다.","장면 4 분화구 추정 위치와 주변 지역을 글과 그림으로 표현한다.","장면 5 대상의 이름과 설명을 해설자의 음성 설명 없이 자막으로 보여 준다."],"numbered":false,"title":"「수월봉 화산 쇄설층」(『국어』 231쪽 장면 설명)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_review_a#11','kor',6,2,'u5','','tb_g6_2_kor_u5_review_a','unit_review','K6-2-u5-C6',2,'mc','auto','약속 시간을 친구들에게 정확하게 전해야 할 때 알맞은 언어와 까닭을 바르게 짝 지은 것은 무엇인가요?',ARRAY['K6-2-u5-X09','K6-2-u5-X06','K6-2-u5-X10']::text[],false,'{"seq":11,"concept":"K6-2-u5-C6","difficulty":2,"kind":"mc","stem":"약속 시간을 친구들에게 정확하게 전해야 할 때 알맞은 언어와 까닭을 바르게 짝 지은 것은 무엇인가요?","options":[{"t":"문자 언어 — 기록으로 남아 필요할 때 다시 확인할 수 있어서","correct":true},{"t":"음성 언어 — 말이 끝나면 사라져서","mis":"K6-2-u5-X09"},{"t":"문자 언어 — 목소리에 감정을 담을 수 있어서","mis":"K6-2-u5-X06"},{"t":"아무 언어나 — 상황과 상관없어서","mis":"K6-2-u5-X10"}],"explanation":["약속 시간은 정확하게 남아야 해요.","문자 언어는 기록으로 남아 다시 확인할 수 있어요.","고른 언어와 그 특성을 이어 까닭을 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_review_a#12','kor',6,2,'u5','','tb_g6_2_kor_u5_review_a','unit_review','K6-2-u5-C18',2,'blank','auto','『국어』 251쪽 2번이에요. 「기사문을 쓸 때에는 읽는 사람인 ( ㄱ )의 관심을 끌 만한 내용인지 살펴봐야 해요.」 ㄱ에 알맞은 낱말은 무엇인가요?',ARRAY['K6-2-u5-X43','K6-2-u5-X32']::text[],false,'{"seq":12,"concept":"K6-2-u5-C18","difficulty":2,"kind":"blank","stem":"『국어』 251쪽 2번이에요. 「기사문을 쓸 때에는 읽는 사람인 ( ㄱ )의 관심을 끌 만한 내용인지 살펴봐야 해요.」 ㄱ에 알맞은 낱말은 무엇인가요?","options":[{"t":"독자","correct":true},{"t":"기자","mis":"K6-2-u5-X43"},{"t":"출처","mis":"K6-2-u5-X32"}],"explanation":["기사문을 읽는 사람은 독자예요.","독자의 관심을 끌 만한 내용인지 살펴봐요.","보기는 관심, 독자, 사실이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_review_a#13','kor',6,2,'u5','','tb_g6_2_kor_u5_review_a','unit_review','K6-2-u5-C33',2,'mc','auto','「계단을 안전하게 이용합시다」의 독자는 누구인가요?',ARRAY['K6-2-u5-X43']::text[],false,'{"seq":13,"concept":"K6-2-u5-C33","difficulty":2,"kind":"mc","stem":"「계단을 안전하게 이용합시다」의 독자는 누구인가요?","options":[{"t":"○○초등학교 학생들","correct":true},{"t":"계단을 만드는 사람들","mis":"K6-2-u5-X43"},{"t":"다른 나라 사람들","mis":"K6-2-u5-X43"},{"t":"글을 쓴 전교 어린이회 학생들만","mis":"K6-2-u5-X43"}],"explanation":["계획하기에서 「읽는 사람: 우리 ○○초등학교 학생들」이라고 정했어요.","글에도 「○○초등학교 학생들은 다음의 내용을 꼭 기억해 주세요」가 나와요.","독자를 정해야 그에 맞게 쓸 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_review_a#14','kor',6,2,'u5','','tb_g6_2_kor_u5_review_a','unit_review','K6-2-u5-C34',2,'mc','auto','「희망초등학교, ‘전문가와 함께 하는 예술 진로 캠프’ 개최」에서 5~6학년 학생들이 실과 실습실에서 한 체험은 무엇인가요?',ARRAY['K6-2-u5-X29','K6-2-u5-X27']::text[],false,'{"seq":14,"concept":"K6-2-u5-C34","difficulty":2,"kind":"mc","stem":"「희망초등학교, ‘전문가와 함께 하는 예술 진로 캠프’ 개최」에서 5~6학년 학생들이 실과 실습실에서 한 체험은 무엇인가요?","options":[{"t":"특수 분장 체험","correct":true},{"t":"그림 작가 체험","mis":"K6-2-u5-X29"},{"t":"성우가 하는 일 익히기","mis":"K6-2-u5-X29"},{"t":"요리사 체험","mis":"K6-2-u5-X27"}],"explanation":["11월 9일에 5~6학년 학생들이 실과 실습실에 모였어요.","특수 분장사 선생님께 배우고 직접 특수 분장을 해 보았어요.","그림 작가는 1~2학년, 성우는 3~4학년의 체험이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_review_a#15','kor',6,2,'u5','','tb_g6_2_kor_u5_review_a','unit_review','K6-2-u5-C22',2,'mc','auto','편지 예시 「그리운 친구 민석이에게」에서 「친구 현수가」는 편지의 어느 부분인가요?',ARRAY['K6-2-u5-X33']::text[],false,'{"seq":15,"concept":"K6-2-u5-C22","difficulty":2,"kind":"mc","stem":"편지 예시 「그리운 친구 민석이에게」에서 「친구 현수가」는 편지의 어느 부분인가요?","options":[{"t":"보내는 사람","correct":true},{"t":"받는 사람","mis":"K6-2-u5-X33"},{"t":"첫인사","mis":"K6-2-u5-X33"},{"t":"하고 싶은 말","mis":"K6-2-u5-X33"}],"explanation":["편지 끝에는 쓴 날짜와 보내는 사람을 써요.","「친구 현수가」는 보내는 사람이에요.","받는 사람은 「그리운 친구 민석이에게」예요."],"asset":{"type":"passage","lines":["[받는 사람] 그리운 친구 민석이에게","[첫인사] 민석아, 전학 간 학교에서는 잘 지내고 있니?","[하고 싶은 말] (간추림) 학급 어린이 회장이 되어 책임감 있게 생활하려고 노력한다.","[하고 싶은 말] (간추림) 연말에 지난해 우리 반 친구들과 함께 만나자.","[끝인사] 즐겁고 행복하게 잘 지내고 다시 만나자.","[쓴 날짜] ○○○○년 ○○월 ○○일","[보내는 사람] 친구 현수가"],"numbered":false,"title":"편지 예시 「그리운 친구 민석이에게」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_review_a#16','kor',6,2,'u5','','tb_g6_2_kor_u5_review_a','unit_review','K6-2-u5-C7',2,'mc','auto','『국어』 252쪽 스스로 확인하기에서 「언어의 표현 효과」 칸에 들어갈 설명으로 알맞은 것은 무엇인가요?',ARRAY['K6-2-u5-X02','K6-2-u5-X03','K6-2-u5-X13']::text[],false,'{"seq":16,"concept":"K6-2-u5-C7","difficulty":2,"kind":"mc","stem":"『국어』 252쪽 스스로 확인하기에서 「언어의 표현 효과」 칸에 들어갈 설명으로 알맞은 것은 무엇인가요?","options":[{"t":"음성 언어는 내용을 생생하게, 문자 언어는 시각적으로 쉽게 이해하게 한다","correct":true},{"t":"음성 언어는 오랫동안 보존되고, 문자 언어는 말이 끝나면 사라진다","mis":"K6-2-u5-X02"},{"t":"두 언어 가운데 문자 언어만 표현 효과가 있고 음성 언어는 없다","mis":"K6-2-u5-X03"},{"t":"두 언어를 될 수 있는 대로 많이 쓸수록 표현 효과가 커진다","mis":"K6-2-u5-X13"}],"explanation":["음성 언어는 내용을 생생하게 전해요.","문자 언어는 눈으로 보며 쉽게 이해하게 해요.","두 언어 모두 저마다 표현 효과가 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_review_a#17','kor',6,2,'u5','','tb_g6_2_kor_u5_review_a','unit_review','K6-2-u5-C1',3,'mc','auto','문자 언어와 음성 언어의 같은 점으로 가장 알맞은 것은 무엇인가요?',ARRAY['K6-2-u5-X02','K6-2-u5-X06']::text[],false,'{"seq":17,"concept":"K6-2-u5-C1","difficulty":3,"kind":"mc","stem":"문자 언어와 음성 언어의 같은 점으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"둘 다 생각이나 정보를 다른 사람에게 전하는 데 쓰인다","correct":true},{"t":"둘 다 쓰고 나면 오랫동안 보존된다","mis":"K6-2-u5-X02"},{"t":"둘 다 목소리의 크기나 억양으로 감정을 전한다","mis":"K6-2-u5-X06"},{"t":"둘 다 말이 끝나면 사라진다","mis":"K6-2-u5-X02"}],"explanation":["『국어』 219쪽은 「다른 방법으로 생각을 전하고」 있다고 했어요.","두 언어 모두 생각과 정보를 전하는 수단이에요.","보존되는지, 사라지는지는 다른 점이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_review_a#18','kor',6,2,'u5','','tb_g6_2_kor_u5_review_a','unit_review','K6-2-u5-C29',3,'mc','auto','공익 광고를 찾아 제목, 주제, 언어의 표현 방법, 언어의 표현 효과를 정리하려고 해요. 「아동 안전 ― 운전자가 보호자 ―」의 「언어의 표현 효과」 칸에 쓸 말로 가장 알맞은 것은 무엇인가요?',ARRAY['K6-2-u5-X12']::text[],false,'{"seq":18,"concept":"K6-2-u5-C29","difficulty":3,"kind":"mc","stem":"공익 광고를 찾아 제목, 주제, 언어의 표현 방법, 언어의 표현 효과를 정리하려고 해요. 「아동 안전 ― 운전자가 보호자 ―」의 「언어의 표현 효과」 칸에 쓸 말로 가장 알맞은 것은 무엇인가요?","options":[{"t":"말로 설명한 내용을 자막으로 정리하고 강조해 어린이 보호의 중요성을 또렷하게 전한다","correct":true},{"t":"동영상, 대사, 자막, 음악 등으로 정보를 전달한다","mis":"K6-2-u5-X12"},{"t":"아동의 안전을 위해 운전하는 사람이 차량 안전을 생각해야 한다","mis":"K6-2-u5-X12"},{"t":"공공의 이익을 위해 여러 사람에게 알리려고 만들었다","mis":"K6-2-u5-X12"}],"explanation":["표현 효과는 표현이 내용 전달을 어떻게 돕는지예요.","「동영상, 대사, 자막, 음악」은 표현 방법 칸에 써요.","주제와 만든 까닭은 다른 칸이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_review_a#19','kor',6,2,'u5','','tb_g6_2_kor_u5_review_a','unit_review','K6-2-u5-C15',3,'mc','auto','공룡에 관심이 많은 친구들에게 공룡 이야기를 쓸 때, 독자를 고려한 방법으로 가장 알맞은 것은 무엇인가요?',ARRAY['K6-2-u5-X20','K6-2-u5-X43','K6-2-u5-X23']::text[],false,'{"seq":19,"concept":"K6-2-u5-C15","difficulty":3,"kind":"mc","stem":"공룡에 관심이 많은 친구들에게 공룡 이야기를 쓸 때, 독자를 고려한 방법으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"「초식 공룡」처럼 어려운 말은 뜻을 풀어 주면서 전하려는 내용은 빠뜨리지 않는다","correct":true},{"t":"어려운 내용은 모두 빼고 재미있고 신나는 말만 골라 쓴다","mis":"K6-2-u5-X20"},{"t":"내가 조사한 내용을 어려운 낱말 그대로 길게 쓴다","mis":"K6-2-u5-X43"},{"t":"공룡 그림을 될 수 있는 대로 많이 넣고 글은 쓰지 않는다","mis":"K6-2-u5-X23"}],"explanation":["독자를 고려한다고 전할 내용을 빼는 것은 아니에요.","독자가 알아들을 수 있게 풀어 써요.","전하려는 것은 그대로, 전하는 방법을 바꿔요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_review_a#20','kor',6,2,'u5','','tb_g6_2_kor_u5_review_a','unit_review','K6-2-u5-C20',3,'mc','auto','『국어』 246쪽 예시 기사문에서 쓴 사람의 바람이 드러난 문장은 무엇인가요?',ARRAY['K6-2-u5-X26']::text[],false,'{"seq":20,"concept":"K6-2-u5-C20","difficulty":3,"kind":"mc","stem":"『국어』 246쪽 예시 기사문에서 쓴 사람의 바람이 드러난 문장은 무엇인가요?","options":[{"t":"「오늘부터 우리 학교 학생들이 앞장서서 ‘에너지 수호천사’가 되기를 기대해 본다.」","correct":true},{"t":"「지난 1일부터 3일까지 점심시간에 어린이 기자단이 교실들을 둘러보았다.」","mis":"K6-2-u5-X26"},{"t":"「설문 조사에서 ‘전등 끄기’가 가장 좋은 방법으로 꼽혔다.」","mis":"K6-2-u5-X26"}],"explanation":["「기대해 본다」는 쓴 사람의 바람이에요.","교실을 둘러본 일과 설문 조사 결과는 확인한 사실이에요.","사실과 생각을 갈라 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_review_a#21','kor',6,2,'u5','','tb_g6_2_kor_u5_review_a','unit_review','K6-2-u5-C12',3,'mc','auto','『국어』 235쪽 (1)에서 「음성 언어의 설명에서 빠진 부분을 문자 언어로 표시해 주어서 정확하게 알 수 있었어.」라고 말한 친구가 이야기한 것은 무엇인가요?',ARRAY['K6-2-u5-X15','K6-2-u5-X05','K6-2-u5-X13']::text[],false,'{"seq":21,"concept":"K6-2-u5-C12","difficulty":3,"kind":"mc","stem":"『국어』 235쪽 (1)에서 「음성 언어의 설명에서 빠진 부분을 문자 언어로 표시해 주어서 정확하게 알 수 있었어.」라고 말한 친구가 이야기한 것은 무엇인가요?","options":[{"t":"문자 언어가 음성 언어를 보완하는 표현 효과","correct":true},{"t":"영상이 재미있었다는 자신의 느낌만","mis":"K6-2-u5-X15"},{"t":"영상의 길이와 올린 날짜","mis":"K6-2-u5-X05"},{"t":"자막이 많을수록 좋은 영상이라는 생각","mis":"K6-2-u5-X13"}],"explanation":["친구는 음성 언어에서 빠진 부분을 문자 언어가 채웠다고 했어요.","두 언어가 서로 보완하는 표현 효과예요.","그래서 내용을 정확하게 알 수 있었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_review_a#22','kor',6,2,'u5','','tb_g6_2_kor_u5_review_a','unit_review','K6-2-u5-C21',3,'mc','auto','학교 신문에 실을 기사문 계획을 세울 때 「독자의 특성」 칸에 쓸 내용으로 알맞은 것은 무엇인가요?',ARRAY['K6-2-u5-X30','K6-2-u5-X32','K6-2-u5-X23']::text[],false,'{"seq":22,"concept":"K6-2-u5-C21","difficulty":3,"kind":"mc","stem":"학교 신문에 실을 기사문 계획을 세울 때 「독자의 특성」 칸에 쓸 내용으로 알맞은 것은 무엇인가요?","options":[{"t":"초등학생이므로 실천할 수 있는 내용에 관심이 많다","correct":true},{"t":"에너지 절약 생활화","mis":"K6-2-u5-X30"},{"t":"학생을 대상으로 설문 조사를 실시한다","mis":"K6-2-u5-X32"},{"t":"학생의 생각을 나타내는 자료","mis":"K6-2-u5-X23"}],"explanation":["독자의 특성은 독자가 어떤 사람이고 무엇에 관심이 있는지예요.","「에너지 절약 생활화」는 기삿거리 칸에 써요.","설문 조사는 자료 수집 방법, 학생의 생각은 필요한 자료예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_review_a#23','kor',6,2,'u5','','tb_g6_2_kor_u5_review_a','unit_review','K6-2-u5-C1',4,'essay','teacher','문자 언어와 음성 언어의 같은 점을 한 가지, 다른 점을 두 가지 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K6-2-u5-C1","difficulty":4,"kind":"essay","stem":"문자 언어와 음성 언어의 같은 점을 한 가지, 다른 점을 두 가지 쓰세요.","answer_guide":{"answer":"예: 같은 점 — 둘 다 생각이나 정보를 다른 사람에게 전한다. 다른 점 — 문자 언어는 글자로 나타내고 음성 언어는 음성으로 나타낸다. 문자 언어는 기록으로 남아 오랫동안 보존할 수 있지만, 음성 언어는 말이 끝나면서 소리가 사라지는 대신 목소리의 크기나 억양으로 감정과 의도를 생생하게 전할 수 있다.","scoring_points":["같은 점을 바르게 썼는가","다른 점 두 가지를 바르게 썼는가","두 언어의 특성을 바꾸어 쓰지 않았는가"]},"explanation":["같은 점은 둘 다 생각을 전한다는 것이에요.","다른 점은 나타내는 방법과 남는지, 사라지는지예요.","목소리와 글자의 강조 방법도 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_review_a#24','kor',6,2,'u5','','tb_g6_2_kor_u5_review_a','unit_review','K6-2-u5-C21',4,'essay','teacher','우리 학교 학생들을 독자로 하는 기사문을 쓰려고 해요. 독자의 특성을 쓰고, 그 특성에 맞는 기삿거리와 필요한 자료, 자료 수집 방법을 정해 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K6-2-u5-C21","difficulty":4,"kind":"essay","stem":"우리 학교 학생들을 독자로 하는 기사문을 쓰려고 해요. 독자의 특성을 쓰고, 그 특성에 맞는 기삿거리와 필요한 자료, 자료 수집 방법을 정해 쓰세요.","answer_guide":{"answer":"예: 독자의 특성 — 우리 학교 학생들은 직접 실천할 수 있는 내용에 관심이 많다. 기삿거리 — 에너지 절약 생활화. 필요한 자료 — 학생의 생각을 나타내는 자료. 자료 수집 방법 — 학생을 대상으로 설문 조사를 실시한다.","scoring_points":["독자의 특성을 썼는가","특성에 맞는 기삿거리를 정했는가","자료와 수집 방법이 기삿거리와 이어지는가"]},"explanation":["독자를 먼저 조사해요.","독자의 관심에 맞는 기삿거리를 골라요.","필요한 자료와 모을 방법까지 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_review_a#25','kor',6,2,'u5','','tb_g6_2_kor_u5_review_a','unit_review','K6-2-u5-C14',4,'essay','teacher','『국어』 251쪽 3번처럼 독자를 고려해 글을 쓰는 방법을 친구에게 세 가지 설명해 주세요.','{}'::text[],false,'{"seq":25,"concept":"K6-2-u5-C14","difficulty":4,"kind":"essay","stem":"『국어』 251쪽 3번처럼 독자를 고려해 글을 쓰는 방법을 친구에게 세 가지 설명해 주세요.","answer_guide":{"answer":"예: 글을 쓸 때에는 독자가 어떤 관심과 흥미를 가지고 있는지 고려하며 써야 해. 독자가 이해하기 쉽게 적절한 매체를 골라 활용해야 해. 독자가 이해하기 쉬운 낱말이나 표현을 골라 써야 해.","scoring_points":["독자의 관심과 흥미를 썼는가","알맞은 매체 고르기를 썼는가","이해하기 쉬운 낱말이나 표현을 썼는가"]},"explanation":["독자의 관심과 흥미를 고려해요.","독자에게 알맞은 매체를 골라요.","이해하기 쉬운 표현을 골라 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_review_b#1','kor',6,2,'u5','','tb_g6_2_kor_u5_review_b','unit_review','K6-2-u5-C1',1,'sa','auto','「글자로 나타내는 말」을 무엇이라고 하나요? 네 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K6-2-u5-C1","difficulty":1,"kind":"sa","stem":"「글자로 나타내는 말」을 무엇이라고 하나요? 네 글자로 쓰세요.","answer":["문자 언어","문자언어"],"explanation":["『국어』 223쪽에서 두 언어의 뜻을 배웠어요.","글자로 나타내는 말은 문자 언어예요.","음성으로 나타내는 말은 음성 언어예요."],"mis":"K6-2-u5-X01"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_review_b#2','kor',6,2,'u5','','tb_g6_2_kor_u5_review_b','unit_review','K6-2-u5-C1',1,'mc','auto','『국어』 250쪽 그림 ㉯에서 친구는 어떻게 의사소통하고 있나요?',ARRAY['K6-2-u5-X01']::text[],false,'{"seq":2,"concept":"K6-2-u5-C1","difficulty":1,"kind":"mc","stem":"『국어』 250쪽 그림 ㉯에서 친구는 어떻게 의사소통하고 있나요?","options":[{"t":"글을 써서 문자 언어로 의사소통한다","correct":true},{"t":"직접 만나서 음성 언어로 의사소통한다","mis":"K6-2-u5-X01"},{"t":"목소리를 녹음해 보낸다","mis":"K6-2-u5-X01"}],"explanation":["그림 ㉯의 친구는 책상에 앉아 글을 써요.","글을 써서 문자 언어로 의사소통해요.","문자 언어는 시간과 장소에 제한 없이 내용을 전할 수 있어요."],"asset":{"type":"passage","lines":["㉮ [그림] 두 친구가 직접 만나서 이야기를 나눈다.","㉯ [그림] 한 친구가 책상에 앉아 글을 쓰고 있다."],"numbered":false,"title":"『국어』 250쪽 1번"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_review_b#3','kor',6,2,'u5','','tb_g6_2_kor_u5_review_b','unit_review','K6-2-u5-C3',1,'mc','auto','『국어』 230쪽 4번에서 음성 매체의 예로 든 것은 무엇인가요?',ARRAY['K6-2-u5-X04']::text[],false,'{"seq":3,"concept":"K6-2-u5-C3","difficulty":1,"kind":"mc","stem":"『국어』 230쪽 4번에서 음성 매체의 예로 든 것은 무엇인가요?","options":[{"t":"오디오 북","correct":true},{"t":"종이 신문","mis":"K6-2-u5-X04"},{"t":"텔레비전","mis":"K6-2-u5-X04"},{"t":"그림책","mis":"K6-2-u5-X04"}],"explanation":["음성 매체는 음성 언어를 기반으로 해요.","오디오 북이 그 예예요.","신문·책은 인쇄 매체, 텔레비전은 영상 매체예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_review_b#4','kor',6,2,'u5','','tb_g6_2_kor_u5_review_b','unit_review','K6-2-u5-C27',1,'ox','auto','「‘작가와의 만남’ 행사 안내」에서 제목을 큰 글자로 쓴 것은 중요한 내용을 눈에 띄게 나타낸 방법이에요.',ARRAY['K6-2-u5-X47']::text[],false,'{"seq":4,"concept":"K6-2-u5-C27","difficulty":1,"kind":"ox","stem":"「‘작가와의 만남’ 행사 안내」에서 제목을 큰 글자로 쓴 것은 중요한 내용을 눈에 띄게 나타낸 방법이에요.","answer":"O","reason_options":[{"t":"글자의 크기나 굵기를 다르게 하면 중요한 내용을 시각적으로 나타낼 수 있기 때문에","correct":true},{"t":"글자 크기는 내용 전달과 아무 관계가 없기 때문에","mis":"K6-2-u5-X47"}],"mis":"K6-2-u5-X47","explanation":["문자 언어는 글자 크기와 굵기를 바꿀 수 있어요.","제목을 크게 쓰면 무엇에 대한 글인지 눈에 띄어요.","표현 방식도 정보 전달을 도와요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_review_b#5','kor',6,2,'u5','','tb_g6_2_kor_u5_review_b','unit_review','K6-2-u5-C28',1,'ox','auto','「선생님의 안내 말씀」에서 선생님은 중요한 내용을 말할 때 목소리를 크게 하셨어요.',ARRAY['K6-2-u5-X47']::text[],false,'{"seq":5,"concept":"K6-2-u5-C28","difficulty":1,"kind":"ox","stem":"「선생님의 안내 말씀」에서 선생님은 중요한 내용을 말할 때 목소리를 크게 하셨어요.","answer":"O","reason_options":[{"t":"재능 발표회 시작 시각과 장소를 말할 때 목소리를 크고 또박또박하게 하셨기 때문에","correct":true},{"t":"선생님은 처음부터 끝까지 같은 목소리로만 말씀하셨기 때문에","mis":"K6-2-u5-X47"}],"mis":"K6-2-u5-X47","explanation":["친구는 「중요한 내용일 때에는 목소리를 크게 하셨어.」라고 했어요.","목소리의 크기로 중요한 곳을 알려 줘요.","이것이 음성 언어의 특성이에요."],"asset":{"type":"passage","lines":["(간추림) 내일 재능 발표회는 오전 9시 30분에 학교 강당에서 시작된다.","[이 부분은 목소리를 크고 또박또박하게 말씀하신다.]","(간추림) 발표하는 친구는 등교하자마자 강당에 가서 나무반 선생님께 말씀드린다.","(간추림) 관람하는 친구는 교실에 모였다가 9시에 선생님과 함께 강당으로 간다.","(간추림) 6학년 자리는 무대를 바라보고 강당 오른편이다.","(간추림) 당부 셋 — 큰 박수로 응원 · 자리를 지키며 집중 · 뛰지 말고 안전하게"],"numbered":false,"title":"「선생님의 안내 말씀」(『국어』 226쪽 듣기 자료, 간추림)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_review_b#6','kor',6,2,'u5','','tb_g6_2_kor_u5_review_b','unit_review','K6-2-u5-C19',1,'sa','auto','기사문에서 「기사문의 주된 내용을 담고 있는 부분」을 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":6,"concept":"K6-2-u5-C19","difficulty":1,"kind":"sa","stem":"기사문에서 「기사문의 주된 내용을 담고 있는 부분」을 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["본문"],"explanation":["『국어』 243쪽에서 본문의 뜻을 살펴봤어요.","주된 내용을 담은 부분은 본문이에요.","본문은 내용을 자세히 써요."],"mis":"K6-2-u5-X28"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_review_b#7','kor',6,2,'u5','','tb_g6_2_kor_u5_review_b','unit_review','K6-2-u5-C16',1,'sa','auto','『국어』 241쪽 7번이에요. 「글을 쓰고 고쳐 쓸 때에는 독자가 (    )하기 쉬운 표현인지, 오해할 만한 표현은 없는지 생각한다.」 빈칸에 알맞은 두 글자 낱말을 쓰세요.','{}'::text[],false,'{"seq":7,"concept":"K6-2-u5-C16","difficulty":1,"kind":"sa","stem":"『국어』 241쪽 7번이에요. 「글을 쓰고 고쳐 쓸 때에는 독자가 (    )하기 쉬운 표현인지, 오해할 만한 표현은 없는지 생각한다.」 빈칸에 알맞은 두 글자 낱말을 쓰세요.","answer":["이해"],"explanation":["고쳐 쓸 때에도 독자를 생각해요.","독자가 이해하기 쉬운 표현인지 살펴요.","오해할 만한 표현도 고쳐요."],"mis":"K6-2-u5-X22"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_review_b#8','kor',6,2,'u5','','tb_g6_2_kor_u5_review_b','unit_review','K6-2-u5-C25',1,'sa','auto','「넓다」는 어떻게 소리 나나요? [ ] 안에 들어갈 발음을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K6-2-u5-C25","difficulty":1,"kind":"sa","stem":"「넓다」는 어떻게 소리 나나요? [ ] 안에 들어갈 발음을 쓰세요.","answer":["널따"],"explanation":["겹받침 ㄼ 뒤에 자음자 ㄷ이 와요.","겹받침 ㄼ은 자음자와 만나면 [ㄹ]로 소리 나요.","그래서 [널따]로 발음해요."],"mis":"K6-2-u5-X39"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_review_b#9','kor',6,2,'u5','','tb_g6_2_kor_u5_review_b','unit_review','K6-2-u5-C29',2,'ox','auto','「아동 안전 ― 운전자가 보호자 ―」는 음성 언어로 설명하면서 문자 언어로도 내용을 정리하거나 강조해 효과적으로 전달하려고 해요.',ARRAY['K6-2-u5-X11']::text[],false,'{"seq":9,"concept":"K6-2-u5-C29","difficulty":2,"kind":"ox","stem":"「아동 안전 ― 운전자가 보호자 ―」는 음성 언어로 설명하면서 문자 언어로도 내용을 정리하거나 강조해 효과적으로 전달하려고 해요.","answer":"O","reason_options":[{"t":"「도로에서는 운전자가 보호자입니다.」라는 말과 「운전면허는 보행자 보호 면허」라는 글자를 함께 썼기 때문에","correct":true},{"t":"음성 언어만 쓰고 글자는 하나도 쓰지 않았기 때문에","mis":"K6-2-u5-X11"}],"mis":"K6-2-u5-X11","explanation":["장면 ㉠에서 말과 글자를 함께 써요.","말로 설명하고 글자로 정리하고 강조해요.","두 언어가 서로 도와 효과적으로 전해요."],"asset":{"type":"passage","lines":["㉠ [음성 언어] 「도로에서는 운전자가 보호자입니다.」라고 설명한다.","㉠ [문자 언어] 「운전면허는 보행자 보호 면허」라는 글자를 운전면허증처럼 도로 위에","㉡ 어린이 보호 구역 표지판과 「스쿨 존에서는 속도를 줄이고」라는 자막","㉢ [음성 언어] 「지켜 주셔서 고맙습니다.」라는 아이의 말과 안전하게 길을 건너는 장면"],"numbered":false,"title":"「아동 안전 ― 운전자가 보호자 ―」(『국어』 229쪽 장면 설명)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_review_b#10','kor',6,2,'u5','','tb_g6_2_kor_u5_review_b','unit_review','K6-2-u5-C30',2,'ox','auto','「수월봉 화산 쇄설층」에서는 수월봉 일대가 제주도에서 가장 넓은 녹차 재배 지역이라고 했어요.',ARRAY['K6-2-u5-X41']::text[],false,'{"seq":10,"concept":"K6-2-u5-C30","difficulty":2,"kind":"ox","stem":"「수월봉 화산 쇄설층」에서는 수월봉 일대가 제주도에서 가장 넓은 녹차 재배 지역이라고 했어요.","answer":"X","reason_options":[{"t":"영상은 화산 쇄설층이 만들어진 과정과 분화구를 다루며, 녹차 재배 지역이라는 내용은 영상 내용과 맞지 않기 때문에","correct":true},{"t":"제주도를 다룬 영상이니 녹차 이야기가 꼭 나오기 때문에","mis":"K6-2-u5-X41"}],"mis":"K6-2-u5-X41","explanation":["영상 내용을 정확하게 확인하며 보아요.","영상은 화산 쇄설층과 분화구를 설명해요.","짐작으로 내용을 덧붙이지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_review_b#11','kor',6,2,'u5','','tb_g6_2_kor_u5_review_b','unit_review','K6-2-u5-C6',2,'ox','auto','감정을 표현해야 하는 상황에서는 목소리에 마음을 담을 수 있는 음성 언어가 알맞을 수 있어요.',ARRAY['K6-2-u5-X10']::text[],false,'{"seq":11,"concept":"K6-2-u5-C6","difficulty":2,"kind":"ox","stem":"감정을 표현해야 하는 상황에서는 목소리에 마음을 담을 수 있는 음성 언어가 알맞을 수 있어요.","answer":"O","reason_options":[{"t":"음성 언어는 목소리의 크기나 억양으로 감정과 의도를 전할 수 있기 때문에","correct":true},{"t":"감정은 언제나 글로만 전해야 하기 때문에","mis":"K6-2-u5-X10"}],"mis":"K6-2-u5-X10","explanation":["상황에 따라 알맞은 언어가 달라요.","감정을 전할 때는 목소리가 큰 힘이 돼요.","『국어』 227쪽 4번의 상황 2가 그런 예예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_review_b#12','kor',6,2,'u5','','tb_g6_2_kor_u5_review_b','unit_review','K6-2-u5-C18',2,'sa','auto','『국어』 251쪽 2번이에요. 「사용할 매체를 정하고 (    )을/를 확인하여 정확한 문장으로 표현해야 해요.」 빈칸에 알맞은 두 글자 낱말을 보기(관심, 독자, 사실)에서 골라 쓰세요.','{}'::text[],false,'{"seq":12,"concept":"K6-2-u5-C18","difficulty":2,"kind":"sa","stem":"『국어』 251쪽 2번이에요. 「사용할 매체를 정하고 (    )을/를 확인하여 정확한 문장으로 표현해야 해요.」 빈칸에 알맞은 두 글자 낱말을 보기(관심, 독자, 사실)에서 골라 쓰세요.","answer":["사실"],"explanation":["기사문은 사실을 전하는 글이에요.","사실을 확인하여 정확한 문장으로 써요.","확인하지 않은 내용은 쓰지 않아요."],"mis":"K6-2-u5-X27"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_review_b#13','kor',6,2,'u5','','tb_g6_2_kor_u5_review_b','unit_review','K6-2-u5-C17',2,'ox','auto','「계단을 안전하게 이용합시다」에서 그래프를 넣은 것은 학생들이 그림이나 그래프가 있을 때 내용을 더 쉽게 이해한다는 특성을 고려한 거예요.',ARRAY['K6-2-u5-X23']::text[],false,'{"seq":13,"concept":"K6-2-u5-C17","difficulty":2,"kind":"ox","stem":"「계단을 안전하게 이용합시다」에서 그래프를 넣은 것은 학생들이 그림이나 그래프가 있을 때 내용을 더 쉽게 이해한다는 특성을 고려한 거예요.","answer":"O","reason_options":[{"t":"계획 단계에서 조사한 독자의 특성에 맞추어 자료를 골랐기 때문에","correct":true},{"t":"그래프는 글을 꾸미려고 아무 때나 넣는 것이기 때문에","mis":"K6-2-u5-X23"}],"mis":"K6-2-u5-X23","explanation":["계획하기에서 독자의 특성을 조사했어요.","그 특성에 맞추어 그래프를 넣었어요.","자료는 독자의 이해를 도우려고 넣어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_review_b#14','kor',6,2,'u5','','tb_g6_2_kor_u5_review_b','unit_review','K6-2-u5-C34',2,'ox','auto','「희망초등학교, ‘전문가와 함께 하는 예술 진로 캠프’ 개최」의 캠프는 11월 8일부터 9일까지 이틀간 열렸어요.',ARRAY['K6-2-u5-X29']::text[],false,'{"seq":14,"concept":"K6-2-u5-C34","difficulty":2,"kind":"ox","stem":"「희망초등학교, ‘전문가와 함께 하는 예술 진로 캠프’ 개최」의 캠프는 11월 8일부터 9일까지 이틀간 열렸어요.","answer":"O","reason_options":[{"t":"전문에 언제(11월 8일부터 9일까지 이틀간)가 나와 있기 때문에","correct":true},{"t":"전문에는 언제가 나오지 않기 때문에","mis":"K6-2-u5-X29"}],"mis":"K6-2-u5-X29","explanation":["전문은 육하원칙 중심으로 요약해요.","언제는 11월 8일부터 9일까지 이틀간이에요.","전문만 읽어도 이 내용을 알 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_review_b#15','kor',6,2,'u5','','tb_g6_2_kor_u5_review_b','unit_review','K6-2-u5-C35',2,'ox','auto','행사에 초대할 때에는 초대 편지를, 정보를 전달할 때에는 알림 편지를 써요.',ARRAY['K6-2-u5-X44']::text[],false,'{"seq":15,"concept":"K6-2-u5-C35","difficulty":2,"kind":"ox","stem":"행사에 초대할 때에는 초대 편지를, 정보를 전달할 때에는 알림 편지를 써요.","answer":"O","reason_options":[{"t":"편지는 쓰는 목적에 따라 종류가 달라지기 때문에","correct":true},{"t":"편지의 종류는 목적과 상관없이 아무것이나 고르면 되기 때문에","mis":"K6-2-u5-X44"}],"mis":"K6-2-u5-X44","explanation":["편지는 목적에 따라 종류가 나뉘어요.","초대할 때는 초대 편지, 정보를 전할 때는 알림 편지예요.","목적에 맞는 편지를 골라 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_review_b#16','kor',6,2,'u5','','tb_g6_2_kor_u5_review_b','unit_review','K6-2-u5-C10',2,'ox','auto','공익 광고에서 언어의 표현 효과를 정리할 때에는 자막이 몇 개인지 세는 것이 가장 중요해요.',ARRAY['K6-2-u5-X13']::text[],false,'{"seq":16,"concept":"K6-2-u5-C10","difficulty":2,"kind":"ox","stem":"공익 광고에서 언어의 표현 효과를 정리할 때에는 자막이 몇 개인지 세는 것이 가장 중요해요.","answer":"X","reason_options":[{"t":"표현 효과는 요소의 개수가 아니라 그 표현이 내용 전달을 어떻게 돕는지로 보기 때문에","correct":true},{"t":"자막이 많을수록 표현 효과가 크기 때문에","mis":"K6-2-u5-X13"}],"mis":"K6-2-u5-X13","explanation":["표현 효과는 표현이 무엇을 돕는지예요.","자막이 많다고 잘 전달되는 것은 아니에요.","어떤 표현이 어떤 내용을 또렷하게 했는지 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_review_b#17','kor',6,2,'u5','','tb_g6_2_kor_u5_review_b','unit_review','K6-2-u5-C2',3,'error','auto','문자 언어와 음성 언어의 다른 점을 정리했어요. 알맞지 않게 정리한 것은 무엇인가요?',ARRAY['K6-2-u5-X02','K6-2-u5-X01','K6-2-u5-X07']::text[],false,'{"seq":17,"concept":"K6-2-u5-C2","difficulty":3,"kind":"error","stem":"문자 언어와 음성 언어의 다른 점을 정리했어요. 알맞지 않게 정리한 것은 무엇인가요?","options":[{"t":"음성 언어는 어떤 경우에도 기록으로 남길 수 없다.","correct":true,"mis_target":"K6-2-u5-X02"},{"t":"문자 언어는 글자로, 음성 언어는 음성으로 나타낸다.","mis":"K6-2-u5-X01"},{"t":"문자 언어는 다시 볼 수 있고, 음성 언어는 보통 말이 끝나면 사라진다.","mis":"K6-2-u5-X07"}],"explanation":["음성 언어는 보통 말하면 사라져요.","하지만 음성 메모처럼 녹음하면 남길 수 있어요.","「어떤 경우에도」처럼 규칙으로 외우면 안 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_review_b#18','kor',6,2,'u5','','tb_g6_2_kor_u5_review_b','unit_review','K6-2-u5-C10',3,'ox','auto','공익 광고의 언어 표현 효과를 정리할 때 「어떤 표현이 쓰였나」와 「그것이 내용 전달을 어떻게 돕나」를 함께 써야 해요.',ARRAY['K6-2-u5-X12']::text[],false,'{"seq":18,"concept":"K6-2-u5-C10","difficulty":3,"kind":"ox","stem":"공익 광고의 언어 표현 효과를 정리할 때 「어떤 표현이 쓰였나」와 「그것이 내용 전달을 어떻게 돕나」를 함께 써야 해요.","answer":"O","reason_options":[{"t":"표현 방법만 늘어놓으면 효과를 알 수 없고, 무엇을 돕는지까지 써야 표현 효과가 되기 때문에","correct":true},{"t":"쓰인 표현의 이름만 적으면 표현 효과를 다 정리한 것이기 때문에","mis":"K6-2-u5-X12"}],"mis":"K6-2-u5-X12","explanation":["먼저 쓰인 표현을 찾아요.","그 표현이 무엇을 돕는지 이어요.","둘이 함께 있어야 표현 효과예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_review_b#19','kor',6,2,'u5','','tb_g6_2_kor_u5_review_b','unit_review','K6-2-u5-C32',3,'ox','auto','『국어』 237쪽 「그림자 술래잡기」를 읽고 독자의 반응이 달라진 까닭은 쓰는 사람이 독자를 고려해 글을 썼기 때문이에요.',ARRAY['K6-2-u5-X19']::text[],false,'{"seq":19,"concept":"K6-2-u5-C32","difficulty":3,"kind":"ox","stem":"『국어』 237쪽 「그림자 술래잡기」를 읽고 독자의 반응이 달라진 까닭은 쓰는 사람이 독자를 고려해 글을 썼기 때문이에요.","answer":"O","reason_options":[{"t":"독자가 이해하기 쉬운 낱말로, 독자가 찾던 놀이 방법을 썼기 때문에","correct":true},{"t":"글의 소재가 운동장 놀이에서 다른 소재로 완전히 바뀌었기 때문에","mis":"K6-2-u5-X19"}],"mis":"K6-2-u5-X19","explanation":["두 글은 같은 운동장 놀이를 다뤄요.","다시 쓴 글은 쉬운 낱말로 독자가 찾던 내용을 썼어요.","쓰는 사람이 독자를 고려했기 때문에 반응이 달라졌어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_review_b#20','kor',6,2,'u5','','tb_g6_2_kor_u5_review_b','unit_review','K6-2-u5-C21',3,'ox','auto','기사문에 설문 조사 결과를 자료로 넣을 때에는 언제, 누구를 대상으로 조사했는지 밝혀야 해요.',ARRAY['K6-2-u5-X32']::text[],false,'{"seq":20,"concept":"K6-2-u5-C21","difficulty":3,"kind":"ox","stem":"기사문에 설문 조사 결과를 자료로 넣을 때에는 언제, 누구를 대상으로 조사했는지 밝혀야 해요.","answer":"O","reason_options":[{"t":"자료의 출처를 밝혀야 독자가 기사 내용을 믿고 확인할 수 있기 때문에","correct":true},{"t":"조사 결과는 숫자만 쓰면 출처는 필요 없기 때문에","mis":"K6-2-u5-X32"}],"mis":"K6-2-u5-X32","explanation":["자료를 제시할 때에는 반드시 출처를 밝혀요.","「계단을 안전하게 이용합시다」도 학생 50명을 대상으로 했다고 밝혔어요.","그래야 독자가 믿을 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_review_b#21','kor',6,2,'u5','','tb_g6_2_kor_u5_review_b','unit_review','K6-2-u5-C12',3,'ox','auto','영상을 감상할 때 매체에서 표현하는 내용을 확인했는지, 문자 언어와 음성 언어의 표현 특성을 생각했는지 스스로 점검해 볼 수 있어요.',ARRAY['K6-2-u5-X15']::text[],false,'{"seq":21,"concept":"K6-2-u5-C12","difficulty":3,"kind":"ox","stem":"영상을 감상할 때 매체에서 표현하는 내용을 확인했는지, 문자 언어와 음성 언어의 표현 특성을 생각했는지 스스로 점검해 볼 수 있어요.","answer":"O","reason_options":[{"t":"표현 효과를 생각하며 시청했는지 돌아보아야 더 깊이 감상할 수 있기 때문에","correct":true},{"t":"영상은 재미만 있으면 따로 점검할 것이 없기 때문에","mis":"K6-2-u5-X15"}],"mis":"K6-2-u5-X15","explanation":["『국어』 235쪽 점검하기는 세 가지를 물어요.","내용 확인, 두 언어의 특성, 표현 방법의 어울림이에요.","스스로 점검하면 감상이 깊어져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_review_b#22','kor',6,2,'u5','','tb_g6_2_kor_u5_review_b','unit_review','K6-2-u5-C21',3,'ox','auto','기사문을 쓰기 전에 독자의 특성, 기삿거리, 필요한 자료, 자료 수집 방법을 정리하는 것은 기사문의 개요를 쓰기 위한 준비 활동이에요.',ARRAY['K6-2-u5-X21']::text[],false,'{"seq":22,"concept":"K6-2-u5-C21","difficulty":3,"kind":"ox","stem":"기사문을 쓰기 전에 독자의 특성, 기삿거리, 필요한 자료, 자료 수집 방법을 정리하는 것은 기사문의 개요를 쓰기 위한 준비 활동이에요.","answer":"O","reason_options":[{"t":"계획을 먼저 세워야 독자를 고려한 표제와 부제, 본문의 개요를 짤 수 있기 때문에","correct":true},{"t":"계획은 기사문을 다 쓴 뒤에 하는 일이기 때문에","mis":"K6-2-u5-X21"}],"mis":"K6-2-u5-X21","explanation":["기사문 쓰기는 계획하기부터 시작해요.","계획을 바탕으로 개요를 짜요.","그다음 글쓰기, 수정하기, 공유하기를 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_review_b#23','kor',6,2,'u5','','tb_g6_2_kor_u5_review_b','unit_review','K6-2-u5-C6',4,'essay','teacher','문자 언어와 음성 언어를 사용한 경험을 하나씩 떠올려 쓰고, 그때 그 언어를 쓰니 좋았던 점을 언어의 특성과 이어 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K6-2-u5-C6","difficulty":4,"kind":"essay","stem":"문자 언어와 음성 언어를 사용한 경험을 하나씩 떠올려 쓰고, 그때 그 언어를 쓰니 좋았던 점을 언어의 특성과 이어 쓰세요.","answer_guide":{"answer":"예: 문자 언어 — 행사 안내장을 읽고 장소와 시간을 확인했다. 글로 남아 있어서 헷갈릴 때 다시 볼 수 있어 좋았다. 음성 언어 — 선생님께 직접 설명을 듣다가 모르는 내용을 다시 여쭈어보았다. 그 자리에서 바로 물어볼 수 있어 좋았다.","scoring_points":["문자 언어를 사용한 경험을 썼는가","음성 언어를 사용한 경험을 썼는가","좋았던 점을 각 언어의 특성과 이어 썼는가"]},"explanation":["일상생활에서 쓴 경험을 떠올려요.","그 언어의 어떤 특성 덕분이었는지 생각해요.","경험과 특성을 이어 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_review_b#24','kor',6,2,'u5','','tb_g6_2_kor_u5_review_b','unit_review','K6-2-u5-C19',4,'essay','teacher','『국어』 245쪽 계획하기 예시 답안(기삿거리 「에너지 절약 생활화」)을 바탕으로 기사문의 제목과 전문을 쓰세요. 전문은 누가, 언제, 어디에서, 무엇을 했는지 드러나게 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K6-2-u5-C19","difficulty":4,"kind":"essay","stem":"『국어』 245쪽 계획하기 예시 답안(기삿거리 「에너지 절약 생활화」)을 바탕으로 기사문의 제목과 전문을 쓰세요. 전문은 누가, 언제, 어디에서, 무엇을 했는지 드러나게 쓰세요.","answer_guide":{"answer":"예: 제목 — 텅 빈 교실에 전등만 ‘활짝’……. 전문 — 우리 학교 어린이 기자단이 점심시간에 교실들을 둘러본 결과, 텅 빈 교실에도 전등이 켜져 있는 등 에너지 낭비 실태가 드러났다. 학생들은 설문 조사에서 ‘전등 끄기’를 가장 좋은 실천 방법으로 꼽았다.","scoring_points":["기사 내용을 간결하게 드러내는 제목을 썼는가","전문에 누가·언제·어디에서·무엇을이 드러나는가","확인한 사실을 바탕으로 썼는가"]},"explanation":["제목은 내용을 간결하게, 관심을 끌게 써요.","전문은 육하원칙 중심으로 요약해요.","조사한 사실을 바탕으로 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_review_b#25','kor',6,2,'u5','','tb_g6_2_kor_u5_review_b','unit_review','K6-2-u5-C24',4,'essay','teacher','이 단원에서 배운 내용을 생활에서 실천하려고 해요. 마음을 전하고 싶은 사람에게 편지를 쓸 때 언어의 특성과 독자를 고려해 무엇을 할지, 언제 할지 구체적으로 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K6-2-u5-C24","difficulty":4,"kind":"essay","stem":"이 단원에서 배운 내용을 생활에서 실천하려고 해요. 마음을 전하고 싶은 사람에게 편지를 쓸 때 언어의 특성과 독자를 고려해 무엇을 할지, 언제 할지 구체적으로 쓰세요.","answer_guide":{"answer":"예: 이번 주말에 전학 간 친구에게 손 편지를 쓰겠다. 글로 남아 친구가 오래 간직할 수 있기 때문이다. 친구가 궁금해할 우리 반 소식을 쉬운 말로 쓰고, 첫인사와 끝인사, 쓴 날짜와 보내는 사람을 빠뜨리지 않겠다. 다 쓰면 직접 부치고 답장을 기다리겠다.","scoring_points":["언제, 누구에게, 무엇을 할지 구체적으로 썼는가","매체를 고른 까닭을 언어의 특성과 이었는가","독자를 고려한 점과 편지의 짜임을 썼는가"]},"explanation":["막연한 다짐보다 언제, 무엇을 할지 써요.","매체를 고른 까닭을 특성과 이어요.","받는 사람을 생각하며 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_review_c#1','kor',6,2,'u5','','tb_g6_2_kor_u5_review_c','unit_review','K6-2-u5-C1',1,'ox','auto','전화로 길 안내를 듣는 것은 음성 언어로 정보를 전달받는 거예요.',ARRAY['K6-2-u5-X01']::text[],false,'{"seq":1,"concept":"K6-2-u5-C1","difficulty":1,"kind":"ox","stem":"전화로 길 안내를 듣는 것은 음성 언어로 정보를 전달받는 거예요.","answer":"O","reason_options":[{"t":"음성으로 나타내는 말을 귀로 듣고 있기 때문에","correct":true},{"t":"전화는 기계를 쓰므로 문자 언어이기 때문에","mis":"K6-2-u5-X01"}],"mis":"K6-2-u5-X01","explanation":["『국어』 222쪽 상황 ㉯가 전화로 길을 찾는 상황이에요.","전화로 듣는 말은 음성 언어예요.","기계를 거쳐도 음성으로 나타내는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_review_c#2','kor',6,2,'u5','','tb_g6_2_kor_u5_review_c','unit_review','K6-2-u5-C5',1,'ox','auto','『국어』 250쪽 그림 ㉮에서 주로 사용한 음성 언어는 사용하면 사라지지만 생생하게 내용을 전달할 수 있어요.',ARRAY['K6-2-u5-X02']::text[],false,'{"seq":2,"concept":"K6-2-u5-C5","difficulty":1,"kind":"ox","stem":"『국어』 250쪽 그림 ㉮에서 주로 사용한 음성 언어는 사용하면 사라지지만 생생하게 내용을 전달할 수 있어요.","answer":"O","reason_options":[{"t":"직접 만나서 하는 말은 사라지지만 목소리로 생생하게 전할 수 있기 때문에","correct":true},{"t":"음성 언어는 기록으로 남아 오랫동안 보존되기 때문에","mis":"K6-2-u5-X02"}],"mis":"K6-2-u5-X02","explanation":["그림 ㉮는 음성 언어를 써요.","음성 언어는 사용하면 사라져요.","하지만 생생하게 내용을 전달할 수 있어요."],"asset":{"type":"passage","lines":["㉮ [그림] 두 친구가 직접 만나서 이야기를 나눈다.","㉯ [그림] 한 친구가 책상에 앉아 글을 쓰고 있다."],"numbered":false,"title":"『국어』 250쪽 1번"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_review_c#3','kor',6,2,'u5','','tb_g6_2_kor_u5_review_c','unit_review','K6-2-u5-C3',1,'sa','auto','『국어』 230쪽 4번이에요. 「음성 매체는 음성 언어를 기반으로 소리, (    ) 같은 것을 함께 사용해 정보를 전달하는 매체이다.」 빈칸에 알맞은 두 글자 낱말을 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"K6-2-u5-C3","difficulty":1,"kind":"sa","stem":"『국어』 230쪽 4번이에요. 「음성 매체는 음성 언어를 기반으로 소리, (    ) 같은 것을 함께 사용해 정보를 전달하는 매체이다.」 빈칸에 알맞은 두 글자 낱말을 쓰세요.","answer":["음악"],"explanation":["보기는 텔레비전, 문자, 신문, 음악이에요.","음성 매체는 소리와 음악을 함께 써요.","오디오 북이 음성 매체예요."],"mis":"K6-2-u5-X04"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_review_c#4','kor',6,2,'u5','','tb_g6_2_kor_u5_review_c','unit_review','K6-2-u5-C27',1,'sa','auto','「‘작가와의 만남’ 행사 안내」를 읽고 친구가 말했어요. 「안내하는 글은 (    )(으)로 내용을 전달하고 있어서 눈으로 읽고 내용을 이해할 수 있었어.」 빈칸에 알맞은 두 글자 낱말을 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"K6-2-u5-C27","difficulty":1,"kind":"sa","stem":"「‘작가와의 만남’ 행사 안내」를 읽고 친구가 말했어요. 「안내하는 글은 (    )(으)로 내용을 전달하고 있어서 눈으로 읽고 내용을 이해할 수 있었어.」 빈칸에 알맞은 두 글자 낱말을 쓰세요.","answer":["글자"],"explanation":["안내하는 글은 문자 언어로 쓰였어요.","글자로 내용을 전달해 눈으로 읽어요.","글자로 쓰인 내용은 나중에 다시 볼 수 있어요."],"mis":"K6-2-u5-X01"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_review_c#5','kor',6,2,'u5','','tb_g6_2_kor_u5_review_c','unit_review','K6-2-u5-C28',1,'sa','auto','「선생님의 안내 말씀」에서 재능 발표회는 어디에서 시작되나요? 네 글자로 쓰세요.','{}'::text[],false,'{"seq":5,"concept":"K6-2-u5-C28","difficulty":1,"kind":"sa","stem":"「선생님의 안내 말씀」에서 재능 발표회는 어디에서 시작되나요? 네 글자로 쓰세요.","answer":["학교 강당","학교강당"],"explanation":["선생님은 시작 시각과 장소를 크고 또박또박하게 말씀하셨어요.","재능 발표회는 학교 강당에서 시작돼요.","중요한 내용은 메모하며 들어요."],"mis":"K6-2-u5-X47"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_review_c#6','kor',6,2,'u5','','tb_g6_2_kor_u5_review_c','unit_review','K6-2-u5-C19',1,'ox','auto','기사문의 제목은 표제로 이루어지며, 필요하면 부제가 붙기도 해요.',ARRAY['K6-2-u5-X28']::text[],false,'{"seq":6,"concept":"K6-2-u5-C19","difficulty":1,"kind":"ox","stem":"기사문의 제목은 표제로 이루어지며, 필요하면 부제가 붙기도 해요.","answer":"O","reason_options":[{"t":"부제는 필요할 때 표제에 덧붙어 그것을 보충하는 제목이기 때문에","correct":true},{"t":"기사문에는 반드시 부제가 있어야 하기 때문에","mis":"K6-2-u5-X28"}],"mis":"K6-2-u5-X28","explanation":["표제는 신문 기사의 제목이에요.","부제는 표제를 보충해요.","부제는 필요할 경우에만 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_review_c#7','kor',6,2,'u5','','tb_g6_2_kor_u5_review_c','unit_review','K6-2-u5-C14',1,'ox','auto','글을 쓰기 전에 독자의 흥미나 관심사, 겪고 있는 문제 같은 것을 조사해요.',ARRAY['K6-2-u5-X21']::text[],false,'{"seq":7,"concept":"K6-2-u5-C14","difficulty":1,"kind":"ox","stem":"글을 쓰기 전에 독자의 흥미나 관심사, 겪고 있는 문제 같은 것을 조사해요.","answer":"O","reason_options":[{"t":"독자를 알아야 독자의 관심을 끌고 이해하기 쉬운 글을 쓸 수 있기 때문에","correct":true},{"t":"글을 다 쓴 뒤에만 독자를 생각하면 되기 때문에","mis":"K6-2-u5-X21"}],"mis":"K6-2-u5-X21","explanation":["독자 조사는 글을 쓰기 전에 해요.","흥미, 관심사, 겪고 있는 문제를 알아봐요.","그 내용이 주제와 표현을 정하는 데 쓰여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_review_c#8','kor',6,2,'u5','','tb_g6_2_kor_u5_review_c','unit_review','K6-2-u5-C25',1,'ox','auto','겹받침 ㄼ이 들어 있는 「넓고」는 뒤에 자음자가 와서 [ㄹ]로 소리 나요.',ARRAY['K6-2-u5-X39']::text[],false,'{"seq":8,"concept":"K6-2-u5-C25","difficulty":1,"kind":"ox","stem":"겹받침 ㄼ이 들어 있는 「넓고」는 뒤에 자음자가 와서 [ㄹ]로 소리 나요.","answer":"O","reason_options":[{"t":"「넓고」는 [널꼬]처럼 받침 ㄹ만 소리 나기 때문에","correct":true},{"t":"겹받침 ㄼ은 언제나 [ㅂ]으로만 소리 나기 때문에","mis":"K6-2-u5-X39"}],"mis":"K6-2-u5-X39","explanation":["겹받침 ㄼ은 자음자와 만나면 [ㄹ]로 소리 나요.","「넓고」는 [널꼬]예요.","다만 「밟-」은 예외로 [ㅂ]으로 소리 나요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_review_c#9','kor',6,2,'u5','','tb_g6_2_kor_u5_review_c','unit_review','K6-2-u5-C29',2,'sa','auto','「아동 안전 ― 운전자가 보호자 ―」 장면 ㉢에서 아이가 한 말이에요. 「지켜 주셔서 (    ).」 빈칸에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-2-u5-C29","difficulty":2,"kind":"sa","stem":"「아동 안전 ― 운전자가 보호자 ―」 장면 ㉢에서 아이가 한 말이에요. 「지켜 주셔서 (    ).」 빈칸에 알맞은 말을 쓰세요.","answer":["고맙습니다"],"explanation":["장면 ㉢은 음성 언어로 아이의 말을 들려줘요.","아이는 「지켜 주셔서 고맙습니다.」라고 말해요.","안전하게 길을 건너는 장면과 함께 나와요."],"mis":"K6-2-u5-X12"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_review_c#10','kor',6,2,'u5','','tb_g6_2_kor_u5_review_c','unit_review','K6-2-u5-C30',2,'sa','auto','『국어』 232쪽 (1)의 예시 답안이에요. 「지하에서 올라온 (    )이/가 지표에 있는 물과 만나 폭발한 뒤, 화산재와 화산 쇄설물들이 쌓여 만들어졌습니다.」 빈칸에 알맞은 세 글자 낱말을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-2-u5-C30","difficulty":2,"kind":"sa","stem":"『국어』 232쪽 (1)의 예시 답안이에요. 「지하에서 올라온 (    )이/가 지표에 있는 물과 만나 폭발한 뒤, 화산재와 화산 쇄설물들이 쌓여 만들어졌습니다.」 빈칸에 알맞은 세 글자 낱말을 쓰세요.","answer":["마그마"],"explanation":["화산 쇄설층이 만들어진 과정이에요.","지하에서 올라온 마그마가 물과 만나 폭발했어요.","그 뒤 화산재와 화산 쇄설물이 쌓였어요."],"mis":"K6-2-u5-X41"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_review_c#11','kor',6,2,'u5','','tb_g6_2_kor_u5_review_c','unit_review','K6-2-u5-C6',2,'error','auto','『국어』 227쪽 4번에 답한 친구들의 까닭이에요. 언어의 특성과 이어지지 않게 까닭을 쓴 친구는 누구인가요?',ARRAY['K6-2-u5-X09','K6-2-u5-X07','K6-2-u5-X08']::text[],false,'{"seq":11,"concept":"K6-2-u5-C6","difficulty":2,"kind":"error","stem":"『국어』 227쪽 4번에 답한 친구들의 까닭이에요. 언어의 특성과 이어지지 않게 까닭을 쓴 친구는 누구인가요?","options":[{"t":"친구 3 — 「문자 언어를 쓰겠다. 그냥 글이 더 좋기 때문이다.」","correct":true,"mis_target":"K6-2-u5-X09"},{"t":"친구 1 — 「문자 언어를 쓰겠다. 순서를 글로 남기면 나중에 다시 볼 수 있기 때문이다.」","mis":"K6-2-u5-X07"},{"t":"친구 2 — 「음성 언어를 쓰겠다. 얼굴을 보고 목소리에 진심을 담을 수 있기 때문이다.」","mis":"K6-2-u5-X08"}],"explanation":["까닭은 언어의 특성과 이어져야 해요.","친구 1은 다시 볼 수 있음, 친구 2는 목소리에 담는 진심을 말했어요.","「그냥 더 좋다」는 특성과 이어지지 않아요."],"asset":{"type":"passage","lines":["상황 1 우리 반 친구에게 복잡한 종이접기 순서를 설명해 주는 상황","상황 2 어제 말다툼을 한 친구에게 미안한 마음을 전하고 싶은 상황"],"numbered":false,"title":"『국어』 227쪽 4번"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_review_c#12','kor',6,2,'u5','','tb_g6_2_kor_u5_review_c','unit_review','K6-2-u5-C21',2,'ox','auto','기사문을 쓸 때에는 독자의 관심을 끌 만한 내용인지 살펴보고 사용할 매체를 정해야 해요.',ARRAY['K6-2-u5-X30']::text[],false,'{"seq":12,"concept":"K6-2-u5-C21","difficulty":2,"kind":"ox","stem":"기사문을 쓸 때에는 독자의 관심을 끌 만한 내용인지 살펴보고 사용할 매체를 정해야 해요.","answer":"O","reason_options":[{"t":"독자와 매체를 고려해야 독자에게 잘 전달되는 기사문을 쓸 수 있기 때문에","correct":true},{"t":"기사문은 독자와 상관없이 기자가 쓰고 싶은 것을 쓰면 되기 때문에","mis":"K6-2-u5-X30"}],"mis":"K6-2-u5-X30","explanation":["기사문도 독자를 고려해 써요.","독자의 관심을 끌 내용인지 살펴요.","학급 누리집, 알림판, 신문처럼 매체도 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_review_c#13','kor',6,2,'u5','','tb_g6_2_kor_u5_review_c','unit_review','K6-2-u5-C33',2,'sa','auto','「계단을 안전하게 이용합시다」에서 학생 50명 가운데 계단에서 위험한 상황을 겪은 적이 없다고 답한 학생은 몇 명인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":13,"concept":"K6-2-u5-C33","difficulty":2,"kind":"sa","stem":"「계단을 안전하게 이용합시다」에서 학생 50명 가운데 계단에서 위험한 상황을 겪은 적이 없다고 답한 학생은 몇 명인가요? 숫자로 쓰세요.","answer":["4","4명"],"explanation":["그래프는 있다 40명, 거의 없다 6명, 없다 4명이에요.","없다고 답한 학생은 4명이에요.","그래프로 보면 한눈에 알 수 있어요."],"asset":{"type":"passage","lines":["[그래프] 계단에서 위험한 상황을 겪은 적이 있습니까?","[그래프] 있다 40명 · 거의 없다 6명 · 없다 4명","(간추림) 학교 정문에서 등교하는 학생 50명에게 물었더니 40명이 위험한 상황을 겪었다.","[별표 기호] 뛰지 말고 천천히 걸어요!","[별표 기호] 필요할 때에는 계단 난간을 잡아요!","[별표 기호] 앞을 잘 보고 걸어요!","[쓴 사람] ○○초등학교 전교 어린이회"],"numbered":false,"title":"「계단을 안전하게 이용합시다」(『국어』 240쪽, 간추림)"},"mis":"K6-2-u5-X27"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_review_c#14','kor',6,2,'u5','','tb_g6_2_kor_u5_review_c','unit_review','K6-2-u5-C34',2,'sa','auto','「희망초등학교, ‘전문가와 함께 하는 예술 진로 캠프’ 개최」를 쓴 사람이에요. 「희망초등학교 조○○ (    )」 빈칸에 알맞은 두 글자 낱말을 쓰세요.','{}'::text[],false,'{"seq":14,"concept":"K6-2-u5-C34","difficulty":2,"kind":"sa","stem":"「희망초등학교, ‘전문가와 함께 하는 예술 진로 캠프’ 개최」를 쓴 사람이에요. 「희망초등학교 조○○ (    )」 빈칸에 알맞은 두 글자 낱말을 쓰세요.","answer":["기자"],"explanation":["기사문 끝에 쓴 사람이 나와요.","기사문을 쓰는 사람을 기자라고 해요.","이 기사문은 희망초등학교 조○○ 기자가 썼어요."],"mis":"K6-2-u5-X28"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_review_c#15','kor',6,2,'u5','','tb_g6_2_kor_u5_review_c','unit_review','K6-2-u5-C35',2,'sa','auto','누군가에게 소식을 전할 때 쓰는 편지를 무엇이라고 하나요? 「(    ) 편지」의 빈칸에 들어갈 두 글자 낱말을 쓰세요.','{}'::text[],false,'{"seq":15,"concept":"K6-2-u5-C35","difficulty":2,"kind":"sa","stem":"누군가에게 소식을 전할 때 쓰는 편지를 무엇이라고 하나요? 「(    ) 편지」의 빈칸에 들어갈 두 글자 낱말을 쓰세요.","answer":["안부"],"explanation":["편지는 목적에 따라 종류가 달라요.","소식을 전할 때는 안부 편지를 써요.","편지 예시 「그리운 친구 민석이에게」도 안부를 묻는 편지예요."],"mis":"K6-2-u5-X44"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_review_c#16','kor',6,2,'u5','','tb_g6_2_kor_u5_review_c','unit_review','K6-2-u5-C4',2,'error','auto','『국어』 252쪽 스스로 확인하기에서 공부한 내용을 설명했어요. 잘못 설명한 것은 무엇인가요?',ARRAY['K6-2-u5-X01','K6-2-u5-X08','K6-2-u5-X07']::text[],false,'{"seq":16,"concept":"K6-2-u5-C4","difficulty":2,"kind":"error","stem":"『국어』 252쪽 스스로 확인하기에서 공부한 내용을 설명했어요. 잘못 설명한 것은 무엇인가요?","options":[{"t":"문자 언어는 말이 끝나면서 소리가 사라진다.","correct":true,"mis_target":"K6-2-u5-X01"},{"t":"음성 언어는 목소리의 크기나 억양으로 감정과 의도를 알 수 있다.","mis":"K6-2-u5-X08"},{"t":"문자 언어는 기록으로 남아 오랫동안 보존할 수 있다.","mis":"K6-2-u5-X07"}],"explanation":["소리가 사라지는 것은 음성 언어의 특성이에요.","문자 언어는 기록으로 남아 오래 보존돼요.","두 언어의 특성을 바꾸어 말하지 않도록 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_review_c#17','kor',6,2,'u5','','tb_g6_2_kor_u5_review_c','unit_review','K6-2-u5-C2',3,'ox','auto','디지털 기기에서는 문자 언어도 전통적인 특징과 다른 모습을 보이기도 해요.',ARRAY['K6-2-u5-X02']::text[],false,'{"seq":17,"concept":"K6-2-u5-C2","difficulty":3,"kind":"ox","stem":"디지털 기기에서는 문자 언어도 전통적인 특징과 다른 모습을 보이기도 해요.","answer":"O","reason_options":[{"t":"정보 통신 기술의 발달로 언어가 매체 환경에 따라 다르게 나타나기도 하기 때문에","correct":true},{"t":"문자 언어는 어떤 매체에서든 반드시 같은 모습이기 때문에","mis":"K6-2-u5-X02"}],"mis":"K6-2-u5-X02","explanation":["문자 언어는 시각적인 기호예요.","디지털 기기에서는 전통적인 특징과 다른 특징을 보이기도 해요.","그래서 매체에 따라 어떻게 나타나는지 살펴봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_review_c#18','kor',6,2,'u5','','tb_g6_2_kor_u5_review_c','unit_review','K6-2-u5-C10',3,'error','auto','친구들이 공익 광고의 표현 효과를 정리했어요. 표현 효과를 알맞게 정리하지 못한 친구는 누구인가요?',ARRAY['K6-2-u5-X13','K6-2-u5-X09','K6-2-u5-X11']::text[],false,'{"seq":18,"concept":"K6-2-u5-C10","difficulty":3,"kind":"error","stem":"친구들이 공익 광고의 표현 효과를 정리했어요. 표현 효과를 알맞게 정리하지 못한 친구는 누구인가요?","options":[{"t":"친구 2 — 「음악이 계속 크게 나오고 자막이 화면을 가득 채워서 좋은 광고야.」","correct":true,"mis_target":"K6-2-u5-X13"},{"t":"친구 1 — 「중요한 말을 자막으로 다시 보여 주어 내용을 기억하기 쉬워.」","mis":"K6-2-u5-X09"},{"t":"친구 3 — 「아이의 목소리와 장면을 함께 보여 주어 마음에 와닿아.」","mis":"K6-2-u5-X11"}],"explanation":["친구 1과 친구 3은 표현이 무엇을 돕는지 말했어요.","음악과 자막이 많다고 좋은 것은 아니에요.","오히려 무엇이 중요한지 흐려질 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_review_c#19','kor',6,2,'u5','','tb_g6_2_kor_u5_review_c','unit_review','K6-2-u5-C14',3,'error','auto','독자를 고려하지 않은 경우를 찾아보았어요. 독자를 고려하지 않은 것은 무엇인가요?',ARRAY['K6-2-u5-X24','K6-2-u5-X19','K6-2-u5-X23']::text[],false,'{"seq":19,"concept":"K6-2-u5-C14","difficulty":3,"kind":"error","stem":"독자를 고려하지 않은 경우를 찾아보았어요. 독자를 고려하지 않은 것은 무엇인가요?","options":[{"t":"초등학생에게 쓰는 글에 「심폐 지구력」 같은 어려운 낱말을 풀이 없이 쓴다.","correct":true,"mis_target":"K6-2-u5-X24"},{"t":"동생에게 초대장을 쓸 때 쉬운 표현을 쓴다.","mis":"K6-2-u5-X19"},{"t":"그래프를 좋아하는 학생들에게 조사 결과를 그래프로 보여 준다.","mis":"K6-2-u5-X23"}],"explanation":["독자가 모르는 낱말은 뜻이 전해지지 않아요.","쉬운 표현과 알맞은 자료는 독자를 고려한 거예요.","어려운 낱말이 글을 훌륭하게 만드는 것은 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_review_c#20','kor',6,2,'u5','','tb_g6_2_kor_u5_review_c','unit_review','K6-2-u5-C20',3,'error','auto','기사문 초안의 문장들이에요. 확인한 사실이 아니라 쓴 사람의 생각을 사실처럼 쓴 문장은 무엇인가요?',ARRAY['K6-2-u5-X26','K6-2-u5-X27']::text[],false,'{"seq":20,"concept":"K6-2-u5-C20","difficulty":3,"kind":"error","stem":"기사문 초안의 문장들이에요. 확인한 사실이 아니라 쓴 사람의 생각을 사실처럼 쓴 문장은 무엇인가요?","options":[{"t":"「모든 학생이 캠프를 최고의 행사라고 생각했다.」","correct":true,"mis_target":"K6-2-u5-X26"},{"t":"「1~2학년 학생들은 미술실에서 그림 작가 체험을 했다.」","mis":"K6-2-u5-X27"},{"t":"「3학년 박○○ 학생은 신기하고 재미있었다고 소감을 전했다.」","mis":"K6-2-u5-X27"}],"explanation":["모든 학생의 생각을 확인할 수는 없어요.","쓴 사람의 생각을 사실처럼 쓴 문장이에요.","체험한 일과 학생이 직접 한 말은 확인한 사실이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_review_c#21','kor',6,2,'u5','','tb_g6_2_kor_u5_review_c','unit_review','K6-2-u5-C11',3,'error','auto','친구들이 「수월봉 화산 쇄설층」의 장면별 표현 방법을 정리했어요. 잘못 정리한 친구는 누구인가요?',ARRAY['K6-2-u5-X14','K6-2-u5-X12']::text[],false,'{"seq":21,"concept":"K6-2-u5-C11","difficulty":3,"kind":"error","stem":"친구들이 「수월봉 화산 쇄설층」의 장면별 표현 방법을 정리했어요. 잘못 정리한 친구는 누구인가요?","options":[{"t":"친구 3 — 「장면 1에서는 분화구 추정 위치를 글과 그림으로 보여 줘.」","correct":true,"mis_target":"K6-2-u5-X14"},{"t":"친구 1 — 「장면 2에서는 해설자의 말을 화면에 문자로 다시 보여 줘.」","mis":"K6-2-u5-X12"},{"t":"친구 2 — 「장면 5에서는 해설자의 음성 설명 없이 자막으로 보여 줘.」","mis":"K6-2-u5-X12"}],"explanation":["장면 1은 파도 소리와 음악 속에 제목이 나타나요.","분화구 추정 위치를 글과 그림으로 보여 주는 것은 장면 4예요.","장면마다 쓴 방법을 바르게 확인해요."],"asset":{"type":"passage","lines":["장면 1 잔잔한 파도 소리와 음악이 들리며 제목이 나타난다.","장면 2 해안 절벽을 다양한 각도로 보여 주고, 해설자의 말을 화면에 문자로 다시 보여 준다.","장면 3 새로운 탄생과 발견을 강조하려고 긴장감이 느껴지는 음악을 사용한다.","장면 4 분화구 추정 위치와 주변 지역을 글과 그림으로 표현한다.","장면 5 대상의 이름과 설명을 해설자의 음성 설명 없이 자막으로 보여 준다."],"numbered":false,"title":"「수월봉 화산 쇄설층」(『국어』 231쪽 장면 설명)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_review_c#22','kor',6,2,'u5','','tb_g6_2_kor_u5_review_c','unit_review','K6-2-u5-C21',3,'sa','auto','『국어』 245쪽 예시 답안에서 기삿거리가 「에너지 절약 생활화」일 때 정한 자료 수집 방법은 학생을 대상으로 한 무엇인가요? 네 글자로 쓰세요.','{}'::text[],false,'{"seq":22,"concept":"K6-2-u5-C21","difficulty":3,"kind":"sa","stem":"『국어』 245쪽 예시 답안에서 기삿거리가 「에너지 절약 생활화」일 때 정한 자료 수집 방법은 학생을 대상으로 한 무엇인가요? 네 글자로 쓰세요.","answer":["설문 조사","설문조사"],"explanation":["필요한 자료는 학생의 생각을 나타내는 자료예요.","학생의 생각을 알려면 학생에게 물어봐요.","그래서 설문 조사를 실시해요."],"mis":"K6-2-u5-X27"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_review_c#23','kor',6,2,'u5','','tb_g6_2_kor_u5_review_c','unit_review','K6-2-u5-C10',4,'essay','teacher','공익 광고 하나를 떠올려 제목, 주제, 언어의 표현 방법, 언어의 표현 효과를 정리해 쓰세요. 떠오르지 않으면 「아동 안전 ― 운전자가 보호자 ―」로 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K6-2-u5-C10","difficulty":4,"kind":"essay","stem":"공익 광고 하나를 떠올려 제목, 주제, 언어의 표현 방법, 언어의 표현 효과를 정리해 쓰세요. 떠오르지 않으면 「아동 안전 ― 운전자가 보호자 ―」로 쓰세요.","answer_guide":{"answer":"예: 제목 — 아동 안전 ― 운전자가 보호자 ―. 주제 — 아동의 안전을 위해 운전하는 사람이 차량 안전을 생각해야 한다. 표현 방법 — 「도로에서는 운전자가 보호자입니다.」라는 음성 언어와 「운전면허는 보행자 보호 면허」라는 문자 언어를 함께 썼다. 표현 효과 — 말로 설명한 내용을 글자로 정리하고 강조해 운전자의 책임을 또렷하게 기억하게 한다.","scoring_points":["제목과 주제를 썼는가","문자 언어·음성 언어의 표현 방법을 썼는가","그 표현이 무엇을 돕는지 효과를 썼는가"]},"explanation":["제목과 주제를 먼저 정리해요.","쓰인 언어 표현을 찾아요.","그 표현이 내용 전달을 어떻게 돕는지 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_review_c#24','kor',6,2,'u5','','tb_g6_2_kor_u5_review_c','unit_review','K6-2-u5-C20',4,'essay','teacher','기사문을 쓸 때 독자가 믿고 읽을 수 있도록 지켜야 할 점을 두 가지 쓰고, 그 까닭을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K6-2-u5-C20","difficulty":4,"kind":"essay","stem":"기사문을 쓸 때 독자가 믿고 읽을 수 있도록 지켜야 할 점을 두 가지 쓰고, 그 까닭을 쓰세요.","answer_guide":{"answer":"예: 첫째, 직접 보고 듣고 조사한 사실만 쓰고 확인하지 않은 소문이나 내 느낌을 사실처럼 쓰지 않는다. 둘째, 사진이나 조사 결과 같은 자료를 넣을 때에는 출처를 밝힌다. 기사문은 독자가 사실이라고 믿고 읽는 글이기 때문이다.","scoring_points":["사실만 쓰기(소문·느낌을 사실처럼 쓰지 않기)를 썼는가","자료의 출처 밝히기를 썼는가","까닭을 독자의 믿음과 이어 썼는가"]},"explanation":["기사문은 사실을 전하는 글이에요.","자료에는 출처를 밝혀요.","독자는 기사문을 사실이라고 믿고 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_review_c#25','kor',6,2,'u5','','tb_g6_2_kor_u5_review_c','unit_review','K6-2-u5-C6',4,'essay','teacher','학급 친구들에게 재능 발표회 일정을 알리려고 해요. 문자 언어와 음성 언어를 어떻게 함께 쓰면 좋을지 이 단원에서 배운 언어의 특성과 이어 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K6-2-u5-C6","difficulty":4,"kind":"essay","stem":"학급 친구들에게 재능 발표회 일정을 알리려고 해요. 문자 언어와 음성 언어를 어떻게 함께 쓰면 좋을지 이 단원에서 배운 언어의 특성과 이어 쓰세요.","answer_guide":{"answer":"예: 아침 시간에 말로 일정을 알려 주면서 중요한 시각과 장소는 목소리를 크고 또박또박하게 강조하겠다. 그리고 같은 내용을 학급 알림판에 글로 써 붙여, 말을 놓친 친구도 나중에 다시 보며 확인할 수 있게 하겠다. 두 언어가 서로 보완하기 때문이다.","scoring_points":["음성 언어를 쓰는 방법과 까닭을 썼는가","문자 언어를 쓰는 방법과 까닭을 썼는가","두 언어가 서로 보완한다는 점으로 정리했는가"]},"explanation":["말은 생생하게, 중요한 곳은 목소리로 강조해요.","글은 남아 다시 볼 수 있어요.","함께 쓰면 서로 보완해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_review_d#1','kor',6,2,'u5','','tb_g6_2_kor_u5_review_d','unit_review','K6-2-u5-C1',1,'mc','auto','다음 가운데 문자 언어로 정보를 전달받는 경우는 무엇인가요?',ARRAY['K6-2-u5-X01']::text[],false,'{"seq":1,"concept":"K6-2-u5-C1","difficulty":1,"kind":"mc","stem":"다음 가운데 문자 언어로 정보를 전달받는 경우는 무엇인가요?","options":[{"t":"안내장을 읽으며 행사 장소를 확인한다","correct":true},{"t":"선생님의 안내 말씀을 듣는다","mis":"K6-2-u5-X01"},{"t":"오디오 북에서 전문가의 설명을 듣는다","mis":"K6-2-u5-X01"},{"t":"전화로 길을 물어본다","mis":"K6-2-u5-X01"}],"explanation":["글자로 나타낸 안내장을 읽는 것은 문자 언어예요.","말씀을 듣거나 오디오 북을 듣는 것은 음성 언어예요.","전화로 묻는 것도 음성 언어예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_review_d#2','kor',6,2,'u5','','tb_g6_2_kor_u5_review_d','unit_review','K6-2-u5-C4',1,'blank','auto','『국어』 250쪽 (3)의 정리예요. 「문자 언어는 시간과 장소에 제한 없이 상대에게 내용을 전달할 수 있으며 오랫동안 정보를 (    )할 수 있다.」 빈칸에 알맞은 낱말은 무엇인가요?',ARRAY['K6-2-u5-X07','K6-2-u5-X06']::text[],false,'{"seq":2,"concept":"K6-2-u5-C4","difficulty":1,"kind":"blank","stem":"『국어』 250쪽 (3)의 정리예요. 「문자 언어는 시간과 장소에 제한 없이 상대에게 내용을 전달할 수 있으며 오랫동안 정보를 (    )할 수 있다.」 빈칸에 알맞은 낱말은 무엇인가요?","options":[{"t":"보존","correct":true},{"t":"삭제","mis":"K6-2-u5-X07"},{"t":"강조","mis":"K6-2-u5-X06"},{"t":"억양","mis":"K6-2-u5-X06"}],"explanation":["그림 ㉯는 문자 언어를 써요.","글로 쓴 내용은 오랫동안 남아요.","그래서 정보를 보존할 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_review_d#3','kor',6,2,'u5','','tb_g6_2_kor_u5_review_d','unit_review','K6-2-u5-C3',1,'ox','auto','『국어』 230쪽 4번에 따르면 신문은 인쇄 매체예요.',ARRAY['K6-2-u5-X04']::text[],false,'{"seq":3,"concept":"K6-2-u5-C3","difficulty":1,"kind":"ox","stem":"『국어』 230쪽 4번에 따르면 신문은 인쇄 매체예요.","answer":"O","reason_options":[{"t":"신문은 문자 언어를 기반으로 표, 그림, 사진을 함께 써서 정보를 전하기 때문에","correct":true},{"t":"신문은 음성 언어를 기반으로 소리와 음악을 쓰기 때문에","mis":"K6-2-u5-X04"}],"mis":"K6-2-u5-X04","explanation":["인쇄 매체에는 책, 신문 같은 것이 있어요.","문자 언어가 바탕이에요.","소리와 음악을 쓰는 것은 음성 매체예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_review_d#4','kor',6,2,'u5','','tb_g6_2_kor_u5_review_d','unit_review','K6-2-u5-C4',1,'mc','auto','공지문, 안내문, 설명서처럼 여러 사람이 같은 정보를 정확하게 나누어 가져야 할 때 알맞은 언어는 무엇인가요?',ARRAY['K6-2-u5-X07','K6-2-u5-X05']::text[],false,'{"seq":4,"concept":"K6-2-u5-C4","difficulty":1,"kind":"mc","stem":"공지문, 안내문, 설명서처럼 여러 사람이 같은 정보를 정확하게 나누어 가져야 할 때 알맞은 언어는 무엇인가요?","options":[{"t":"문자 언어","correct":true},{"t":"음성 언어","mis":"K6-2-u5-X07"},{"t":"몸짓","mis":"K6-2-u5-X05"}],"explanation":["여러 사람이 같은 정보를 정확하게 공유해야 해요.","문자 언어는 한 번 제시된 내용이 사라지지 않아요.","반복해서 똑같이 확인할 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_review_d#5','kor',6,2,'u5','','tb_g6_2_kor_u5_review_d','unit_review','K6-2-u5-C5',1,'mc','auto','「선생님의 안내 말씀」을 듣고 친구가 「궁금한 점을 기억하기가 어려워. 그래서 주의 깊게 들어야 해.」라고 했어요. 그렇게 말한 까닭이 되는 음성 언어의 특성은 무엇인가요?',ARRAY['K6-2-u5-X06','K6-2-u5-X02','K6-2-u5-X07']::text[],false,'{"seq":5,"concept":"K6-2-u5-C5","difficulty":1,"kind":"mc","stem":"「선생님의 안내 말씀」을 듣고 친구가 「궁금한 점을 기억하기가 어려워. 그래서 주의 깊게 들어야 해.」라고 했어요. 그렇게 말한 까닭이 되는 음성 언어의 특성은 무엇인가요?","options":[{"t":"말이 끝나면서 소리가 사라진다","correct":true},{"t":"글자 크기로 강조할 수 있다","mis":"K6-2-u5-X06"},{"t":"오랫동안 보존된다","mis":"K6-2-u5-X02"},{"t":"천천히 생각하며 고쳐 쓸 수 있다","mis":"K6-2-u5-X07"}],"explanation":["말은 끝나면 소리가 사라져요.","그래서 다시 확인하기 어려워요.","집중해서 듣고 메모하며 들어요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"선생님께서 재능 발표회에 대하여 말씀해 주셨어. 중요한 내용일 때에는 목소리를 크게 하셨어."},{"who":"친구 2","text":"그런데 궁금한 점을 기억하기가 어려워. 그래서 주의 깊게 들어야 해."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_review_d#6','kor',6,2,'u5','','tb_g6_2_kor_u5_review_d','unit_review','K6-2-u5-C19',1,'blank','auto','『국어』 244쪽의 정리예요. 「기사문의 제목은 기사 내용을 (    )하게 드러낸다.」 빈칸에 알맞은 낱말은 무엇인가요?',ARRAY['K6-2-u5-X31','K6-2-u5-X28']::text[],false,'{"seq":6,"concept":"K6-2-u5-C19","difficulty":1,"kind":"blank","stem":"『국어』 244쪽의 정리예요. 「기사문의 제목은 기사 내용을 (    )하게 드러낸다.」 빈칸에 알맞은 낱말은 무엇인가요?","options":[{"t":"간결","correct":true},{"t":"화려","mis":"K6-2-u5-X31"},{"t":"복잡","mis":"K6-2-u5-X28"}],"explanation":["제목은 기사 내용을 짧고 또렷하게 드러내요.","그래서 「간결하게 드러낸다」라고 정리해요.","화려하게 부풀리지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_review_d#7','kor',6,2,'u5','','tb_g6_2_kor_u5_review_d','unit_review','K6-2-u5-C14',1,'mc','auto','독자를 고려한다는 것의 뜻으로 알맞은 것은 무엇인가요?',ARRAY['K6-2-u5-X43','K6-2-u5-X24','K6-2-u5-X20']::text[],false,'{"seq":7,"concept":"K6-2-u5-C14","difficulty":1,"kind":"mc","stem":"독자를 고려한다는 것의 뜻으로 알맞은 것은 무엇인가요?","options":[{"t":"글을 읽는 사람의 관점에서 생각하거나 헤아려 보는 것","correct":true},{"t":"글쓴이가 하고 싶은 말만 쓰는 것","mis":"K6-2-u5-X43"},{"t":"어려운 낱말을 골라 멋지게 쓰는 것","mis":"K6-2-u5-X24"},{"t":"독자가 좋아하는 말만 골라 쓰는 것","mis":"K6-2-u5-X20"}],"explanation":["독자는 글을 읽는 사람이에요.","독자의 흥미, 배경지식, 수준을 두루 헤아려요.","좋아하는 말만 쓰는 것과는 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_review_d#8','kor',6,2,'u5','','tb_g6_2_kor_u5_review_d','unit_review','K6-2-u5-C25',1,'mc','auto','「맑아요」의 바른 발음은 무엇인가요?',ARRAY['K6-2-u5-X38','K6-2-u5-X39']::text[],false,'{"seq":8,"concept":"K6-2-u5-C25","difficulty":1,"kind":"mc","stem":"「맑아요」의 바른 발음은 무엇인가요?","options":[{"t":"[말가요]","correct":true},{"t":"[막아요]","mis":"K6-2-u5-X38"},{"t":"[마가요]","mis":"K6-2-u5-X39"},{"t":"[막까요]","mis":"K6-2-u5-X38"}],"explanation":["겹받침 ㄺ 뒤에 모음이 와요.","두 소리가 다 나고 ㄱ은 뒤 글자로 넘어가요.","그래서 [말가요]로 발음해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_review_d#9','kor',6,2,'u5','','tb_g6_2_kor_u5_review_d','unit_review','K6-2-u5-C9',2,'match','auto','「아동 안전 ― 운전자가 보호자 ―」에 쓰인 표현과 그 갈래를 알맞게 이으세요.','{}'::text[],false,'{"seq":9,"concept":"K6-2-u5-C9","difficulty":2,"kind":"match","stem":"「아동 안전 ― 운전자가 보호자 ―」에 쓰인 표현과 그 갈래를 알맞게 이으세요.","pairs":[{"l":"「도로에서는 운전자가 보호자입니다.」라는 설명","r":"음성 언어"},{"l":"「운전면허는 보행자 보호 면허」라는 글자","r":"문자 언어"},{"l":"영상에 함께 나오는 음악","r":"언어와 함께 쓰는 소리 요소"}],"mis":"K6-2-u5-X01","explanation":["목소리로 한 설명은 음성 언어예요.","화면에 보이는 글자는 문자 언어예요.","음악은 언어와 어우러져 내용을 전하는 요소예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_review_d#10','kor',6,2,'u5','','tb_g6_2_kor_u5_review_d','unit_review','K6-2-u5-C12',2,'mc','auto','『국어』 231쪽에서 「음성, 문자, 소리, 음악, 그림, 동영상과 같은 요소를 생각하며 살펴보면 표현 효과를 알 수 있어요.」라고 했어요. 이 말에 맞게 영상을 감상한 친구는 누구인가요?',ARRAY['K6-2-u5-X15','K6-2-u5-X13','K6-2-u5-X16']::text[],false,'{"seq":10,"concept":"K6-2-u5-C12","difficulty":2,"kind":"mc","stem":"『국어』 231쪽에서 「음성, 문자, 소리, 음악, 그림, 동영상과 같은 요소를 생각하며 살펴보면 표현 효과를 알 수 있어요.」라고 했어요. 이 말에 맞게 영상을 감상한 친구는 누구인가요?","options":[{"t":"「장면 4는 분화구 위치를 글과 그림으로 보여 주어 한눈에 알 수 있었어.」라고 말한 친구","correct":true},{"t":"「영상이 그냥 멋있었고 재미있었어.」라고 말한 친구","mis":"K6-2-u5-X15"},{"t":"「자막이 몇 번 나왔는지 세어 보았어.」라고 말한 친구","mis":"K6-2-u5-X13"},{"t":"「내 느낌과 다른 친구는 영상을 잘못 본 거야.」라고 말한 친구","mis":"K6-2-u5-X16"}],"explanation":["표현 요소를 찾고 그것이 무엇을 돕는지 말해요.","글과 그림이 위치를 한눈에 알게 도왔어요.","느낌만 말하거나 개수를 세는 것은 표현 효과가 아니에요."],"asset":{"type":"passage","lines":["장면 1 잔잔한 파도 소리와 음악이 들리며 제목이 나타난다.","장면 2 해안 절벽을 다양한 각도로 보여 주고, 해설자의 말을 화면에 문자로 다시 보여 준다.","장면 3 새로운 탄생과 발견을 강조하려고 긴장감이 느껴지는 음악을 사용한다.","장면 4 분화구 추정 위치와 주변 지역을 글과 그림으로 표현한다.","장면 5 대상의 이름과 설명을 해설자의 음성 설명 없이 자막으로 보여 준다."],"numbered":false,"title":"「수월봉 화산 쇄설층」(『국어』 231쪽 장면 설명)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_review_d#11','kor',6,2,'u5','','tb_g6_2_kor_u5_review_d','unit_review','K6-2-u5-C6',2,'mc','auto','긴 설명이 필요한 경우 문자 언어를 고르는 까닭으로 가장 알맞은 것은 무엇인가요?',ARRAY['K6-2-u5-X03','K6-2-u5-X06','K6-2-u5-X10']::text[],false,'{"seq":11,"concept":"K6-2-u5-C6","difficulty":2,"kind":"mc","stem":"긴 설명이 필요한 경우 문자 언어를 고르는 까닭으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"천천히 생각하며 읽고, 필요할 때 다시 볼 수 있어서","correct":true},{"t":"글이 말보다 언제나 더 뛰어나서","mis":"K6-2-u5-X03"},{"t":"목소리로 감정을 실감 나게 전할 수 있어서","mis":"K6-2-u5-X06"},{"t":"빠르고 편하기만 하면 되어서","mis":"K6-2-u5-X10"}],"explanation":["긴 설명은 한 번 듣고 기억하기 어려워요.","글로 쓰면 천천히 읽고 다시 볼 수 있어요.","어느 언어가 뛰어나서가 아니라 상황에 알맞아서 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_review_d#12','kor',6,2,'u5','','tb_g6_2_kor_u5_review_d','unit_review','K6-2-u5-C18',2,'mc','auto','『국어』 251쪽 2번을 바탕으로 기사문을 쓰는 방법을 바르게 말한 것은 무엇인가요?',ARRAY['K6-2-u5-X27','K6-2-u5-X26','K6-2-u5-X30']::text[],false,'{"seq":12,"concept":"K6-2-u5-C18","difficulty":2,"kind":"mc","stem":"『국어』 251쪽 2번을 바탕으로 기사문을 쓰는 방법을 바르게 말한 것은 무엇인가요?","options":[{"t":"사실을 확인하여 정확한 문장으로 표현한다","correct":true},{"t":"확인하지 않은 소문도 재미있으면 쓴다","mis":"K6-2-u5-X27"},{"t":"기자의 느낌을 사실처럼 쓴다","mis":"K6-2-u5-X26"},{"t":"독자가 관심 없는 일을 골라 쓴다","mis":"K6-2-u5-X30"}],"explanation":["기사문은 사실에 기반해 객관적으로 써요.","사실을 확인하고 정확한 문장으로 표현해요.","독자의 관심도 함께 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_review_d#13','kor',6,2,'u5','','tb_g6_2_kor_u5_review_d','unit_review','K6-2-u5-C17',2,'mc','auto','「계단을 안전하게 이용합시다」에서 안전 수칙을 별표 기호로 나누어 보여 준 효과로 알맞은 것은 무엇인가요?',ARRAY['K6-2-u5-X13','K6-2-u5-X25','K6-2-u5-X24']::text[],false,'{"seq":13,"concept":"K6-2-u5-C17","difficulty":2,"kind":"mc","stem":"「계단을 안전하게 이용합시다」에서 안전 수칙을 별표 기호로 나누어 보여 준 효과로 알맞은 것은 무엇인가요?","options":[{"t":"수칙을 기억하기 쉬워 어린 동생들도 오래 기억할 수 있다","correct":true},{"t":"기호가 많을수록 좋은 글이 된다","mis":"K6-2-u5-X13"},{"t":"지킬 일만 쓰고 왜 지켜야 하는지는 빼도 된다","mis":"K6-2-u5-X25"},{"t":"어려운 낱말이 돋보인다","mis":"K6-2-u5-X24"}],"explanation":["『국어』 241쪽 6번에서 친구가 말한 효과예요.","수칙을 나누어 보여 주면 기억하기 쉬워요.","어린 동생들도 오래 기억할 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_review_d#14','kor',6,2,'u5','','tb_g6_2_kor_u5_review_d','unit_review','K6-2-u5-C19',2,'mc','auto','「희망초등학교, ‘전문가와 함께 하는 예술 진로 캠프’ 개최」의 본문 끝에 6학년 김○○ 학생과 3학년 박○○ 학생의 말을 넣은 까닭으로 가장 알맞은 것은 무엇인가요?',ARRAY['K6-2-u5-X27','K6-2-u5-X28','K6-2-u5-X05']::text[],false,'{"seq":14,"concept":"K6-2-u5-C19","difficulty":2,"kind":"mc","stem":"「희망초등학교, ‘전문가와 함께 하는 예술 진로 캠프’ 개최」의 본문 끝에 6학년 김○○ 학생과 3학년 박○○ 학생의 말을 넣은 까닭으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"캠프에 참여한 학생이 직접 한 말을 전해 생생하게 알리려고","correct":true},{"t":"기자가 지어낸 말을 넣어 기사에 재미를 더하려고","mis":"K6-2-u5-X27"},{"t":"학생의 말로 기사의 표제와 부제를 대신하려고","mis":"K6-2-u5-X28"},{"t":"참여한 학생들의 이름을 널리 자랑하려고","mis":"K6-2-u5-X05"}],"explanation":["기사문은 직접 보고 듣고 조사한 내용을 써요.","참여한 학생의 말을 그대로 옮겨 생생하게 전해요.","지어낸 말은 기사문에 쓸 수 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_review_d#15','kor',6,2,'u5','','tb_g6_2_kor_u5_review_d','unit_review','K6-2-u5-C22',2,'mc','auto','편지를 쓸 때 독자를 고려한 방법으로 가장 알맞은 것은 무엇인가요?',ARRAY['K6-2-u5-X34','K6-2-u5-X33','K6-2-u5-X36']::text[],false,'{"seq":15,"concept":"K6-2-u5-C22","difficulty":2,"kind":"mc","stem":"편지를 쓸 때 독자를 고려한 방법으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"편지를 받는 사람에게 알맞게 존칭을 쓰고 쓴 목적이 뚜렷하게 드러나게 쓴다","correct":true},{"t":"받는 사람이 누구든 상관없이 늘 같은 반말투로 쓴다","mis":"K6-2-u5-X34"},{"t":"첫인사와 끝인사, 쓴 날짜는 빼고 하고 싶은 말만 쓴다","mis":"K6-2-u5-X33"},{"t":"쓴 목적은 숨기고 꾸미는 말과 인사만 길게 쓴다","mis":"K6-2-u5-X36"}],"explanation":["편지의 독자는 받는 사람이에요.","받는 사람에게 알맞게 존칭을 써요.","쓴 목적이 뚜렷하게 드러나야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_review_d#16','kor',6,2,'u5','','tb_g6_2_kor_u5_review_d','unit_review','K6-2-u5-C7',2,'match','auto','『국어』 252쪽 스스로 확인하기에서 공부한 것과 설명을 알맞게 이으세요.','{}'::text[],false,'{"seq":16,"concept":"K6-2-u5-C7","difficulty":2,"kind":"match","stem":"『국어』 252쪽 스스로 확인하기에서 공부한 것과 설명을 알맞게 이으세요.","pairs":[{"l":"언어의 표현 특성","r":"음성 언어는 목소리의 크기나 억양으로 감정과 의도를 알 수 있다"},{"l":"언어의 표현 효과","r":"문자 언어는 시각적으로 내용을 쉽게 이해할 수 있도록 한다"},{"l":"독자를 고려해 글 쓰기","r":"독자의 수준에 맞게 쓰고 독자의 흥미와 관심을 생각한다"}],"mis":"K6-2-u5-X11","explanation":["표현 특성은 언어가 가진 기본 성질이에요.","표현 효과는 그 언어가 이해를 어떻게 돕는지예요.","독자를 고려한 글쓰기는 소단원 2에서 배웠어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_review_d#17','kor',6,2,'u5','','tb_g6_2_kor_u5_review_d','unit_review','K6-2-u5-C1',3,'mc','auto','『국어』 223쪽 (3)에서 친구들이 말한 경험 가운데 음성 언어로 정보를 이해한 경험은 무엇인가요?',ARRAY['K6-2-u5-X01']::text[],false,'{"seq":17,"concept":"K6-2-u5-C1","difficulty":3,"kind":"mc","stem":"『국어』 223쪽 (3)에서 친구들이 말한 경험 가운데 음성 언어로 정보를 이해한 경험은 무엇인가요?","options":[{"t":"직접 설명을 듣다가 모르는 내용을 다시 물어본 경험","correct":true},{"t":"문자 언어로 된 설명서를 보면서 청소기를 사용한 경험","mis":"K6-2-u5-X01"},{"t":"안내장 종이를 읽다가 이해하기 어려워 다시 한번 확인한 경험","mis":"K6-2-u5-X01"}],"explanation":["직접 설명을 듣는 것은 음성 언어예요.","모르는 내용을 그 자리에서 다시 물을 수 있어요.","설명서와 안내장은 문자 언어예요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"상황 ㉮와 같이 문자 언어로 된 설명서를 보면서 청소기를 사용한 경험이 있어."},{"who":"친구 2","text":"상황 ㉯와 같이 음성 언어로 책을 추천받은 적이 있어. 생생하게 설명을 들어서 좋았어."},{"who":"친구 3","text":"직접 설명을 듣다가 모르는 내용을 다시 물어본 경험이 있어."},{"who":"친구 4","text":"안내장 종이를 읽다가 이해하기 어려워 다시 한번 확인했던 경험이 있어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_review_d#18','kor',6,2,'u5','','tb_g6_2_kor_u5_review_d','unit_review','K6-2-u5-C9',3,'mc','auto','텔레비전 뉴스에서 현장 기자가 「지진 현장에 나와 있습니다. 많은 사람이 놀라고 있습니다.」라고 말하고, 화면에는 지진이 난 곳과 규모를 자막으로 보여 주었어요. 자막을 함께 보여 준 효과로 가장 알맞은 것은 무엇인가요?',ARRAY['K6-2-u5-X11','K6-2-u5-X05','K6-2-u5-X13']::text[],false,'{"seq":18,"concept":"K6-2-u5-C9","difficulty":3,"kind":"mc","stem":"텔레비전 뉴스에서 현장 기자가 「지진 현장에 나와 있습니다. 많은 사람이 놀라고 있습니다.」라고 말하고, 화면에는 지진이 난 곳과 규모를 자막으로 보여 주었어요. 자막을 함께 보여 준 효과로 가장 알맞은 것은 무엇인가요?","options":[{"t":"말을 놓쳐도 중요한 정보를 글자로 한눈에 다시 확인할 수 있다","correct":true},{"t":"자막이 있으니 기자의 목소리는 필요 없어진다","mis":"K6-2-u5-X11"},{"t":"자막을 넣으면 화면이 화려해져 시청자가 즐거워진다","mis":"K6-2-u5-X05"},{"t":"자막이 많을수록 뉴스가 정확해진다","mis":"K6-2-u5-X13"}],"explanation":["음성 언어는 생생하지만 금방 사라져요.","자막은 꼭 알아야 할 정보를 화면에 남겨요.","두 언어가 서로 보완해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_review_d#19','kor',6,2,'u5','','tb_g6_2_kor_u5_review_d','unit_review','K6-2-u5-C32',3,'mc','auto','『국어』 236쪽 글과 237쪽 글은 같은 운동장 놀이를 다루었어요. 그런데도 독자의 반응이 다른 까닭으로 가장 알맞은 것은 무엇인가요?',ARRAY['K6-2-u5-X22','K6-2-u5-X24','K6-2-u5-X43']::text[],false,'{"seq":19,"concept":"K6-2-u5-C32","difficulty":3,"kind":"mc","stem":"『국어』 236쪽 글과 237쪽 글은 같은 운동장 놀이를 다루었어요. 그런데도 독자의 반응이 다른 까닭으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"237쪽 글은 독자가 관심 있는 놀이 방법을 쉬운 낱말로 썼기 때문","correct":true},{"t":"237쪽 글이 더 길기 때문","mis":"K6-2-u5-X22"},{"t":"236쪽 글에 어려운 낱말이 있어서 더 훌륭하기 때문","mis":"K6-2-u5-X24"},{"t":"237쪽 글은 글쓴이가 조사한 내용만 썼기 때문","mis":"K6-2-u5-X43"}],"explanation":["소재는 같아도 독자를 생각한 정도가 달라요.","237쪽 글은 독자의 관심사와 낱말 수준을 고려했어요.","길이나 어려운 낱말이 반응을 바꾼 것이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_review_d#20','kor',6,2,'u5','','tb_g6_2_kor_u5_review_d','unit_review','K6-2-u5-C21',3,'mc','auto','『국어』 247쪽 수정하기 (2)에서 짝과 기사문을 바꾸어 읽고 할 일로 알맞은 것은 무엇인가요?',ARRAY['K6-2-u5-X22','K6-2-u5-X13']::text[],false,'{"seq":20,"concept":"K6-2-u5-C21","difficulty":3,"kind":"mc","stem":"『국어』 247쪽 수정하기 (2)에서 짝과 기사문을 바꾸어 읽고 할 일로 알맞은 것은 무엇인가요?","options":[{"t":"기사문에 대한 짝의 의견을 쓰고, 그 의견을 참고해 고쳐 쓸 내용을 정한다","correct":true},{"t":"짝의 글씨가 예쁜지만 평가한다","mis":"K6-2-u5-X22"},{"t":"짝의 의견은 듣지 않고 내 글을 그대로 둔다","mis":"K6-2-u5-X22"},{"t":"짝의 기사문에 자료를 될 수 있는 대로 많이 넣어 준다","mis":"K6-2-u5-X13"}],"explanation":["짝과 기사문을 바꾸어 읽어요.","짝의 의견을 쓰고 서로 나눠요.","의견을 참고해 고쳐 쓸 내용을 정하고 고쳐 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_review_d#21','kor',6,2,'u5','','tb_g6_2_kor_u5_review_d','unit_review','K6-2-u5-C12',3,'mc','auto','사회나 과학 시간에 본 영상에서 언어의 표현 효과를 찾을 때 살펴볼 점으로 가장 알맞은 것은 무엇인가요?',ARRAY['K6-2-u5-X05','K6-2-u5-X15']::text[],false,'{"seq":21,"concept":"K6-2-u5-C12","difficulty":3,"kind":"mc","stem":"사회나 과학 시간에 본 영상에서 언어의 표현 효과를 찾을 때 살펴볼 점으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"설명하는 말과 함께 연도나 이름 같은 중요한 내용을 문자로 보여 주는지","correct":true},{"t":"영상을 만든 사람이 누구이고 언제 올렸는지","mis":"K6-2-u5-X05"},{"t":"영상을 본 사람이 몇 명이고 좋아요가 몇 개인지","mis":"K6-2-u5-X05"},{"t":"어느 교과 시간에 본 영상이 가장 재미있었는지","mis":"K6-2-u5-X15"}],"explanation":["『국어』 234쪽 예시 답안을 떠올려요.","연도나 용액 이름을 문자로 알려 주어 이해하기 쉬웠어요.","만든 사람이나 본 사람 수는 표현 효과가 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_review_d#22','kor',6,2,'u5','','tb_g6_2_kor_u5_review_d','unit_review','K6-2-u5-C21',3,'error','auto','친구들이 학교 신문에 실을 기삿거리를 정했어요. 독자와 사실 확인을 생각하지 않고 고른 친구는 누구인가요?',ARRAY['K6-2-u5-X30']::text[],false,'{"seq":22,"concept":"K6-2-u5-C21","difficulty":3,"kind":"error","stem":"친구들이 학교 신문에 실을 기삿거리를 정했어요. 독자와 사실 확인을 생각하지 않고 고른 친구는 누구인가요?","options":[{"t":"친구 2 — 「내가 직접 확인할 수 없는 먼 나라 소문을 쓸래.」","correct":true,"mis_target":"K6-2-u5-X30"},{"t":"친구 1 — 「친구들이 관심을 두는 우리 학교 행사를 쓸래.」","mis":"K6-2-u5-X30"},{"t":"친구 3 — 「우리 주변에서 경험할 수 있는 에너지 절약을 쓸래.」","mis":"K6-2-u5-X30"}],"explanation":["기삿거리는 독자가 관심을 두는 일이어야 해요.","직접 보고 듣고 확인할 수 있는 일이어야 해요.","확인할 수 없는 소문은 기삿거리로 알맞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_review_d#23','kor',6,2,'u5','','tb_g6_2_kor_u5_review_d','unit_review','K6-2-u5-C2',4,'essay','teacher','「말은 언제나 사라지고, 글은 언제나 남는다.」라고 말한 친구에게, 매체 환경에 따라 달라지는 예를 들어 알맞게 고쳐 말해 주세요.','{}'::text[],false,'{"seq":23,"concept":"K6-2-u5-C2","difficulty":4,"kind":"essay","stem":"「말은 언제나 사라지고, 글은 언제나 남는다.」라고 말한 친구에게, 매체 환경에 따라 달라지는 예를 들어 알맞게 고쳐 말해 주세요.","answer_guide":{"answer":"예: 말은 보통 끝나면 사라지지만, 스마트폰의 음성 메모처럼 녹음하면 기록으로 남길 수 있어. 글도 보통 오래 남지만 디지털 기기에서는 전통적인 특징과 다른 모습을 보이기도 해. 그러니 「언제나」라고 외우기보다 매체에 따라 어떻게 되는지 살펴봐야 해.","scoring_points":["음성 언어도 남길 수 있는 예를 들었는가","문자 언어도 매체에 따라 달라짐을 썼는가","특성은 기본 성질이라는 점으로 정리했는가"]},"explanation":["특성은 보통 그렇다는 기본 성질이에요.","매체를 쓰면 말도 남고, 글도 달라질 수 있어요.","매체에 따라 어떻게 되는지 살펴봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_review_d#24','kor',6,2,'u5','','tb_g6_2_kor_u5_review_d','unit_review','K6-2-u5-C14',4,'essay','teacher','친구가 쓴 기사문을 『국어』 247쪽 수정하기 (1)의 네 물음(기삿거리, 제목, 본문의 말, 자료)으로 점검할 때, 각 물음이 독자의 무엇을 고려하는 것인지 두 가지 이상 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K6-2-u5-C14","difficulty":4,"kind":"essay","stem":"친구가 쓴 기사문을 『국어』 247쪽 수정하기 (1)의 네 물음(기삿거리, 제목, 본문의 말, 자료)으로 점검할 때, 각 물음이 독자의 무엇을 고려하는 것인지 두 가지 이상 쓰세요.","answer_guide":{"answer":"예: 관심을 끌 만한 기삿거리인지 보는 것은 독자의 관심을 고려하는 것이다. 이해하기 쉬운 말로 본문을 썼는지 보는 것은 독자의 수준을 고려하는 것이다. 독자의 이해를 돕는 자료를 적절하게 썼는지 보는 것은 독자가 내용을 쉽게 이해하도록 돕는 것이다.","scoring_points":["물음 두 가지 이상을 골랐는가","물음마다 독자의 관심·수준·이해 가운데 무엇을 고려하는지 이었는가","독자의 관점에서 설명했는가"]},"explanation":["수정하기 물음은 모두 독자를 향해 있어요.","관심, 수준, 이해를 살펴요.","고쳐 쓰기도 독자에게 더 잘 닿게 하는 일이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u5_review_d#25','kor',6,2,'u5','','tb_g6_2_kor_u5_review_d','unit_review','K6-2-u5-C12',4,'essay','teacher','이 단원을 마치며 『국어』 252쪽 스스로 확인하기의 세 물음 가운데 가장 자신 있는 것과 더 노력할 것을 하나씩 골라, 까닭과 노력할 방법을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K6-2-u5-C12","difficulty":4,"kind":"essay","stem":"이 단원을 마치며 『국어』 252쪽 스스로 확인하기의 세 물음 가운데 가장 자신 있는 것과 더 노력할 것을 하나씩 골라, 까닭과 노력할 방법을 쓰세요.","answer_guide":{"answer":"예: 나는 「문자 언어와 음성 언어의 표현 특성을 알고 있나요?」가 가장 자신 있다. 길 찾기 상황과 안내 말씀으로 두 언어의 다른 점을 분명히 알게 되었기 때문이다. 「독자와 매체를 고려해 글을 쓸 수 있나요?」는 더 노력하겠다. 글을 쓰기 전에 읽을 사람이 무엇에 관심이 있는지 먼저 물어보고 쓰겠다.","scoring_points":["자신 있는 물음과 까닭을 썼는가","더 노력할 물음을 골랐는가","노력할 방법을 구체적으로 썼는가"]},"explanation":["세 물음으로 단원 공부를 돌아봐요.","자신 있는 것은 까닭을 들어요.","더 노력할 것은 방법을 구체적으로 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
